  token         TEXT NOT NULL UNIQUE CHECK (token IS NULL OR length(token) BETWEEN 1 AND 200),
  registered_at INTEGER NOT NULL
) STRICT;
CREATE TABLE channels (
  seq                     INTEGER PRIMARY KEY,
  id                      TEXT NOT NULL UNIQUE CHECK (id IS NULL OR length(id) BETWEEN 1 AND 80),
  request_id              TEXT NOT NULL REFERENCES recruitment_requests(id) ON DELETE RESTRICT,
  player_id               TEXT NOT NULL CHECK (player_id IS NULL OR length(player_id) BETWEEN 1 AND 80),
  player_name             TEXT CHECK (player_name IS NULL OR length(player_name) BETWEEN 0 AND 200),
  org_id                  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name                TEXT NOT NULL CHECK (org_name IS NULL OR length(org_name) BETWEEN 0 AND 200),
  org_verified            INTEGER CHECK (org_verified IS NULL OR org_verified IN (0, 1)),
  scout_name              TEXT CHECK (scout_name IS NULL OR length(scout_name) BETWEEN 0 AND 200),
  scout_role              TEXT CHECK (scout_role IS NULL OR length(scout_role) BETWEEN 0 AND 200),
  counterparty            TEXT NOT NULL CHECK (counterparty IN ('player', 'guardian')),
  guardian_id             TEXT CHECK (guardian_id IS NULL OR length(guardian_id) BETWEEN 1 AND 80),
  created_at              INTEGER NOT NULL,
  last_activity_at        INTEGER NOT NULL,
  read_by_org_at          INTEGER,
  read_by_counterparty_at INTEGER,
  CHECK (last_activity_at >= created_at)
) STRICT;
CREATE TABLE messages (
  seq              INTEGER PRIMARY KEY,
  id               TEXT NOT NULL UNIQUE CHECK (id IS NULL OR length(id) BETWEEN 1 AND 80),
  channel_id       TEXT NOT NULL REFERENCES channels(id) ON DELETE CASCADE,
  position         INTEGER NOT NULL CHECK (position >= 0),
  created_at       INTEGER NOT NULL,
  sender_kind      TEXT NOT NULL CHECK (sender_kind IN ('player', 'guardian', 'org_user')),
  sender_user_id   TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  sender_person_id TEXT CHECK (sender_person_id IS NULL OR length(sender_person_id) BETWEEN 1 AND 80),
  sender_name      TEXT CHECK (sender_name IS NULL OR length(sender_name) BETWEEN 0 AND 200),
  text             TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 4000),
  client_msg_id    TEXT CHECK (client_msg_id IS NULL OR length(client_msg_id) BETWEEN 1 AND 64),
  CHECK ((sender_kind = 'org_user' AND sender_user_id IS NOT NULL AND sender_person_id IS NULL)
      OR (sender_kind <> 'org_user' AND sender_person_id IS NOT NULL AND sender_user_id IS NULL))
) STRICT;
CREATE TABLE message_attachments (
  message_id    TEXT PRIMARY KEY REFERENCES messages(id) ON DELETE CASCADE,
  kind          TEXT NOT NULL CHECK (kind IN ('clip', 'trial_report')),
  media_id      TEXT CHECK (media_id IS NULL OR length(media_id) BETWEEN 1 AND 80),
  title         TEXT CHECK (title IS NULL OR length(title) BETWEEN 0 AND 300),
  url           TEXT CHECK (url IS NULL OR length(url) BETWEEN 0 AND 2000),
  verified_clip INTEGER CHECK (verified_clip IS NULL OR verified_clip IN (0, 1)),
  report_id     TEXT CHECK (report_id IS NULL OR length(report_id) BETWEEN 1 AND 80),
  org_name      TEXT CHECK (org_name IS NULL OR length(org_name) BETWEEN 0 AND 200),
  summary       TEXT CHECK (summary IS NULL OR length(summary) BETWEEN 0 AND 500),
  CHECK ((kind = 'clip' AND media_id IS NOT NULL AND verified_clip IS NOT NULL AND report_id IS NULL AND org_name IS NULL AND summary IS NULL)
      OR (kind = 'trial_report' AND report_id IS NOT NULL AND media_id IS NULL AND title IS NULL AND url IS NULL AND verified_clip IS NULL))
) STRICT;
CREATE TABLE blocks (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                        TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  org_id                           TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  by_kind                          TEXT NOT NULL CHECK (by_kind IN ('player','guardian')),
  reason                           TEXT NOT NULL CHECK (length(reason) <= 2000),
  created_at                       INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE reports (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  created_at                       INTEGER NOT NULL,
  by_kind                          TEXT NOT NULL CHECK (by_kind IN ('player','guardian','org_user','system')),
  by_id                            TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_org_id                        TEXT CHECK (by_org_id IS NULL OR length(by_org_id) <= 80 AND length(by_org_id) > 0),
  target_kind                      TEXT NOT NULL CHECK (target_kind IN ('club','scout','player')),
  target_org_id                    TEXT CHECK (target_org_id IS NULL OR length(target_org_id) <= 80 AND length(target_org_id) > 0),
  target_scout_name                TEXT CHECK (target_scout_name IS NULL OR length(target_scout_name) <= 200 AND length(target_scout_name) > 0),
  target_player_id                 TEXT CHECK (target_player_id IS NULL OR length(target_player_id) <= 200 AND length(target_player_id) > 0),
  reason                           TEXT NOT NULL CHECK (length(reason) <= 2000 AND length(reason) > 0),
  urgent                           INTEGER NOT NULL CHECK (urgent IN (0,1)),
  status                           TEXT NOT NULL CHECK (status IN ('pending_review','resolved')),
  outcome                          TEXT CHECK (outcome IS NULL OR length(outcome) <= 2000 AND length(outcome) > 0),
  resolved_at                      INTEGER,
  FOREIGN KEY (by_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (target_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK ((status = 'resolved') = (resolved_at IS NOT NULL)),
  CHECK (status = 'resolved' OR outcome IS NULL),
  CHECK ((by_kind = 'org_user') = (by_org_id IS NOT NULL))
) STRICT;
CREATE TABLE moderation_log (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  created_at                       INTEGER NOT NULL,
  context_kind                     TEXT NOT NULL CHECK (length(context_kind) <= 60 AND length(context_kind) > 0),
  context_player_id                TEXT CHECK (context_player_id IS NULL OR length(context_player_id) <= 80 AND length(context_player_id) > 0),
  context_org_id                   TEXT CHECK (context_org_id IS NULL OR length(context_org_id) <= 80 AND length(context_org_id) > 0),
  context_user_id                  TEXT CHECK (context_user_id IS NULL OR length(context_user_id) <= 80 AND length(context_user_id) > 0),
  context_channel_id               TEXT CHECK (context_channel_id IS NULL OR length(context_channel_id) <= 80 AND length(context_channel_id) > 0),
  context_request_id               TEXT CHECK (context_request_id IS NULL OR length(context_request_id) <= 80 AND length(context_request_id) > 0),
  context_trial_id                 TEXT CHECK (context_trial_id IS NULL OR length(context_trial_id) <= 80 AND length(context_trial_id) > 0),
  severity                         TEXT NOT NULL CHECK (severity IN ('contact','grooming')),
  excerpt                          TEXT NOT NULL CHECK (length(excerpt) <= 140),
  FOREIGN KEY (context_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (context_user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE moderation_flags (
  moderation_id TEXT NOT NULL,
  ord INTEGER NOT NULL CHECK (ord >= 0),
  flag TEXT NOT NULL CHECK (flag IN ('email', 'email_obfuscated', 'phone_number', 'phone_spelled', 'social_handle', 'social_platform', 'url', 'meet_off_platform', 'secrecy', 'personal_probing')),
  PRIMARY KEY (moderation_id, ord),
  FOREIGN KEY (moderation_id) REFERENCES moderation_log(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE org_notes (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                           TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  player_id                        TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  user_id                          TEXT NOT NULL CHECK (length(user_id) <= 80 AND length(user_id) > 0),
  scout_name                       TEXT NOT NULL CHECK (length(scout_name) <= 200),
  text                             TEXT NOT NULL CHECK (length(text) <= 2000 AND length(text) > 0),
  created_at                       INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ledger (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  occurred_at                      INTEGER NOT NULL,
  type                             TEXT NOT NULL CHECK (type IN ('view','save','shortlist','contact_request','contact_request_to_guardian','contact_accepted','contact_accepted_by_guardian','contact_declined','contact_declined_by_guardian','trial_request','trial_request_to_guardian','trial_accepted','trial_accepted_by_guardian','trial_declined','trial_declined_by_guardian','message','signing','released_by_club','staff_removed','org_blocked_by_player','org_blocked_by_guardian','account_transitioned','assessment_submitted','attendance_verified','clip_tagged','coach_affiliation_confirmed','level_review','matchday_logged','open_trial_posted','open_trial_registration','open_trial_registration_by_guardian','opportunity_application','passport_view','passport_recruitment_view','passport_share_created','passport_share_revoked','recruitment_room_created','transition_pack_view','trial_checkin','trial_report','box_assignment_created','box_assignment_cancelled','box_challenge_published','box_clip_saved','box_prefs_changed','box_result_invalidated','box_result_restored','combine_attempt_completed','combine_request_created','combine_request_completed','verification_decision','verification_root_approved')),
  player_id                        TEXT CHECK (player_id IS NULL OR length(player_id) <= 80 AND length(player_id) > 0),
  org_id                           TEXT CHECK (org_id IS NULL OR length(org_id) <= 80 AND length(org_id) > 0),
  org_name                         TEXT CHECK (org_name IS NULL OR length(org_name) <= 200),
  user_id                          TEXT CHECK (user_id IS NULL OR length(user_id) <= 80 AND length(user_id) > 0),
  actor_name                       TEXT CHECK (actor_name IS NULL OR length(actor_name) <= 200),
  detail_assignment_id             TEXT CHECK (detail_assignment_id IS NULL OR length(detail_assignment_id) <= 80 AND length(detail_assignment_id) > 0) CHECK (detail_assignment_id IS NULL OR type IN ('box_assignment_cancelled')),
  detail_drill_id                  TEXT CHECK (detail_drill_id IS NULL OR length(detail_drill_id) <= 80 AND length(detail_drill_id) > 0) CHECK (detail_drill_id IS NULL OR type IN ('box_assignment_created', 'box_challenge_published')),
  detail_target_type               TEXT CHECK (detail_target_type IS NULL OR length(detail_target_type) <= 40) CHECK (detail_target_type IS NULL OR type IN ('box_assignment_created')),
  detail_target_value              REAL CHECK (detail_target_value IS NULL OR type IN ('box_assignment_created')),
  detail_challenge_id              TEXT CHECK (detail_challenge_id IS NULL OR length(detail_challenge_id) <= 80 AND length(detail_challenge_id) > 0) CHECK (detail_challenge_id IS NULL OR type IN ('box_challenge_published')),
  detail_session_id                TEXT CHECK (detail_session_id IS NULL OR length(detail_session_id) <= 80 AND length(detail_session_id) > 0) CHECK (detail_session_id IS NULL OR type IN ('box_clip_saved', 'box_result_invalidated', 'box_result_restored')),
  detail_media_id                  TEXT CHECK (detail_media_id IS NULL OR length(detail_media_id) <= 80 AND length(detail_media_id) > 0) CHECK (detail_media_id IS NULL OR type IN ('box_clip_saved')),
  detail_by                        TEXT CHECK (detail_by IS NULL OR length(detail_by) <= 40) CHECK (detail_by IS NULL OR type IN ('box_prefs_changed', 'passport_share_revoked')),
  detail_share                     TEXT CHECK (detail_share IS NULL OR length(detail_share) <= 40) CHECK (detail_share IS NULL OR type IN ('box_prefs_changed')),
  detail_retain_clips              INTEGER CHECK (detail_retain_clips IS NULL OR detail_retain_clips IN (0,1)) CHECK (detail_retain_clips IS NULL OR type IN ('box_prefs_changed')),
  detail_dispute_id                TEXT CHECK (detail_dispute_id IS NULL OR length(detail_dispute_id) <= 80 AND length(detail_dispute_id) > 0) CHECK (detail_dispute_id IS NULL OR type IN ('box_result_invalidated')),
  detail_outcome                   TEXT CHECK (detail_outcome IS NULL OR length(detail_outcome) <= 40) CHECK (detail_outcome IS NULL OR type IN ('box_result_invalidated')),
  detail_reason                    TEXT CHECK (detail_reason IS NULL OR length(detail_reason) <= 300) CHECK (detail_reason IS NULL OR type IN ('box_result_restored', 'level_review')),
  detail_attempt_id                TEXT CHECK (detail_attempt_id IS NULL OR length(detail_attempt_id) <= 80 AND length(detail_attempt_id) > 0) CHECK (detail_attempt_id IS NULL OR type IN ('combine_attempt_completed')),
  detail_protocol                  TEXT CHECK (detail_protocol IS NULL OR length(detail_protocol) <= 120) CHECK (detail_protocol IS NULL OR type IN ('combine_attempt_completed')),
  detail_state                     TEXT CHECK (detail_state IS NULL OR length(detail_state) <= 40) CHECK (detail_state IS NULL OR type IN ('combine_attempt_completed')),
  detail_request_id                TEXT CHECK (detail_request_id IS NULL OR length(detail_request_id) <= 80 AND length(detail_request_id) > 0) CHECK (detail_request_id IS NULL OR type IN ('combine_request_completed', 'combine_request_created')),
  detail_from_value                TEXT CHECK (detail_from_value IS NULL OR length(detail_from_value) <= 40) CHECK (detail_from_value IS NULL OR type IN ('level_review')),
  detail_to_value                  TEXT CHECK (detail_to_value IS NULL OR length(detail_to_value) <= 40) CHECK (detail_to_value IS NULL OR type IN ('level_review')),
  detail_trial_id                  TEXT CHECK (detail_trial_id IS NULL OR length(detail_trial_id) <= 80 AND length(detail_trial_id) > 0) CHECK (detail_trial_id IS NULL OR type IN ('open_trial_posted')),
  detail_via                       TEXT CHECK (detail_via IS NULL OR length(detail_via) <= 40) CHECK (detail_via IS NULL OR type IN ('passport_recruitment_view')),
  detail_mode                      TEXT CHECK (detail_mode IS NULL OR length(detail_mode) <= 40) CHECK (detail_mode IS NULL OR type IN ('passport_share_created')),
  detail_share_id                  TEXT CHECK (detail_share_id IS NULL OR length(detail_share_id) <= 80 AND length(detail_share_id) > 0) CHECK (detail_share_id IS NULL OR type IN ('passport_share_created', 'passport_share_revoked')),
  detail_claim_id                  TEXT CHECK (detail_claim_id IS NULL OR length(detail_claim_id) <= 80 AND length(detail_claim_id) > 0) CHECK (detail_claim_id IS NULL OR type IN ('verification_decision')),
  detail_action                    TEXT CHECK (detail_action IS NULL OR length(detail_action) <= 40) CHECK (detail_action IS NULL OR type IN ('verification_decision')),
  detail_root_request_id           TEXT CHECK (detail_root_request_id IS NULL OR length(detail_root_request_id) <= 80 AND length(detail_root_request_id) > 0) CHECK (detail_root_request_id IS NULL OR type IN ('verification_root_approved')),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ledger_protocols (
  ledger_id TEXT NOT NULL,
  ord INTEGER NOT NULL CHECK (ord >= 0),
  protocol TEXT NOT NULL CHECK (length(protocol) > 0 AND length(protocol) <= 120),
  PRIMARY KEY (ledger_id, ord),
  FOREIGN KEY (ledger_id) REFERENCES ledger(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE ops_events (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  occurred_at                      INTEGER NOT NULL,
  kind                             TEXT NOT NULL CHECK (kind IN ('staff_bootstrapped','audit_export','backup_created','backup_refused','backup_failed','delivery_failed','webhook_failed')),
  detail_org_id                    TEXT CHECK (detail_org_id IS NULL OR length(detail_org_id) <= 80 AND length(detail_org_id) > 0) CHECK (detail_org_id IS NULL OR kind IN ('staff_bootstrapped', 'audit_export')),
  detail_user_id                   TEXT CHECK (detail_user_id IS NULL OR length(detail_user_id) <= 80 AND length(detail_user_id) > 0) CHECK (detail_user_id IS NULL OR kind IN ('staff_bootstrapped')),
  detail_by                        TEXT CHECK (detail_by IS NULL OR length(detail_by) <= 200) CHECK (detail_by IS NULL OR kind IN ('staff_bootstrapped', 'audit_export')),
  detail_dir                       TEXT CHECK (detail_dir IS NULL OR length(detail_dir) <= 200) CHECK (detail_dir IS NULL OR kind IN ('backup_created', 'backup_refused', 'backup_failed')),
  detail_files                     INTEGER CHECK (detail_files IS NULL OR kind IN ('backup_created')),
  detail_queued_for_removal        INTEGER CHECK (detail_queued_for_removal IS NULL OR kind IN ('backup_created')),
  detail_error                     TEXT CHECK (detail_error IS NULL OR length(detail_error) <= 300) CHECK (detail_error IS NULL OR kind IN ('backup_refused', 'backup_failed')),
  detail_conflict_count            INTEGER CHECK (detail_conflict_count IS NULL OR kind IN ('backup_refused')),
  detail_dispatch_id               TEXT CHECK (detail_dispatch_id IS NULL OR length(detail_dispatch_id) <= 80 AND length(detail_dispatch_id) > 0) CHECK (detail_dispatch_id IS NULL OR kind IN ('delivery_failed')),
  detail_channel                   TEXT CHECK (detail_channel IS NULL OR length(detail_channel) <= 40) CHECK (detail_channel IS NULL OR kind IN ('delivery_failed')),
  detail_delivery_id               TEXT CHECK (detail_delivery_id IS NULL OR length(detail_delivery_id) <= 80 AND length(detail_delivery_id) > 0) CHECK (detail_delivery_id IS NULL OR kind IN ('webhook_failed')),
  detail_endpoint_id               TEXT CHECK (detail_endpoint_id IS NULL OR length(detail_endpoint_id) <= 80 AND length(detail_endpoint_id) > 0) CHECK (detail_endpoint_id IS NULL OR kind IN ('webhook_failed')),
  FOREIGN KEY (detail_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (detail_user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE source_changes (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                        TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  type                             TEXT NOT NULL CHECK (type IN ('position_changed')),
  source_system                    TEXT NOT NULL CHECK (source_system IN ('passport_prefs','position_history')),
  source_id                        TEXT CHECK (source_id IS NULL OR length(source_id) <= 200 AND length(source_id) > 0),
  occurred_at                      INTEGER NOT NULL,
  detail_position_from             TEXT CHECK (detail_position_from IS NULL OR length(detail_position_from) <= 40) CHECK (detail_position_from IS NULL OR type IN ('position_changed')),
  detail_position_to               TEXT CHECK (detail_position_to IS NULL OR length(detail_position_to) <= 40) CHECK (detail_position_to IS NULL OR type IN ('position_changed')),
  detail_submitted_by              TEXT CHECK (detail_submitted_by IS NULL OR length(detail_submitted_by) <= 40) CHECK (detail_submitted_by IS NULL OR type IN ('position_changed'))
) STRICT;
CREATE TABLE idv_queue (
  seq                              INTEGER PRIMARY KEY,
  id                               TEXT NOT NULL UNIQUE CHECK (length(id) > 0 AND length(id) <= 80),
  guardian_id                      TEXT NOT NULL CHECK (length(guardian_id) <= 80 AND length(guardian_id) > 0),
  guardian_name                    TEXT CHECK (guardian_name IS NULL OR length(guardian_name) <= 200),
  document_type                    TEXT NOT NULL CHECK (length(document_type) <= 60 AND length(document_type) > 0),
  document_ref_last4               TEXT NOT NULL CHECK (length(document_ref_last4) <= 20),
  provider                         TEXT NOT NULL CHECK (length(provider) <= 60 AND length(provider) > 0),
  reference                        TEXT NOT NULL CHECK (length(reference) <= 200 AND length(reference) > 0),
  created_at                       INTEGER NOT NULL,
  status                           TEXT NOT NULL CHECK (status IN ('approved','revoked'))
) STRICT;
CREATE TABLE recruitment_requests (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL,
  player_name TEXT,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name TEXT NOT NULL,
  org_type TEXT CHECK (org_type IS NULL OR org_type IN ('club','agency')),
  org_verified INTEGER NOT NULL CHECK (org_verified IS NULL OR org_verified IN (0,1)),
  org_safeguarding_certified INTEGER NOT NULL CHECK (org_safeguarding_certified IS NULL OR org_safeguarding_certified IN (0,1)),
  org_trusted_partner INTEGER CHECK (org_trusted_partner IS NULL OR org_trusted_partner IN (0,1)),
  user_id TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  scout_name TEXT,
  scout_role TEXT,
  type TEXT NOT NULL CHECK (type IS NULL OR type IN ('contact','trial')),
  message TEXT,
  subject TEXT,
  contact_id TEXT,
  trial_proposed_date TEXT CHECK (trial_proposed_date IS NULL OR trial_proposed_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  trial_alt_days_json TEXT CHECK (trial_alt_days_json IS NULL OR (json_valid(trial_alt_days_json) AND json_type(trial_alt_days_json) = 'array')),
  trial_venue TEXT,
  trial_notes TEXT,
  trial_private_venue_address TEXT CHECK (trial_private_venue_address IS NULL OR length(trial_private_venue_address) <= 200),
  trial_private_instructions TEXT CHECK (trial_private_instructions IS NULL OR length(trial_private_instructions) <= 500),
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('pending','accepted','declined','suspended')),
  created_at INTEGER NOT NULL,
  responded_at INTEGER,
  responded_by TEXT CHECK (responded_by IS NULL OR responded_by IN ('player','guardian')),
  routed_to TEXT NOT NULL CHECK (routed_to IS NULL OR routed_to IN ('player','guardian')),
  guardian_id TEXT,
  contact_channel_id TEXT,
  case_id TEXT REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  trial_id TEXT REFERENCES trials(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  recipient_type TEXT CHECK (recipient_type IS NULL OR recipient_type IN ('player','guardian')),
  recipient_player_id TEXT,
  recipient_guardian_id TEXT,
  recipient_minor INTEGER CHECK (recipient_minor IS NULL OR recipient_minor IN (0,1)),
  invite_key TEXT CHECK (invite_key IS NULL OR length(invite_key) <= 64),
  invite_fp TEXT,
  subject_removed_at INTEGER,
  CHECK ((type = 'trial') = (trial_alt_days_json IS NOT NULL)),
  CHECK ((recipient_type IS NULL) = (recipient_minor IS NULL)),
  CHECK ((invite_key IS NULL) = (invite_fp IS NULL))
) STRICT;
CREATE TABLE request_trial_slots (
  request_id TEXT NOT NULL REFERENCES recruitment_requests(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  day TEXT NOT NULL CHECK (day IS NULL OR day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('onboarding','training','drill','small_sided','match','other')),
  starts_at INTEGER NOT NULL,
  ends_at INTEGER NOT NULL,
  timezone TEXT NOT NULL,
  venue_name TEXT CHECK (venue_name IS NULL OR length(venue_name) <= 120),
  venue_town TEXT CHECK (venue_town IS NULL OR length(venue_town) <= 80),
  venue_address TEXT CHECK (venue_address IS NULL OR length(venue_address) <= 200),
  PRIMARY KEY (request_id, position),
  UNIQUE (request_id, day),
  CHECK (ends_at > starts_at)
) STRICT;
CREATE TABLE trials (
  id TEXT PRIMARY KEY,
  request_id TEXT NOT NULL UNIQUE REFERENCES recruitment_requests(id) ON DELETE RESTRICT,
  case_id TEXT REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  player_name TEXT,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name TEXT NOT NULL,
  scout_name TEXT,
  accepted_at INTEGER NOT NULL,
  accepted_by TEXT CHECK (accepted_by IS NULL OR accepted_by IN ('player','guardian')),
  guardian_approved INTEGER CHECK (guardian_approved IS NULL OR guardian_approved IN (0,1)),
  proposed_date TEXT CHECK (proposed_date IS NULL OR proposed_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  venue TEXT,
  notes TEXT,
  report_due_at INTEGER,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('awaiting_report','reported')),
  reminder_sent INTEGER NOT NULL CHECK (reminder_sent IS NULL OR reminder_sent IN (0,1)),
  feedback_escalated_at INTEGER,
  workflow_state TEXT NOT NULL CHECK (workflow_state IS NULL OR workflow_state IN ('legacy_accepted','accepted','scheduled','completed','cancelled')),
  schedule_timezone TEXT,
  schedule_revision INTEGER,
  schedule_proposed_at INTEGER,
  schedule_proposed_by_kind TEXT CHECK (schedule_proposed_by_kind IS NULL OR schedule_proposed_by_kind IN ('org','player','guardian','system')),
  schedule_proposed_by_user_id TEXT,
  schedule_proposed_by_actor_id TEXT,
  schedule_proposed_by_name TEXT,
  schedule_confirmed_at INTEGER,
  schedule_confirmed_by_kind TEXT CHECK (schedule_confirmed_by_kind IS NULL OR schedule_confirmed_by_kind IN ('org','player','guardian','system')),
  schedule_confirmed_by_user_id TEXT,
  schedule_confirmed_by_actor_id TEXT,
  schedule_confirmed_by_name TEXT,
  schedule_declined_at INTEGER,
  schedule_declined_by_kind TEXT CHECK (schedule_declined_by_kind IS NULL OR schedule_declined_by_kind IN ('org','player','guardian','system')),
  schedule_declined_by_user_id TEXT,
  schedule_declined_by_actor_id TEXT,
  schedule_declined_by_name TEXT,
  completion_state TEXT CHECK (completion_state IS NULL OR completion_state IN ('completed','cancelled')),
  completion_at INTEGER,
  completion_by_kind TEXT CHECK (completion_by_kind IS NULL OR completion_by_kind IN ('org','player','guardian','system')),
  completion_by_user_id TEXT,
  completion_by_actor_id TEXT,
  completion_by_name TEXT,
  completion_reason TEXT CHECK (completion_reason IS NULL OR length(completion_reason) <= 300),
  completion_phase TEXT CHECK (completion_phase IS NULL OR completion_phase IN ('legacy_accepted','accepted','scheduled','completed','cancelled')),
  completion_cancelled_by TEXT CHECK (completion_cancelled_by IS NULL OR completion_cancelled_by IN ('club','player','guardian','system')),
  recipient_type TEXT CHECK (recipient_type IS NULL OR recipient_type IN ('player','guardian')),
  recipient_player_id TEXT,
  recipient_guardian_id TEXT,
  recipient_minor INTEGER CHECK (recipient_minor IS NULL OR recipient_minor IN (0,1)),
  recipient_at INTEGER,
  lifecycle_applied INTEGER CHECK (lifecycle_applied IS NULL OR lifecycle_applied IN (0,1)),
  lifecycle_from TEXT,
  lifecycle_to TEXT,
  lifecycle_reason TEXT,
  lifecycle_at INTEGER,
  day_arrival_time TEXT CHECK (day_arrival_time IS NULL OR length(day_arrival_time) <= 40),
  day_arrival_address TEXT CHECK (day_arrival_address IS NULL OR length(day_arrival_address) <= 200),
  day_arrival_notes TEXT CHECK (day_arrival_notes IS NULL OR length(day_arrival_notes) <= 300),
  day_emergency_name TEXT CHECK (day_emergency_name IS NULL OR length(day_emergency_name) <= 80),
  day_emergency_phone TEXT CHECK (day_emergency_phone IS NULL OR length(day_emergency_phone) <= 30),
  day_emergency_set_by TEXT CHECK (day_emergency_set_by IS NULL OR day_emergency_set_by IN ('player','guardian')),
  day_emergency_at INTEGER,
  day_collection_policy TEXT CHECK (day_collection_policy IS NULL OR length(day_collection_policy) <= 300),
  rev INTEGER NOT NULL CHECK (rev >= 0),
  rev_at INTEGER,
  rev_by_user_id TEXT,
  rev_by_name TEXT,
  subject_removed_at INTEGER,
  UNIQUE (id, player_id),
  CHECK ((schedule_timezone IS NULL) = (schedule_revision IS NULL)),
  CHECK ((completion_state IS NULL) = (completion_at IS NULL)),
  CHECK ((recipient_type IS NULL) = (recipient_minor IS NULL)),
  CHECK (day_emergency_at IS NOT NULL OR (day_emergency_name IS NULL AND day_emergency_phone IS NULL))
) STRICT;
CREATE TABLE trial_schedule_sessions (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('onboarding','training','drill','small_sided','match','other')),
  starts_at INTEGER NOT NULL,
  ends_at INTEGER NOT NULL,
  venue_name TEXT CHECK (venue_name IS NULL OR length(venue_name) <= 120),
  venue_town TEXT CHECK (venue_town IS NULL OR length(venue_town) <= 80),
  venue_address TEXT CHECK (venue_address IS NULL OR length(venue_address) <= 200),
  instructions TEXT CHECK (instructions IS NULL OR length(instructions) <= 500),
  PRIMARY KEY (trial_id, position),
  UNIQUE (trial_id, id),
  CHECK (ends_at > starts_at)
) STRICT;
CREATE TABLE trial_session_evidence (
  trial_id TEXT NOT NULL,
  session_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('box_cam_session')),
  box_session_id TEXT NOT NULL,
  linked_at INTEGER NOT NULL,
  linked_by_kind TEXT CHECK (linked_by_kind IS NULL OR linked_by_kind IN ('org','player','guardian','system')),
  linked_by_user_id TEXT,
  linked_by_actor_id TEXT,
  linked_by_name TEXT,
  removed_at INTEGER,
  removed_by_kind TEXT CHECK (removed_by_kind IS NULL OR removed_by_kind IN ('org','player','guardian','system')),
  removed_by_user_id TEXT,
  removed_by_actor_id TEXT,
  removed_by_name TEXT,
  PRIMARY KEY (trial_id, session_id, position),
  FOREIGN KEY (trial_id, session_id) REFERENCES trial_schedule_sessions(trial_id, id) ON DELETE CASCADE
) STRICT;
CREATE TABLE trial_schedule_revisions (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  revision INTEGER NOT NULL,
  timezone TEXT NOT NULL,
  proposed_at INTEGER,
  proposed_by_kind TEXT CHECK (proposed_by_kind IS NULL OR proposed_by_kind IN ('org','player','guardian','system')),
  proposed_by_user_id TEXT,
  proposed_by_actor_id TEXT,
  proposed_by_name TEXT,
  confirmed_at INTEGER,
  confirmed_by_kind TEXT CHECK (confirmed_by_kind IS NULL OR confirmed_by_kind IN ('org','player','guardian','system')),
  confirmed_by_user_id TEXT,
  confirmed_by_actor_id TEXT,
  confirmed_by_name TEXT,
  superseded_at INTEGER,
  reason TEXT CHECK (reason IS NULL OR length(reason) <= 300),
  material INTEGER CHECK (material IS NULL OR material IN (0,1)),
  PRIMARY KEY (trial_id, position),
  UNIQUE (trial_id, revision)
) STRICT;
CREATE TABLE trial_revision_sessions (
  trial_id TEXT NOT NULL,
  revision INTEGER NOT NULL,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('onboarding','training','drill','small_sided','match','other')),
  starts_at INTEGER NOT NULL,
  ends_at INTEGER NOT NULL,
  venue_name TEXT CHECK (venue_name IS NULL OR length(venue_name) <= 120),
  venue_town TEXT CHECK (venue_town IS NULL OR length(venue_town) <= 80),
  venue_address TEXT CHECK (venue_address IS NULL OR length(venue_address) <= 200),
  instructions TEXT CHECK (instructions IS NULL OR length(instructions) <= 500),
  PRIMARY KEY (trial_id, revision, position),
  FOREIGN KEY (trial_id, revision) REFERENCES trial_schedule_revisions(trial_id, revision) ON DELETE CASCADE
) STRICT;
CREATE TABLE trial_attendance (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  session_id TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IS NULL OR state IN ('attended','partial','no_show','club_cancelled','player_withdrew')),
  source TEXT NOT NULL CHECK (source IS NULL OR source IN ('checkin','manual')),
  recorded_by_kind TEXT CHECK (recorded_by_kind IS NULL OR recorded_by_kind IN ('org','player','guardian','system')),
  recorded_by_user_id TEXT,
  recorded_by_actor_id TEXT,
  recorded_by_name TEXT,
  recorded_at INTEGER NOT NULL,
  note TEXT CHECK (note IS NULL OR length(note) <= 300),
  PRIMARY KEY (trial_id, position)
) STRICT;
CREATE TABLE trial_history (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  at INTEGER NOT NULL,
  action TEXT NOT NULL CHECK (action IS NULL OR length(action) <= 64),
  by_kind TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','player','guardian','system')),
  by_user_id TEXT,
  by_actor_id TEXT,
  by_name TEXT,
  detail_json TEXT CHECK (detail_json IS NULL OR (json_valid(detail_json) AND json_type(detail_json) = 'object')),
  PRIMARY KEY (trial_id, position),
  UNIQUE (trial_id, id)
) STRICT;
CREATE TABLE trial_keys (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  act TEXT NOT NULL CHECK (act IS NULL OR act IN ('schedule','cancel','attendance','complete','link')),
  position INTEGER NOT NULL,
  key TEXT NOT NULL CHECK (key IS NULL OR length(key) <= 64),
  fp TEXT NOT NULL,
  at INTEGER NOT NULL,
  PRIMARY KEY (trial_id, act, position)
) STRICT;
CREATE TABLE trial_reminders (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  marker TEXT NOT NULL CHECK (marker IS NULL OR length(marker) <= 120),
  sent_at INTEGER NOT NULL,
  PRIMARY KEY (trial_id, marker)
) STRICT;
CREATE TABLE trial_reports (
  trial_id TEXT PRIMARY KEY REFERENCES trials(id) ON DELETE CASCADE,
  id TEXT NOT NULL UNIQUE,
  player_id TEXT NOT NULL,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name TEXT,
  user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  scout_name TEXT,
  filed_at INTEGER NOT NULL,
  acceleration REAL NOT NULL,
  sprint_speed_kmh REAL NOT NULL,
  distance_km REAL NOT NULL,
  pass_completion_pct REAL NOT NULL,
  duel_success_pct REAL NOT NULL,
  coach_rating REAL NOT NULL,
  notes TEXT,
  strength_note TEXT,
  focus_note TEXT,
  FOREIGN KEY (trial_id, player_id) REFERENCES trials(id, player_id) ON DELETE CASCADE
) STRICT;
CREATE TABLE trial_day_staff (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  name TEXT NOT NULL CHECK (name IS NULL OR length(name) <= 80),
  role TEXT NOT NULL CHECK (role IS NULL OR length(role) <= 60),
  check_kind TEXT CHECK (check_kind IS NULL OR length(check_kind) <= 60),
  check_ref TEXT CHECK (check_ref IS NULL OR length(check_ref) <= 60),
  check_status TEXT CHECK (check_status IS NULL OR check_status IN ('pending','reviewed','expired','rejected')),
  check_expires_at TEXT,
  check_reviewed_by TEXT,
  check_reviewed_at INTEGER,
  added_by_name TEXT,
  added_at INTEGER NOT NULL,
  PRIMARY KEY (trial_id, position),
  UNIQUE (trial_id, id),
  CHECK (check_status IS NOT NULL OR (check_kind IS NULL AND check_ref IS NULL AND check_expires_at IS NULL AND check_reviewed_by IS NULL AND check_reviewed_at IS NULL))
) STRICT;
CREATE TABLE trial_day_consents (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  by_kind TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','player','guardian','system')),
  by_user_id TEXT,
  by_actor_id TEXT,
  by_name TEXT,
  scope TEXT NOT NULL CHECK (scope IS NULL OR scope IN ('player_event_consent','guardian_event_consent')),
  at INTEGER NOT NULL,
  PRIMARY KEY (trial_id, position)
) STRICT;
CREATE TABLE trial_day_checkins (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  player_id TEXT NOT NULL,
  at INTEGER NOT NULL,
  by_user_id TEXT,
  by_name TEXT,
  PRIMARY KEY (trial_id, position)
) STRICT;
CREATE TABLE trial_day_status_events (
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('cancelled','postponed')),
  at INTEGER NOT NULL,
  by_name TEXT,
  reason TEXT CHECK (reason IS NULL OR length(reason) <= 200),
  new_date TEXT CHECK (new_date IS NULL OR new_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  PRIMARY KEY (trial_id, position)
) STRICT;
CREATE TABLE recruitment_cases (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  player_name TEXT,
  vacancy_id TEXT,
  owner_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT NOT NULL,
  owner_name TEXT,
  stage TEXT NOT NULL CHECK (stage IS NULL OR stage IN ('identified','review','observation','trial','decision','closed','invited','awaiting_response')),
  priority TEXT NOT NULL CHECK (priority IS NULL OR priority IN ('high','medium','low')),
  deadline_day TEXT CHECK (deadline_day IS NULL OR deadline_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  deadline_at INTEGER,
  restricted INTEGER NOT NULL CHECK (restricted IS NULL OR restricted IN (0,1)),
  decision_outcome TEXT CHECK (decision_outcome IS NULL OR decision_outcome IN ('sign','pass','monitor')),
  decision_reasons TEXT CHECK (decision_reasons IS NULL OR length(decision_reasons) <= 500),
  decision_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  decision_by_name TEXT,
  decision_approved_by_name TEXT,
  decision_at INTEGER,
  links_signing_id TEXT,
  created_at INTEGER NOT NULL,
  subject_removed_at INTEGER,
  room_status TEXT CHECK (room_status IS NULL OR room_status IN ('watching','under_review','contact_planned','contacted','shortlisted','priority','trial_requested','trial_scheduled','trial_completed','offer_consideration','offer_made','offer_accepted','offer_declined','signed','on_hold','withdrawn','archived','closed')),
  room_priority TEXT CHECK (room_priority IS NULL OR room_priority IN ('low','normal','high','urgent')),
  room_lead_scout_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  room_source_context TEXT CHECK (room_source_context IS NULL OR room_source_context IN ('search','watchlist','shortlist','opportunity','recommendation','campaign','passport','nobody_missed','second_look','matching','dynamic_watchlist','direct')),
  room_source_ref_id TEXT,
  room_source_ref_version INTEGER,
  room_opened_by_user_id TEXT,
  room_opened_by_name TEXT,
  room_updated_at INTEGER,
  room_archived_at INTEGER,
  room_closed_at INTEGER,
  room_rev INTEGER CHECK (room_rev IS NULL OR room_rev >= 0),
  room_rev_at INTEGER,
  room_rev_by_user_id TEXT,
  room_rev_by_name TEXT,
  room_reopened_at INTEGER,
  room_reopened_by_user_id TEXT,
  room_reopened_by_name TEXT,
  room_reopened_from TEXT CHECK (room_reopened_from IS NULL OR room_reopened_from IN ('watching','under_review','contact_planned','contacted','shortlisted','priority','trial_requested','trial_scheduled','trial_completed','offer_consideration','offer_made','offer_accepted','offer_declined','signed','on_hold','withdrawn','archived','closed')),
  room_reopened_reason_codes_json TEXT CHECK (room_reopened_reason_codes_json IS NULL OR (json_valid(room_reopened_reason_codes_json) AND json_type(room_reopened_reason_codes_json) = 'array')),
  room_reopened_source_context TEXT CHECK (room_reopened_source_context IS NULL OR room_reopened_source_context IN ('search','watchlist','shortlist','opportunity','recommendation','campaign','passport','nobody_missed','second_look','matching','dynamic_watchlist','direct')),
  room_reopened_source_ref_id TEXT,
  room_reopened_source_ref_version INTEGER,
  CHECK (deadline_day IS NULL OR deadline_at IS NULL),
  CHECK ((decision_outcome IS NULL) = (decision_at IS NULL)),
  CHECK ((room_status IS NULL) = (room_rev IS NULL) AND (room_status IS NULL) = (room_updated_at IS NULL) AND (room_status IS NULL) = (room_priority IS NULL)),
  CHECK ((room_reopened_at IS NULL) = (room_reopened_reason_codes_json IS NULL)),
  CHECK (room_status IS NOT NULL OR room_reopened_at IS NULL)
) STRICT;
CREATE TABLE case_room_tags (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  tag TEXT NOT NULL CHECK (length(tag) BETWEEN 1 AND 40),
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, tag)
) STRICT;
CREATE TABLE case_assignments (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT NOT NULL,
  user_name TEXT,
  task TEXT NOT NULL CHECK (task IS NULL OR length(task) <= 200),
  due_day TEXT CHECK (due_day IS NULL OR due_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  due_at INTEGER,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('open','in_progress','done','cancelled')),
  created_at INTEGER NOT NULL,
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, id),
  CHECK (due_day IS NULL OR due_at IS NULL)
) STRICT;
CREATE TABLE case_tasks (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  description TEXT CHECK (description IS NULL OR length(description) <= 1000),
  due_day TEXT CHECK (due_day IS NULL OR due_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  due_at INTEGER,
  assignee_user_id TEXT,
  assignee_name TEXT,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('open','in_progress','done','cancelled')),
  linked_resource_type TEXT CHECK (linked_resource_type IS NULL OR linked_resource_type IN ('evidence','assessment','combine_request','trial','box_cam_assignment','evidence_request','comment')),
  linked_resource_id TEXT,
  created_by_user_id TEXT,
  created_by_name TEXT,
  created_at INTEGER NOT NULL,
  completed_at INTEGER,
  completed_by_name TEXT,
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, id),
  CHECK (due_day IS NULL OR due_at IS NULL)
) STRICT;
CREATE TABLE case_approvals (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  decision_outcome TEXT NOT NULL CHECK (decision_outcome IS NULL OR decision_outcome IN ('sign','pass','monitor')),
  decision_reasons TEXT CHECK (decision_reasons IS NULL OR length(decision_reasons) <= 500),
  requested_by_user_id TEXT,
  requested_by_name TEXT,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('pending','approved','rejected')),
  requested_at INTEGER NOT NULL,
  resolved_by_user_id TEXT,
  resolved_by_name TEXT,
  resolved_at INTEGER,
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, id),
  CHECK ((status = 'pending') = (resolved_at IS NULL))
) STRICT;
CREATE TABLE case_history (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  at INTEGER NOT NULL,
  action TEXT NOT NULL CHECK (length(action) BETWEEN 1 AND 64),
  by_kind TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','org_user','player','guardian','system','admin','agent')),
  by_id TEXT,
  by_name TEXT,
  detail_text TEXT,
  detail_json TEXT CHECK (detail_json IS NULL OR (json_valid(detail_json) AND json_type(detail_json) = 'object')),
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, id),
  CHECK (detail_text IS NULL OR detail_json IS NULL)
) STRICT;
CREATE TABLE case_request_links (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  request_id TEXT NOT NULL REFERENCES recruitment_requests(id) ON DELETE RESTRICT,
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, request_id)
) STRICT;
CREATE TABLE case_trial_links (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  trial_id TEXT NOT NULL REFERENCES trials(id) ON DELETE RESTRICT,
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, trial_id)
) STRICT;
CREATE TABLE case_decision_drafts (
  case_id TEXT PRIMARY KEY REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  id TEXT NOT NULL UNIQUE,
  outcome TEXT CHECK (outcome IS NULL OR outcome IN ('progress','hold','reject')),
  note TEXT CHECK (note IS NULL OR length(note) <= 2000),
  by_user_id TEXT,
  by_name TEXT,
  by_role TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  updated_by_user_id TEXT,
  updated_by_name TEXT,
  updated_by_role TEXT,
  rev INTEGER NOT NULL CHECK (rev >= 1),
  rev_at INTEGER,
  create_key TEXT CHECK (create_key IS NULL OR length(create_key) <= 64),
  create_fp TEXT,
  CHECK ((create_key IS NULL) = (create_fp IS NULL))
) STRICT;
CREATE TABLE case_decision_draft_reason_codes (
  case_id TEXT NOT NULL REFERENCES case_decision_drafts(case_id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  code TEXT NOT NULL CHECK (length(code) BETWEEN 1 AND 64),
  PRIMARY KEY (case_id, position)
) STRICT;
CREATE TABLE case_decision_draft_evidence_refs (
  case_id TEXT NOT NULL REFERENCES case_decision_drafts(case_id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('assessment','trial','box_cam_session','passport_evidence')),
  ref_id TEXT NOT NULL,
  meta_json TEXT CHECK (meta_json IS NULL OR (json_valid(meta_json) AND json_type(meta_json) = 'object')),
  PRIMARY KEY (case_id, position)
) STRICT;
CREATE TABLE case_transaction_handoffs (
  case_id TEXT PRIMARY KEY REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  id TEXT NOT NULL UNIQUE,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('invited','accepted','withdrawn')),
  invited_at INTEGER NOT NULL,
  invited_by_user_id TEXT,
  invited_by_name TEXT,
  accepted_at INTEGER,
  withdrawn_at INTEGER,
  transaction_id TEXT,
  represented_at_invitation INTEGER NOT NULL CHECK (represented_at_invitation IS NULL OR represented_at_invitation IN (0,1)),
  invited_agency_org_id TEXT,
  invited_agent_user_id TEXT,
  invite_key TEXT CHECK (invite_key IS NULL OR length(invite_key) <= 64),
  rev INTEGER NOT NULL CHECK (rev >= 1),
  rev_at INTEGER,
  CHECK ((status = 'accepted') = (accepted_at IS NOT NULL)),
  CHECK ((status = 'withdrawn') = (withdrawn_at IS NOT NULL))
) STRICT;
CREATE TABLE case_budget_scenarios (
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version >= 1),
  label TEXT NOT NULL CHECK (label IS NULL OR length(label) <= 80),
  currency TEXT NOT NULL CHECK (currency IS NULL OR currency IN ('GBP','EUR','USD','CHF','SEK','NOK','DKK','PLN','BRL')),
  term_months INTEGER NOT NULL CHECK (term_months BETWEEN 1 AND 72),
  created_by_name TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  approval_by_name TEXT,
  approval_by_user_id TEXT,
  approval_at INTEGER,
  approval_version INTEGER,
  approval_superseded INTEGER CHECK (approval_superseded IS NULL OR approval_superseded IN (0,1)),
  PRIMARY KEY (case_id, position),
  UNIQUE (case_id, id),
  CHECK ((approval_at IS NULL) = (approval_version IS NULL) AND (approval_at IS NULL) = (approval_superseded IS NULL))
) STRICT;
CREATE TABLE case_budget_lines (
  case_id TEXT NOT NULL,
  scenario_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('wage','fee','bonus','expense')),
  label TEXT NOT NULL CHECK (label IS NULL OR length(label) <= 80),
  amount_minor INTEGER NOT NULL CHECK (amount_minor >= 0),
  currency TEXT NOT NULL CHECK (currency IS NULL OR currency IN ('GBP','EUR','USD','CHF','SEK','NOK','DKK','PLN','BRL')),
  schedule TEXT NOT NULL CHECK (schedule IS NULL OR schedule IN ('one_off','weekly','monthly','annual')),
  confirmed INTEGER NOT NULL CHECK (confirmed IS NULL OR confirmed IN (0,1)),
  conditional_assumption TEXT CHECK (conditional_assumption IS NULL OR length(conditional_assumption) <= 200),
  PRIMARY KEY (case_id, scenario_id, position),
  UNIQUE (case_id, scenario_id, id),
  FOREIGN KEY (case_id, scenario_id) REFERENCES case_budget_scenarios(case_id, id) ON DELETE CASCADE
) STRICT;
CREATE TABLE case_budget_fx_assumptions (
  case_id TEXT NOT NULL,
  scenario_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  from_currency TEXT NOT NULL CHECK (from_currency IS NULL OR from_currency IN ('GBP','EUR','USD','CHF','SEK','NOK','DKK','PLN','BRL')),
  to_currency TEXT NOT NULL CHECK (to_currency IS NULL OR to_currency IN ('GBP','EUR','USD','CHF','SEK','NOK','DKK','PLN','BRL')),
  rate TEXT NOT NULL CHECK (length(rate) BETWEEN 1 AND 32),
  source TEXT CHECK (source IS NULL OR length(source) <= 80),
  date TEXT NOT NULL CHECK (date IS NULL OR date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  manual INTEGER NOT NULL CHECK (manual IS NULL OR manual IN (0,1)),
  PRIMARY KEY (case_id, scenario_id, position),
  FOREIGN KEY (case_id, scenario_id) REFERENCES case_budget_scenarios(case_id, id) ON DELETE CASCADE
) STRICT;
CREATE TABLE case_budget_actuals (
  case_id TEXT NOT NULL,
  scenario_id TEXT NOT NULL,
  position INTEGER NOT NULL,
  id TEXT NOT NULL,
  line_id TEXT NOT NULL,
  amount_minor INTEGER NOT NULL,
  at INTEGER NOT NULL,
  recorded_by_name TEXT,
  PRIMARY KEY (case_id, scenario_id, position),
  FOREIGN KEY (case_id, scenario_id) REFERENCES case_budget_scenarios(case_id, id) ON DELETE CASCADE
) STRICT;
CREATE TABLE room_comments (
  id TEXT PRIMARY KEY,
  room_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  author_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT NOT NULL,
  author_name TEXT,
  body TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 4000),
  reply_to_id TEXT,
  created_at INTEGER NOT NULL,
  edited_at INTEGER,
  edit_count INTEGER NOT NULL CHECK (edit_count >= 0),
  deleted_at INTEGER,
  deleted_by_user_id TEXT,
  deleted_by_name TEXT,
  UNIQUE (room_id, id),
  FOREIGN KEY (room_id, reply_to_id) REFERENCES room_comments(room_id, id) ON DELETE RESTRICT,
  CHECK (deleted_at IS NOT NULL OR (deleted_by_user_id IS NULL AND deleted_by_name IS NULL))
) STRICT;
CREATE TABLE room_comment_mentions (
  comment_id TEXT NOT NULL REFERENCES room_comments(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  user_id TEXT NOT NULL,
  PRIMARY KEY (comment_id, position),
  UNIQUE (comment_id, user_id)
) STRICT;
CREATE TABLE room_snapshots (
  id TEXT PRIMARY KEY,
  room_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  at INTEGER NOT NULL,
  trigger TEXT NOT NULL CHECK (length(trigger) BETWEEN 1 AND 120),
  trust_score REAL,
  trust_band TEXT,
  trust_policy_version INTEGER,
  trust_component_levels_json TEXT CHECK (trust_component_levels_json IS NULL OR (json_valid(trust_component_levels_json) AND json_type(trust_component_levels_json) = 'object')),
  trust_hash TEXT,
  source_passport_version INTEGER,
  source_passport_revision TEXT,
  note TEXT,
  UNIQUE (room_id, id),
  CHECK ((trust_hash IS NULL) = (trust_component_levels_json IS NULL))
) STRICT;
CREATE TABLE room_snapshot_source_refs (
  snapshot_id TEXT NOT NULL REFERENCES room_snapshots(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('evidence','assessment','combine','trial')),
  position INTEGER NOT NULL,
  ref_id TEXT NOT NULL,
  PRIMARY KEY (snapshot_id, kind, position)
) STRICT;
CREATE TABLE room_decisions (
  id TEXT PRIMARY KEY,
  room_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  kind TEXT CHECK (kind IS NULL OR kind IN ('recommendation','formal')),
  state TEXT CHECK (state IS NULL OR state IN ('draft','final')),
  outcome TEXT CHECK (outcome IS NULL OR outcome IN ('progress','hold','reject')),
  recommendation TEXT NOT NULL CHECK (recommendation IS NULL OR recommendation IN ('no_decision','continue_watching','shortlist','priority','trial','offer','archive')),
  note TEXT CHECK (note IS NULL OR length(note) <= 2000),
  by_user_id TEXT,
  by_name TEXT,
  by_role TEXT,
  created_at INTEGER NOT NULL,
  finalized_at INTEGER,
  trigger TEXT CHECK (trigger IS NULL OR length(trigger) <= 120),
  client_key TEXT CHECK (client_key IS NULL OR length(client_key) <= 64),
  supersedes_id TEXT,
  superseded_by_id TEXT,
  supersession_of_id TEXT,
  supersession_reason TEXT CHECK (supersession_reason IS NULL OR length(supersession_reason) <= 500),
  rev INTEGER CHECK (rev IS NULL OR rev >= 1),
  rev_at INTEGER,
  assessments_submitted INTEGER,
  assessments_withheld INTEGER,
  assessment_verdicts_json TEXT CHECK (assessment_verdicts_json IS NULL OR (json_valid(assessment_verdicts_json) AND json_type(assessment_verdicts_json) = 'object')),
  snapshot_id TEXT,
  finalize_key TEXT CHECK (finalize_key IS NULL OR length(finalize_key) <= 64),
  finalize_fp TEXT,
  draft_key TEXT CHECK (draft_key IS NULL OR length(draft_key) <= 64),
  draft_fp TEXT,
  draft_id TEXT,
  lifecycle_action TEXT,
  lifecycle_from TEXT CHECK (lifecycle_from IS NULL OR lifecycle_from IN ('watching','under_review','contact_planned','contacted','shortlisted','priority','trial_requested','trial_scheduled','trial_completed','offer_consideration','offer_made','offer_accepted','offer_declined','signed','on_hold','withdrawn','archived','closed')),
  lifecycle_to TEXT CHECK (lifecycle_to IS NULL OR lifecycle_to IN ('watching','under_review','contact_planned','contacted','shortlisted','priority','trial_requested','trial_scheduled','trial_completed','offer_consideration','offer_made','offer_accepted','offer_declined','signed','on_hold','withdrawn','archived','closed')),
  lifecycle_applied INTEGER CHECK (lifecycle_applied IS NULL OR lifecycle_applied IN (0,1)),
  lifecycle_reason TEXT,
  lifecycle_at INTEGER,
  policy_version INTEGER,
  UNIQUE (room_id, id),
  FOREIGN KEY (room_id, snapshot_id) REFERENCES room_snapshots(room_id, id) ON DELETE RESTRICT,
  FOREIGN KEY (room_id, supersedes_id) REFERENCES room_decisions(room_id, id) ON DELETE RESTRICT,
  FOREIGN KEY (room_id, superseded_by_id) REFERENCES room_decisions(room_id, id) ON DELETE RESTRICT,
  CHECK ((finalize_key IS NULL) = (finalize_fp IS NULL)),
  CHECK ((draft_key IS NULL) = (draft_fp IS NULL)),
  CHECK ((assessments_submitted IS NULL) = (assessment_verdicts_json IS NULL)),
  CHECK ((supersession_of_id IS NULL) = (supersession_reason IS NULL))
) STRICT;
CREATE TABLE room_decision_reason_codes (
  decision_id TEXT NOT NULL REFERENCES room_decisions(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  code TEXT NOT NULL CHECK (length(code) BETWEEN 1 AND 64),
  PRIMARY KEY (decision_id, position)
) STRICT;
CREATE TABLE room_decision_evidence_refs (
  decision_id TEXT NOT NULL REFERENCES room_decisions(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IS NULL OR kind IN ('assessment','trial','box_cam_session','passport_evidence')),
  ref_id TEXT NOT NULL,
  meta_json TEXT CHECK (meta_json IS NULL OR (json_valid(meta_json) AND json_type(meta_json) = 'object')),
  PRIMARY KEY (decision_id, position)
) STRICT;
CREATE TABLE room_decision_assessment_ids (
  decision_id TEXT NOT NULL REFERENCES room_decisions(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  assessment_id TEXT NOT NULL,
  PRIMARY KEY (decision_id, position)
) STRICT;
CREATE TABLE room_evidence_states (
  id TEXT PRIMARY KEY,
  room_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  evidence_id TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IS NULL OR state IN ('not_reviewed','reviewing','reviewed','needs_follow_up')),
  note TEXT CHECK (note IS NULL OR length(note) <= 1000),
  by_user_id TEXT,
  by_name TEXT,
  at INTEGER NOT NULL,
  UNIQUE (room_id, evidence_id)
) STRICT;
CREATE TABLE recruitment_contacts (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('draft','delivered','failed','responded','recorded','cancelled')),
  channel TEXT NOT NULL CHECK (channel IS NULL OR channel IN ('in_app','phone','in_person','email_external','agent','other')),
  contact_mode TEXT NOT NULL CHECK (contact_mode IS NULL OR contact_mode IN ('player_only','both')),
  recipient_type TEXT CHECK (recipient_type IS NULL OR recipient_type IN ('player','guardian')),
  recipient_player_id TEXT,
  recipient_guardian_id TEXT,
  recipient_minor INTEGER CHECK (recipient_minor IS NULL OR recipient_minor IN (0,1)),
  routing_at INTEGER,
  routing_mode TEXT CHECK (routing_mode IS NULL OR routing_mode IN ('player_only','both')),
  routing_player INTEGER CHECK (routing_player IS NULL OR routing_player IN (0,1)),
  routing_guardian INTEGER CHECK (routing_guardian IS NULL OR routing_guardian IN (0,1)),
  routing_agent_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  routing_agent_agreement_id TEXT,
  routing_honest TEXT,
  subject TEXT CHECK (subject IS NULL OR length(subject) <= 120),
  body TEXT CHECK (body IS NULL OR length(body) <= 2000),
  summary TEXT CHECK (summary IS NULL OR length(summary) <= 500),
  created_by_user_id TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name TEXT,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  sent_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  sent_by_name TEXT,
  sent_at INTEGER,
  delivered_at INTEGER,
  failed_at INTEGER,
  failure_code TEXT,
  request_id TEXT REFERENCES recruitment_requests(id) DEFERRABLE INITIALLY DEFERRED,
  email_copy_state TEXT CHECK (email_copy_state IS NULL OR email_copy_state IN ('queued','not_available','local_outbox','accepted_by_provider','failed')),
  email_copy_to TEXT CHECK (email_copy_to IS NULL OR email_copy_to IN ('guardian')),
  email_copy_outbox_id TEXT,
  email_copy_at INTEGER,
  lifecycle_applied INTEGER CHECK (lifecycle_applied IS NULL OR lifecycle_applied IN (0,1)),
  lifecycle_from TEXT,
  lifecycle_to TEXT,
  lifecycle_reason TEXT,
  lifecycle_at INTEGER,
  occurred_at INTEGER,
  recorded_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  recorded_by_name TEXT,
  recorded_at INTEGER,
  responded_at INTEGER,
  response_kind TEXT CHECK (response_kind IS NULL OR response_kind IN ('accepted','declined')),
  response_message TEXT CHECK (response_message IS NULL OR length(response_message) <= 500),
  response_by TEXT CHECK (response_by IS NULL OR response_by IN ('player','guardian')),
  response_at INTEGER,
  cancelled_at INTEGER,
  cancelled_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  cancelled_by_name TEXT,
  create_key TEXT,
  create_fp TEXT,
  send_key TEXT,
  send_fp TEXT,
  record_key TEXT,
  record_fp TEXT,
  rev INTEGER NOT NULL CHECK (rev >= 0),
  rev_at INTEGER,
  rev_by_user_id TEXT,
  rev_by_name TEXT,
  policy_version INTEGER NOT NULL,
  CHECK ((recipient_type IS NULL) = (recipient_minor IS NULL)),
  CHECK ((routing_at IS NULL) = (routing_mode IS NULL)),
  CHECK ((email_copy_state IS NULL) = (email_copy_to IS NULL)),
  CHECK ((response_kind IS NULL) = (response_by IS NULL)),
  CHECK (send_key IS NULL OR send_fp IS NOT NULL),
  CHECK ((create_key IS NULL) = (create_fp IS NULL)),
  CHECK ((record_key IS NULL) = (record_fp IS NULL)),
  CHECK (routing_mode IS NULL OR (routing_player IS NOT NULL AND routing_guardian IS NOT NULL)),
  CHECK (lifecycle_applied IS NULL OR (lifecycle_applied = 1 AND lifecycle_reason IS NULL) OR (lifecycle_applied = 0 AND lifecycle_from IS NULL AND lifecycle_to IS NULL)),
  CHECK (request_id IS NULL OR channel = 'in_app')
) STRICT;
CREATE TABLE contact_attempts (
  contact_id TEXT NOT NULL REFERENCES recruitment_contacts(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  at INTEGER NOT NULL,
  ok INTEGER NOT NULL CHECK (ok IS NULL OR ok IN (0,1)),
  code TEXT,
  PRIMARY KEY (contact_id, position)
) STRICT;
CREATE TABLE contact_history (
  id TEXT PRIMARY KEY,
  contact_id TEXT NOT NULL REFERENCES recruitment_contacts(id) ON DELETE RESTRICT,
  position INTEGER NOT NULL,
  at INTEGER NOT NULL,
  action TEXT NOT NULL,
  by_kind TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','player','guardian')),
  by_user_id TEXT CHECK (by_user_id IS NULL OR by_kind = 'org'),
  by_name TEXT,
  detail_json TEXT CHECK (detail_json IS NULL OR json_type(detail_json) = 'object'),
  UNIQUE (contact_id, position)
) STRICT;
CREATE TABLE recruitment_offers (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  case_id TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  player_id TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IS NULL OR type IN ('direct_recruitment')),
  decision_id TEXT,
  transaction_id TEXT,
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('DRAFT','ISSUED','ACCEPTED','DECLINED','WITHDRAWN','EXPIRED','SUPERSEDED')),
  current_revision_id TEXT NOT NULL,
  agent_share_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  agent_share_agreement_id TEXT,
  agent_share_at INTEGER,
  agent_share_by_kind TEXT CHECK (agent_share_by_kind IS NULL OR agent_share_by_kind IN ('player')),
  agent_share_by_id TEXT,
  create_key TEXT,
  create_fp TEXT,
  lifecycle_applied INTEGER CHECK (lifecycle_applied IS NULL OR lifecycle_applied IN (0,1)),
  lifecycle_action TEXT,
  lifecycle_reason TEXT,
  lifecycle_message TEXT,
  lifecycle_allowed_json TEXT CHECK (lifecycle_allowed_json IS NULL OR json_type(lifecycle_allowed_json) = 'array'),
  lifecycle_from TEXT,
  lifecycle_to TEXT,
  lifecycle_at INTEGER,
  created_at INTEGER NOT NULL,
  created_by_user_id TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name TEXT,
  created_by_role TEXT,
  updated_at INTEGER NOT NULL,
  rev INTEGER NOT NULL CHECK (rev >= 1),
  rev_at INTEGER,
  rev_by_user_id TEXT,
  rev_by_name TEXT,
  policy_version INTEGER NOT NULL,
  subject_removed_at INTEGER,
  CHECK ((agent_share_user_id IS NULL) = (agent_share_at IS NULL)),
  CHECK ((create_key IS NULL) = (create_fp IS NULL)),
  FOREIGN KEY (id, current_revision_id) REFERENCES offer_revisions(offer_id, id) DEFERRABLE INITIALLY DEFERRED
) STRICT;
CREATE TABLE offer_revisions (
  id TEXT PRIMARY KEY,
  offer_id TEXT NOT NULL REFERENCES recruitment_offers(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  revision_number INTEGER NOT NULL CHECK (revision_number >= 1),
  status TEXT NOT NULL CHECK (status IS NULL OR status IN ('DRAFT','ISSUED','ACCEPTED','DECLINED','WITHDRAWN','EXPIRED','SUPERSEDED')),
  term_offer_type TEXT NOT NULL CHECK (term_offer_type IS NULL OR term_offer_type IN ('direct_recruitment')),
  term_role TEXT CHECK (term_role IS NULL OR length(term_role) <= 80),
  term_squad TEXT CHECK (term_squad IS NULL OR length(term_squad) <= 80),
  term_start_date TEXT CHECK (term_start_date IS NULL OR term_start_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  term_end_date TEXT CHECK (term_end_date IS NULL OR term_end_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
  term_conditions TEXT CHECK (term_conditions IS NULL OR length(term_conditions) <= 1000),
  recipient_message TEXT CHECK (recipient_message IS NULL OR length(recipient_message) <= 2000),
  internal_note TEXT CHECK (internal_note IS NULL OR length(internal_note) <= 2000),
  expires_at INTEGER,
  created_at INTEGER NOT NULL,
  created_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name TEXT,
  created_by_role TEXT,
  updated_at INTEGER NOT NULL,
  updated_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  updated_by_name TEXT,
  updated_by_role TEXT,
  issued_at INTEGER,
  issued_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  issued_by_name TEXT,
  issued_by_role TEXT,
  withdrawn_at INTEGER,
  withdrawn_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  withdrawn_by_name TEXT,
  withdrawn_by_role TEXT,
  withdraw_reason TEXT CHECK (withdraw_reason IS NULL OR length(withdraw_reason) <= 400),
  responded_at INTEGER,
  response_id TEXT,
  supersedes_revision_id TEXT,
  superseded_by_revision_id TEXT,
  superseded_at INTEGER,
  recipient_type TEXT CHECK (recipient_type IS NULL OR recipient_type IN ('player','guardian')),
  recipient_player_id TEXT,
  recipient_guardian_id TEXT,
  recipient_minor INTEGER CHECK (recipient_minor IS NULL OR recipient_minor IN (0,1)),
  recipient_at INTEGER,
  readiness_transaction_id TEXT,
  readiness_evaluated_at INTEGER,
  readiness_status TEXT,
  readiness_blockers_json TEXT CHECK (readiness_blockers_json IS NULL OR json_type(readiness_blockers_json) = 'array'),
  rev INTEGER NOT NULL CHECK (rev >= 1),
  rev_at INTEGER,
  rev_by_user_id TEXT,
  rev_by_name TEXT,
  discarded_by_response_id TEXT,
  CHECK ((recipient_type IS NULL) = (recipient_at IS NULL)),
  UNIQUE (offer_id, id),
  UNIQUE (offer_id, revision_number),
  UNIQUE (offer_id, position),
  FOREIGN KEY (offer_id, supersedes_revision_id) REFERENCES offer_revisions(offer_id, id),
  FOREIGN KEY (offer_id, superseded_by_revision_id) REFERENCES offer_revisions(offer_id, id),
  FOREIGN KEY (offer_id, response_id) REFERENCES offer_responses(offer_id, id),
  FOREIGN KEY (offer_id, discarded_by_response_id) REFERENCES offer_responses(offer_id, id)
) STRICT;
CREATE TABLE offer_revision_documents (
  id TEXT PRIMARY KEY,
  revision_id TEXT NOT NULL REFERENCES offer_revisions(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  evidence_id TEXT NOT NULL,
  label TEXT CHECK (label IS NULL OR length(label) <= 120),
  mime TEXT,
  bytes INTEGER,
  UNIQUE (revision_id, position)
) STRICT;
CREATE TABLE offer_responses (
  id TEXT PRIMARY KEY,
  offer_id TEXT NOT NULL REFERENCES recruitment_offers(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  revision_id TEXT NOT NULL,
  response_type TEXT NOT NULL CHECK (response_type IS NULL OR response_type IN ('accepted','declined')),
  actor_type TEXT NOT NULL CHECK (actor_type IS NULL OR actor_type IN ('player','guardian')),
  actor_id TEXT NOT NULL CHECK (length(actor_id) > 0),
  actor_name TEXT,
  for_player_id TEXT NOT NULL,
  occurred_at INTEGER NOT NULL,
  reason TEXT CHECK (reason IS NULL OR length(reason) <= 400),
  client_key TEXT,
  UNIQUE (offer_id, id),
  UNIQUE (offer_id, revision_id),
  UNIQUE (offer_id, position),
  FOREIGN KEY (offer_id, revision_id) REFERENCES offer_revisions(offer_id, id)
) STRICT;
CREATE TABLE offer_read_receipts (
  offer_id TEXT NOT NULL REFERENCES recruitment_offers(id) ON DELETE CASCADE,
  position INTEGER NOT NULL,
  revision_id TEXT NOT NULL,
  viewer_kind TEXT NOT NULL CHECK (viewer_kind IS NULL OR viewer_kind IN ('player','guardian')),
  viewer_id TEXT NOT NULL,
  first_viewed_at INTEGER NOT NULL,
  PRIMARY KEY (offer_id, position),
  UNIQUE (offer_id, revision_id, viewer_kind, viewer_id),
  FOREIGN KEY (offer_id, revision_id) REFERENCES offer_revisions(offer_id, id)
) STRICT;
CREATE TABLE offer_history (
  id TEXT PRIMARY KEY,
  offer_id TEXT NOT NULL REFERENCES recruitment_offers(id) ON DELETE RESTRICT,
  position INTEGER NOT NULL,
  at INTEGER NOT NULL,
  action TEXT NOT NULL,
  by_kind TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','player','guardian','admin','system')),
  by_id TEXT,
  by_name TEXT,
  detail_json TEXT CHECK (detail_json IS NULL OR json_type(detail_json) = 'object'),
  UNIQUE (offer_id, position)
) STRICT;
CREATE TABLE offer_keys (
  offer_id TEXT NOT NULL REFERENCES recruitment_offers(id) ON DELETE CASCADE,
  act TEXT NOT NULL CHECK (act IS NULL OR act IN ('issue','withdraw','revise')),
  position INTEGER NOT NULL,
  key TEXT NOT NULL,
  revision_id TEXT NOT NULL,
  PRIMARY KEY (offer_id, act, position),
  FOREIGN KEY (offer_id, revision_id) REFERENCES offer_revisions(offer_id, id)
) STRICT;
CREATE TABLE signing_packages (
  id                               TEXT PRIMARY KEY,
  org_id                           TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  case_id                          TEXT NOT NULL REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  player_id                        TEXT NOT NULL,
  offer_id                         TEXT NOT NULL REFERENCES recruitment_offers(id) ON DELETE RESTRICT,
  offer_revision_id                TEXT NOT NULL,
  transaction_id                   TEXT,
  status                           TEXT NOT NULL CHECK (status IN ('DRAFT','READY','IN_PROGRESS','COMPLETED','CANCELLED','VOIDED')),
  current_revision_id              TEXT NOT NULL,
  expires_at                       INTEGER,
  internal_note                    TEXT CHECK (internal_note IS NULL OR length(internal_note) <= 2000),
  completion_signing_id            TEXT REFERENCES signings(id) DEFERRABLE INITIALLY DEFERRED,
  completion_completed_at          INTEGER,
  completion_by_kind               TEXT CHECK (completion_by_kind IS NULL OR completion_by_kind IN ('org','player','guardian','admin','system')),
  completion_by_user_id            TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  completion_by_name               TEXT,
  completion_by_role               TEXT,
  completion_contract_start_date   TEXT CHECK (completion_contract_start_date IS NULL OR length(completion_contract_start_date) = 10),
  completion_contract_end_date     TEXT CHECK (completion_contract_end_date IS NULL OR length(completion_contract_end_date) = 10),
  completion_document_sha256       TEXT CHECK (completion_document_sha256 IS NULL OR length(completion_document_sha256) = 64),
  completion_lifecycle_from        TEXT,
  completion_lifecycle_to          TEXT,
  completion_lifecycle_at          INTEGER,
  cancelled_at                     INTEGER,
  cancelled_by_kind                TEXT CHECK (cancelled_by_kind IS NULL OR cancelled_by_kind IN ('org','player','guardian','admin','system')),
  cancelled_by_user_id             TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  cancelled_by_name                TEXT,
  cancelled_by_role                TEXT,
  cancel_reason                    TEXT CHECK (cancel_reason IS NULL OR length(cancel_reason) <= 500),
  voided_at                        INTEGER,
  voided_by_kind                   TEXT CHECK (voided_by_kind IS NULL OR voided_by_kind IN ('org','player','guardian','admin','system')),
  voided_by_id                     TEXT,
  voided_by_name                   TEXT,
  voided_by_role                   TEXT,
  void_reason                      TEXT CHECK (void_reason IS NULL OR length(void_reason) <= 500),
  created_at                       INTEGER NOT NULL,
  created_by_kind                  TEXT CHECK (created_by_kind IS NULL OR created_by_kind IN ('org','player','guardian','admin','system')),
  created_by_user_id               TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name                  TEXT,
  created_by_role                  TEXT,
  updated_at                       INTEGER NOT NULL,
  rev                              INTEGER NOT NULL DEFAULT 1 CHECK (rev >= 1),
  rev_at                           INTEGER,
  rev_by_user_id                   TEXT,
  rev_by_name                      TEXT,
  policy_version                   INTEGER NOT NULL DEFAULT 1,
  subject_removed_at               INTEGER,
  CHECK ((status = 'COMPLETED') = (completion_signing_id IS NOT NULL)),
  CHECK ((voided_at IS NULL) = (voided_by_kind IS NULL))
) STRICT;
CREATE TABLE signing_revisions (
  id                               TEXT PRIMARY KEY,
  package_id                       TEXT NOT NULL REFERENCES signing_packages(id) ON DELETE CASCADE,
  position                         INTEGER NOT NULL,
  revision_number                  INTEGER NOT NULL CHECK (revision_number >= 1),
  status                           TEXT NOT NULL CHECK (status IN ('DRAFT','READY','IN_PROGRESS','COMPLETED','CANCELLED','VOIDED','SUPERSEDED')),
  created_at                       INTEGER NOT NULL,
  created_by_kind                  TEXT CHECK (created_by_kind IS NULL OR created_by_kind IN ('org','player','guardian','admin','system')),
  created_by_user_id               TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name                  TEXT,
  created_by_role                  TEXT,
  ready_at                         INTEGER,
  ready_by_kind                    TEXT CHECK (ready_by_kind IS NULL OR ready_by_kind IN ('org','player','guardian','admin','system')),
  ready_by_user_id                 TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  ready_by_name                    TEXT,
  ready_by_role                    TEXT,
  completed_at                     INTEGER,
  completed_by_kind                TEXT CHECK (completed_by_kind IS NULL OR completed_by_kind IN ('org','player','guardian','admin','system')),
  completed_by_user_id             TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  completed_by_name                TEXT,
  completed_by_role                TEXT,
  superseded_at                    INTEGER,
  contract_start_date              TEXT CHECK (contract_start_date IS NULL OR length(contract_start_date) = 10),
  contract_end_date                TEXT CHECK (contract_end_date IS NULL OR length(contract_end_date) = 10),
  policy_version                   INTEGER,
  policy_jurisdiction              TEXT,
  policy_offer_policy_version      INTEGER,
  supersedes_revision_id           TEXT,
  superseded_by_revision_id        TEXT,
  UNIQUE (package_id, revision_number),
  UNIQUE (package_id, position)
) STRICT;
CREATE TABLE signing_documents (
  id                               TEXT PRIMARY KEY,
  revision_id                      TEXT NOT NULL REFERENCES signing_revisions(id) ON DELETE CASCADE,
  kind                             TEXT NOT NULL CHECK (kind IN ('signing','executed')),
  evidence_id                      TEXT NOT NULL,
  sha256                           TEXT NOT NULL CHECK (length(sha256) = 64),
  filename                         TEXT,
  mime                             TEXT,
  bytes                            INTEGER,
  label                            TEXT CHECK (label IS NULL OR length(label) <= 120),
  uploaded_at                      INTEGER NOT NULL,
  uploaded_by_kind                 TEXT CHECK (uploaded_by_kind IS NULL OR uploaded_by_kind IN ('org','player','guardian','admin','system')),
  uploaded_by_user_id              TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  uploaded_by_name                 TEXT,
  uploaded_by_role                 TEXT,
  UNIQUE (revision_id, kind)
) STRICT;
CREATE TABLE signing_revision_parties (
  revision_id                      TEXT NOT NULL REFERENCES signing_revisions(id) ON DELETE CASCADE,
  position                         INTEGER NOT NULL,
  party_type                       TEXT NOT NULL CHECK (party_type IN ('PLAYER','GUARDIAN','CLUB_SIGNATORY')),
  for_entity_id                    TEXT,
  for_player_id                    TEXT,
  status                           TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','COMPLETED')),
  completed_at                     INTEGER,
  completed_by_kind                TEXT CHECK (completed_by_kind IS NULL OR completed_by_kind IN ('org','player','guardian','admin','system')),
  completed_by_id                  TEXT,
  completed_by_name                TEXT,
  method                           TEXT CHECK (method IS NULL OR method IN ('PLATFORM_ACKNOWLEDGMENT','UPLOAD_EXECUTED_DOCUMENT')),
  evidence_ref_kind                TEXT CHECK (evidence_ref_kind IS NULL OR evidence_ref_kind IN ('platform_acknowledgment')),
  evidence_ref_id                  TEXT,
  evidence_revision_id             TEXT,
  evidence_document_sha256         TEXT CHECK (evidence_document_sha256 IS NULL OR length(evidence_document_sha256) = 64),
  evidence_at                      INTEGER,
  evidence_actor_kind              TEXT,
  evidence_actor_id                TEXT,
  evidence_session                 TEXT,
  PRIMARY KEY (revision_id, party_type),
  UNIQUE (revision_id, position),
  CHECK ((status = 'COMPLETED') = (completed_at IS NOT NULL))
) STRICT;
CREATE TABLE signing_history (
  id                               TEXT PRIMARY KEY,
  package_id                       TEXT NOT NULL REFERENCES signing_packages(id) ON DELETE RESTRICT,
  position                         INTEGER NOT NULL,
  at                               INTEGER NOT NULL,
  by_kind                          TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','player','guardian','admin','system')),
  by_id                            TEXT,
  by_name                          TEXT,
  action                           TEXT NOT NULL,
  detail_json                      TEXT CHECK (detail_json IS NULL OR json_valid(detail_json)),
  UNIQUE (package_id, position)
) STRICT;
CREATE TABLE signings (
  id                               TEXT PRIMARY KEY,
  player_id                        TEXT NOT NULL,
  player_name                      TEXT,
  org_id                           TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name                         TEXT,
  user_id                          TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  scout_name                       TEXT,
  ts                               INTEGER NOT NULL,
  signed_at                        INTEGER,
  first_qualifying_ledger_id       TEXT,
  first_qualifying_at              INTEGER,
  first_qualifying_type            TEXT,
  attribution_window_months        INTEGER,
  inside_attribution_window        INTEGER NOT NULL DEFAULT 0 CHECK (inside_attribution_window IN (0,1)),
  method                           TEXT NOT NULL DEFAULT 'LEGACY_RECORDED' CHECK (method IN ('CANONICAL_COMPLETION','LEGACY_RECORDED')),
  note                             TEXT CHECK (note IS NULL OR length(note) <= 400),
  signing_package_id               TEXT REFERENCES signing_packages(id) ON DELETE RESTRICT,
  signing_revision_id              TEXT REFERENCES signing_revisions(id) ON DELETE RESTRICT,
  signing_revision_number          INTEGER,
  case_id                          TEXT REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  offer_id                         TEXT REFERENCES recruitment_offers(id) ON DELETE RESTRICT,
  offer_revision_id                TEXT,
  transaction_id                   TEXT,
  document_sha256                  TEXT CHECK (document_sha256 IS NULL OR length(document_sha256) = 64),
  document_evidence_id             TEXT,
  executed_document_evidence_id    TEXT,
  contract_start_date              TEXT CHECK (contract_start_date IS NULL OR length(contract_start_date) = 10),
  contract_end_date                TEXT CHECK (contract_end_date IS NULL OR length(contract_end_date) = 10),
  policy_version                   INTEGER,
  CHECK ((method = 'CANONICAL_COMPLETION') = (signing_package_id IS NOT NULL))
) STRICT;
CREATE TABLE signing_parties (
  signing_id                       TEXT NOT NULL REFERENCES signings(id) ON DELETE CASCADE,
  position                         INTEGER NOT NULL,
  party_type                       TEXT NOT NULL CHECK (party_type IN ('PLAYER','GUARDIAN','CLUB_SIGNATORY')),
  method                           TEXT CHECK (method IS NULL OR method IN ('PLATFORM_ACKNOWLEDGMENT','UPLOAD_EXECUTED_DOCUMENT')),
  completed_at                     INTEGER,
  by_kind                          TEXT CHECK (by_kind IS NULL OR by_kind IN ('org','player','guardian','admin','system')),
  PRIMARY KEY (signing_id, party_type),
  UNIQUE (signing_id, position)
) STRICT;
CREATE TABLE follow_ups (
  id                               TEXT PRIMARY KEY,
  signing_id                       TEXT NOT NULL REFERENCES signings(id) ON DELETE RESTRICT,
  player_id                        TEXT NOT NULL,
  org_id                           TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  milestone                        TEXT NOT NULL CHECK (milestone IN ('3m','6m','12m')),
  due_at                           INTEGER NOT NULL,
  status                           TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','due','complete')),
  notified_at                      INTEGER,
  created_at                       INTEGER NOT NULL,
  UNIQUE (signing_id, milestone)
) STRICT;
CREATE TABLE outcome_reports (
  id                               TEXT PRIMARY KEY,
  follow_up_id                     TEXT NOT NULL UNIQUE REFERENCES follow_ups(id) ON DELETE RESTRICT,
  signing_id                       TEXT NOT NULL REFERENCES signings(id) ON DELETE RESTRICT,
  player_id                        TEXT NOT NULL,
  org_id                           TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  by_user_id                       TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  by_name                          TEXT,
  registration_status              TEXT NOT NULL CHECK (registration_status IN ('registered','released','left','unknown')),
  matches_played                   INTEGER CHECK (matches_played IS NULL OR matches_played >= 0),
  progression                      TEXT CHECK (progression IS NULL OR length(progression) <= 200),
  end_reason                       TEXT CHECK (end_reason IS NULL OR length(end_reason) <= 200),
  note                             TEXT CHECK (note IS NULL OR length(note) <= 300),
  status                           TEXT NOT NULL DEFAULT 'reported' CHECK (status IN ('reported','confirmed','disputed')),
  at                               INTEGER NOT NULL
) STRICT;
CREATE TABLE outcome_report_confirmations (
  report_id                        TEXT NOT NULL REFERENCES outcome_reports(id) ON DELETE CASCADE,
  position                         INTEGER NOT NULL,
  by_kind                          TEXT NOT NULL CHECK (by_kind IN ('player','guardian')),
  by_id                            TEXT NOT NULL,
  by_name                          TEXT,
  agree                            INTEGER NOT NULL CHECK (agree IN (0,1)),
  note                             TEXT CHECK (note IS NULL OR length(note) <= 300),
  experience_rating                INTEGER CHECK (experience_rating IS NULL OR experience_rating BETWEEN 1 AND 5),
  at                               INTEGER NOT NULL,
  PRIMARY KEY (report_id, by_id),
  UNIQUE (report_id, position)
) STRICT;
CREATE TABLE idempotency_keys (
  owner_table                      TEXT NOT NULL CHECK (owner_table IN ('signing_packages')),
  owner_id                         TEXT NOT NULL,
  position                         INTEGER NOT NULL,
  act                              TEXT NOT NULL,
  shape                            TEXT NOT NULL CHECK (shape IN ('list', 'value')),
  key                              TEXT,
  fp                               TEXT,
  at                               INTEGER,
  entry_json                       TEXT NOT NULL CHECK (entry_json IS NULL OR json_valid(entry_json)),
  PRIMARY KEY (owner_table, owner_id, position)
) STRICT;
CREATE TABLE evidence (
  id                  TEXT PRIMARY KEY,
  player_id           TEXT NOT NULL,
  claim_type          TEXT NOT NULL CHECK (claim_type IN ('statistic','attendance','assessment_result','reference','footage','availability')),
  label               TEXT NOT NULL CHECK (length(label) <= 120),
  value_number        REAL,
  value_text          TEXT CHECK (value_text IS NULL OR length(value_text) <= 120),
  units               TEXT CHECK (units IS NULL OR length(units) <= 20),
  season              TEXT CHECK (season IS NULL OR length(season) <= 20),
  source_kind         TEXT NOT NULL CHECK (source_kind IN ('player','guardian','org')),
  source_id           TEXT NOT NULL,
  source_name         TEXT NOT NULL CHECK (length(source_name) <= 200),
  observed_at         INTEGER,
  recorded_at         INTEGER NOT NULL,
  verification_status TEXT NOT NULL CHECK (verification_status IN ('self_reported','coach_confirmed','club_assessed')),
  verification_method TEXT CHECK (verification_method IS NULL OR length(verification_method) <= 80),
  reviewer_id         TEXT,
  reviewer_name       TEXT CHECK (reviewer_name IS NULL OR length(reviewer_name) <= 200),
  reviewed_at         INTEGER,
  expires_at          INTEGER,
  correction_of_id    TEXT REFERENCES evidence(id) ON DELETE RESTRICT,
  superseded_by_id    TEXT REFERENCES evidence(id) ON DELETE RESTRICT,
  note                TEXT CHECK (note IS NULL OR length(note) <= 300),
  CHECK (value_number IS NULL OR value_text IS NULL)
) STRICT;
CREATE TABLE evidence_media (
  evidence_id TEXT NOT NULL REFERENCES evidence(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  media_id    TEXT NOT NULL,
  PRIMARY KEY (evidence_id, position),
  UNIQUE (evidence_id, media_id)
) STRICT;
CREATE TABLE evidence_disputes (
  id                 TEXT PRIMARY KEY,
  evidence_id        TEXT NOT NULL REFERENCES evidence(id) ON DELETE CASCADE,
  position           INTEGER NOT NULL,
  filed_at           INTEGER NOT NULL,
  by_kind            TEXT NOT NULL CHECK (by_kind IN ('player','org')),
  by_id              TEXT NOT NULL,
  by_name            TEXT NOT NULL CHECK (length(by_name) <= 200),
  reason             TEXT NOT NULL CHECK (length(reason) <= 300),
  status             TEXT NOT NULL CHECK (status IN ('open','resolved')),
  resolution_outcome TEXT CHECK (resolution_outcome IS NULL OR resolution_outcome IN ('upheld','rejected')),
  resolution_note    TEXT CHECK (resolution_note IS NULL OR length(resolution_note) <= 300),
  resolved_at        INTEGER,
  UNIQUE (evidence_id, position),
  CHECK ((status = 'resolved') = (resolution_outcome IS NOT NULL AND resolved_at IS NOT NULL))
) STRICT;
CREATE TABLE evidence_history (
  id          TEXT PRIMARY KEY,
  evidence_id    TEXT NOT NULL REFERENCES evidence(id) ON DELETE RESTRICT,
  position    INTEGER NOT NULL,
  at          INTEGER NOT NULL,
  by_kind     TEXT CHECK (by_kind IS NULL OR by_kind IN ('player','guardian','org','admin')),
  by_id       TEXT,
  by_name     TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action      TEXT NOT NULL,
  detail      TEXT CHECK (detail IS NULL OR length(detail) <= 500),
  UNIQUE (evidence_id, position)
) STRICT;
CREATE TABLE coach_affiliations (
  id                   TEXT PRIMARY KEY,
  org_id               TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name             TEXT NOT NULL CHECK (length(org_name) <= 200),
  coach_name           TEXT NOT NULL CHECK (length(coach_name) <= 80),
  coach_email          TEXT CHECK (coach_email IS NULL OR length(coach_email) <= 120),
  role                 TEXT NOT NULL CHECK (length(role) <= 60),
  from_date            TEXT NOT NULL CHECK (length(from_date) = 10),
  to_date              TEXT CHECK (to_date IS NULL OR length(to_date) = 10),
  status               TEXT NOT NULL CHECK (status IN ('confirmed','ended','revoked')),
  confirmed_by_user_id TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  confirmed_by_name    TEXT NOT NULL CHECK (length(confirmed_by_name) <= 200),
  conflict_of_interest TEXT CHECK (conflict_of_interest IS NULL OR length(conflict_of_interest) <= 200),
  created_at           INTEGER NOT NULL,
  CHECK ((status = 'confirmed') = (to_date IS NULL))
) STRICT;
CREATE TABLE coach_affiliation_history (
  id          TEXT PRIMARY KEY,
  affiliation_id    TEXT NOT NULL REFERENCES coach_affiliations(id) ON DELETE RESTRICT,
  position    INTEGER NOT NULL,
  at          INTEGER NOT NULL,
  by_kind     TEXT CHECK (by_kind IS NULL OR by_kind IN ('player','guardian','org','admin')),
  by_id       TEXT,
  by_name     TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action      TEXT NOT NULL,
  detail      TEXT CHECK (detail IS NULL OR length(detail) <= 500),
  UNIQUE (affiliation_id, position)
) STRICT;
CREATE TABLE squad_invites (
  id           TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name     TEXT NOT NULL CHECK (length(org_name) <= 200),
  player_id    TEXT NOT NULL,
  player_name  TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  by_user_id   TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  by_name      TEXT NOT NULL CHECK (length(by_name) <= 200),
  note         TEXT CHECK (note IS NULL OR length(note) <= 200),
  status       TEXT NOT NULL CHECK (status IN ('pending_guardian','pending_player','approved','declined')),
  created_at   INTEGER NOT NULL,
  responded_at INTEGER,
  CHECK ((status IN ('approved','declined')) = (responded_at IS NOT NULL))
) STRICT;
CREATE TABLE assessment_templates (
  id              TEXT NOT NULL,
  version         INTEGER NOT NULL CHECK (version >= 1),
  position_group  TEXT NOT NULL CHECK (position_group IN ('GK','DEF','MID','ATT')),
  created_at      INTEGER NOT NULL,
  created_by_name TEXT NOT NULL CHECK (length(created_by_name) <= 200),
  PRIMARY KEY (id, version),
  UNIQUE (position_group, version)
) STRICT;
CREATE TABLE assessment_template_attributes (
  template_id      TEXT NOT NULL,
  template_version INTEGER NOT NULL,
  position         INTEGER NOT NULL,
  attr_id          TEXT NOT NULL CHECK (length(attr_id) <= 40),
  label            TEXT NOT NULL CHECK (length(label) <= 80),
  anchor_1         TEXT CHECK (anchor_1 IS NULL OR length(anchor_1) <= 200),
  anchor_2         TEXT CHECK (anchor_2 IS NULL OR length(anchor_2) <= 200),
  anchor_3         TEXT CHECK (anchor_3 IS NULL OR length(anchor_3) <= 200),
  anchor_4         TEXT CHECK (anchor_4 IS NULL OR length(anchor_4) <= 200),
  anchor_5         TEXT CHECK (anchor_5 IS NULL OR length(anchor_5) <= 200),
  PRIMARY KEY (template_id, template_version, position),
  UNIQUE (template_id, template_version, attr_id),
  FOREIGN KEY (template_id, template_version) REFERENCES assessment_templates(id, version) ON DELETE CASCADE
) STRICT;
CREATE TABLE video_segments (
  id                 TEXT PRIMARY KEY,
  media_id           TEXT NOT NULL,
  player_id          TEXT NOT NULL,
  org_id             TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  created_by_user_id TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name    TEXT NOT NULL CHECK (length(created_by_name) <= 200),
  start_s            REAL NOT NULL CHECK (start_s >= 0),
  end_s              REAL NOT NULL CHECK (end_s > start_s AND end_s - start_s <= 600),
  event_type         TEXT CHECK (event_type IS NULL OR length(event_type) <= 40),
  note               TEXT CHECK (note IS NULL OR length(note) <= 300),
  drawing_json       TEXT CHECK (drawing_json IS NULL OR (json_valid(drawing_json) AND json_type(drawing_json) = 'object' AND length(drawing_json) <= 4000)),
  created_at         INTEGER NOT NULL
) STRICT;
CREATE TABLE video_segment_labels (
  segment_id TEXT NOT NULL REFERENCES video_segments(id) ON DELETE CASCADE,
  position   INTEGER NOT NULL CHECK (position BETWEEN 0 AND 7),
  label      TEXT NOT NULL CHECK (length(label) <= 30),
  PRIMARY KEY (segment_id, position)
) STRICT;
CREATE TABLE playlists (
  id                 TEXT PRIMARY KEY,
  org_id             TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  name               TEXT NOT NULL CHECK (length(name) <= 80),
  created_by_user_id TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  created_by_name    TEXT NOT NULL CHECK (length(created_by_name) <= 200),
  created_at         INTEGER NOT NULL
) STRICT;
CREATE TABLE playlist_segments (
  playlist_id TEXT NOT NULL REFERENCES playlists(id) ON DELETE CASCADE,
  position    INTEGER NOT NULL,
  segment_id  TEXT NOT NULL REFERENCES video_segments(id) ON DELETE RESTRICT,
  PRIMARY KEY (playlist_id, position),
  UNIQUE (playlist_id, segment_id)
) STRICT;
CREATE TABLE assessments (
  id                            TEXT PRIMARY KEY,
  org_id                        TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id                     TEXT NOT NULL,
  player_name                   TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  scout_user_id                 TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  scout_name                    TEXT NOT NULL CHECK (length(scout_name) <= 200),
  template_id                   TEXT NOT NULL,
  template_version              INTEGER NOT NULL,
  context_fixture               TEXT CHECK (context_fixture IS NULL OR length(context_fixture) <= 120),
  context_date                  TEXT CHECK (context_date IS NULL OR length(context_date) = 10),
  context_minutes_watched       INTEGER CHECK (context_minutes_watched IS NULL OR context_minutes_watched BETWEEN 1 AND 600),
  context_viewing               TEXT CHECK (context_viewing IS NULL OR context_viewing IN ('live','video')),
  context_opponent_level        TEXT CHECK (context_opponent_level IS NULL OR length(context_opponent_level) <= 60),
  context_trial_id              TEXT,
  context_trial_session_id      TEXT CHECK (context_trial_session_id IS NULL OR context_trial_id IS NOT NULL),
  state                         TEXT NOT NULL CHECK (state IN ('draft','submitted','reviewed')),
  recommendation_verdict        TEXT CHECK (recommendation_verdict IS NULL OR recommendation_verdict IN ('sign','monitor','pass')),
  recommendation_reasons        TEXT CHECK (recommendation_reasons IS NULL OR length(recommendation_reasons) <= 500),
  second_opinion_of_id          TEXT REFERENCES assessments(id) ON DELETE RESTRICT,
  created_at                    INTEGER NOT NULL,
  submitted_at                  INTEGER,
  reviewed_at                   INTEGER,
  review_note                   TEXT CHECK (review_note IS NULL OR length(review_note) <= 300),
  published_feedback_text       TEXT CHECK (published_feedback_text IS NULL OR length(published_feedback_text) <= 800),
  published_feedback_by_user_id TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  published_feedback_by_name    TEXT CHECK (published_feedback_by_name IS NULL OR length(published_feedback_by_name) <= 200),
  published_feedback_at         INTEGER,
  FOREIGN KEY (template_id, template_version) REFERENCES assessment_templates(id, version) ON DELETE RESTRICT,
  CHECK ((state = 'draft') = (submitted_at IS NULL)),
  CHECK ((state = 'reviewed') = (reviewed_at IS NOT NULL)),
  CHECK (review_note IS NULL OR state = 'reviewed'),
  CHECK ((recommendation_verdict IS NULL) = (recommendation_reasons IS NULL)),
  CHECK ((published_feedback_text IS NULL) = (published_feedback_by_user_id IS NULL) AND (published_feedback_text IS NULL) = (published_feedback_by_name IS NULL) AND (published_feedback_text IS NULL) = (published_feedback_at IS NULL)),
  CHECK (published_feedback_text IS NULL OR state <> 'draft')
) STRICT;
CREATE TABLE assessment_ratings (
  assessment_id TEXT NOT NULL REFERENCES assessments(id) ON DELETE CASCADE,
  position      INTEGER NOT NULL,
  attr_id       TEXT NOT NULL CHECK (length(attr_id) <= 40),
  rating        INTEGER CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  not_observed  INTEGER NOT NULL CHECK (not_observed IN (0,1)),
  confidence    TEXT NOT NULL CHECK (confidence IN ('low','medium','high')),
  note          TEXT CHECK (note IS NULL OR length(note) <= 300),
  PRIMARY KEY (assessment_id, position),
  UNIQUE (assessment_id, attr_id),
  CHECK ((not_observed = 1) = (rating IS NULL))
) STRICT;
CREATE TABLE assessment_rating_refs (
  assessment_id    TEXT NOT NULL,
  rating_position  INTEGER NOT NULL,
  position         INTEGER NOT NULL CHECK (position BETWEEN 0 AND 5),
  segment_id       TEXT REFERENCES video_segments(id) ON DELETE RESTRICT,
  trial_session_id TEXT CHECK (trial_session_id IS NULL OR length(trial_session_id) <= 80),
  box_session_id   TEXT CHECK (box_session_id IS NULL OR length(box_session_id) <= 80),
  t_s              REAL CHECK (t_s IS NULL OR t_s >= 0),
  label            TEXT CHECK (label IS NULL OR length(label) <= 80),
  PRIMARY KEY (assessment_id, rating_position, position),
  FOREIGN KEY (assessment_id, rating_position) REFERENCES assessment_ratings(assessment_id, position) ON DELETE CASCADE
) STRICT;
CREATE TABLE assessment_history (
  id          TEXT PRIMARY KEY,
  assessment_id    TEXT NOT NULL REFERENCES assessments(id) ON DELETE RESTRICT,
  position    INTEGER NOT NULL,
  at          INTEGER NOT NULL,
  by_kind     TEXT CHECK (by_kind IS NULL OR by_kind IN ('player','guardian','org','admin')),
  by_id       TEXT,
  by_name     TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action      TEXT NOT NULL,
  detail      TEXT CHECK (detail IS NULL OR length(detail) <= 500),
  UNIQUE (assessment_id, position)
) STRICT;
CREATE TABLE org_tactical_setups (
  org_id           TEXT PRIMARY KEY REFERENCES orgs(id) ON DELETE RESTRICT,
  formation        TEXT NOT NULL CHECK (length(formation) BETWEEN 1 AND 20),
  planning_horizon TEXT CHECK (planning_horizon IS NULL OR length(planning_horizon) <= 40),
  updated_at       INTEGER NOT NULL,
  updated_by_name  TEXT NOT NULL CHECK (length(updated_by_name) <= 200)
) STRICT;
CREATE TABLE org_tactical_roles (
  id             TEXT PRIMARY KEY,
  org_id         TEXT NOT NULL REFERENCES org_tactical_setups(org_id) ON DELETE CASCADE,
  ordinal        INTEGER NOT NULL CHECK (ordinal >= 0),
  name           TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 60),
  position_group TEXT NOT NULL CHECK (position_group IN ('GK','DEF','MID','ATT')),
  description    TEXT NOT NULL CHECK (length(description) <= 300),
  category       TEXT NOT NULL CHECK (category IN ('mens','womens','boys','girls','mixed')),
  UNIQUE (org_id, id)
) STRICT;
CREATE TABLE org_tactical_role_criteria (
  role_id      TEXT NOT NULL REFERENCES org_tactical_roles(id) ON DELETE CASCADE,
  kind         TEXT NOT NULL CHECK (kind IN ('required','preferred')),
  ordinal      INTEGER NOT NULL CHECK (ordinal >= 0),
  key          TEXT NOT NULL CHECK (key IN ('positionGroup','minAge','maxAge','foot','availability','maxLevel','minAppearances','category')),
  value_number INTEGER,
  value_text   TEXT CHECK (value_text IS NULL OR length(value_text) <= 40),
  PRIMARY KEY (role_id, kind, ordinal),
  UNIQUE (role_id, kind, key),
  CHECK ((value_number IS NULL) <> (value_text IS NULL)),
  CHECK ((key IN ('minAge','maxAge','minAppearances')) = (value_number IS NOT NULL))
) STRICT;
CREATE TABLE org_tactical_windows (
  org_id  TEXT NOT NULL REFERENCES org_tactical_setups(org_id) ON DELETE CASCADE,
  ordinal INTEGER NOT NULL CHECK (ordinal >= 0),
  name    TEXT NOT NULL CHECK (length(name) <= 40),
  opens   TEXT CHECK (opens IS NULL OR length(opens) = 10),
  closes  TEXT CHECK (closes IS NULL OR length(closes) = 10),
  PRIMARY KEY (org_id, ordinal),
  CHECK (opens IS NULL OR closes IS NULL OR opens <= closes)
) STRICT;
CREATE TABLE org_squad_members (
  id                TEXT PRIMARY KEY,
  org_id            TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id         TEXT,
  name              TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  position          TEXT CHECK (position IS NULL OR length(position) <= 40),
  source            TEXT NOT NULL CHECK (source IN ('manual','invite_approved','signing')),
  approved_by_label TEXT CHECK (approved_by_label IS NULL OR length(approved_by_label) <= 200),
  added_at          INTEGER NOT NULL,
  CHECK ((source = 'invite_approved') = (approved_by_label IS NOT NULL)),
  CHECK (source = 'manual' OR player_id IS NOT NULL)
) STRICT;
CREATE TABLE org_shadow_players (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id     TEXT NOT NULL,
  name          TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
  role_id       TEXT REFERENCES org_tactical_roles(id) ON DELETE SET NULL,
  added_by_name TEXT NOT NULL CHECK (length(added_by_name) <= 200),
  added_at      INTEGER NOT NULL,
  UNIQUE (org_id, player_id)
) STRICT;
CREATE TABLE org_looking_for (
  org_id   TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  ordinal  INTEGER NOT NULL CHECK (ordinal BETWEEN 0 AND 4),
  position TEXT NOT NULL CHECK (position IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  PRIMARY KEY (org_id, ordinal),
  UNIQUE (org_id, position)
) STRICT;
CREATE TABLE org_federation_checks (
  org_id          TEXT PRIMARY KEY REFERENCES orgs(id) ON DELETE RESTRICT,
  federation      TEXT NOT NULL CHECK (length(federation) BETWEEN 1 AND 120),
  registration_id TEXT NOT NULL CHECK (length(registration_id) BETWEEN 1 AND 60),
  contact_email   TEXT CHECK (contact_email IS NULL OR length(contact_email) <= 120),
  status          TEXT NOT NULL CHECK (status IN ('pending')),
  submitted_at    INTEGER NOT NULL
) STRICT;
CREATE TABLE vacancies (
  id              TEXT PRIMARY KEY,
  org_id          TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  role_id         TEXT REFERENCES org_tactical_roles(id) ON DELETE SET NULL,
  role_name       TEXT NOT NULL CHECK (length(role_name) BETWEEN 1 AND 60),
  window_name     TEXT CHECK (window_name IS NULL OR length(window_name) <= 40),
  notes           TEXT CHECK (notes IS NULL OR length(notes) <= 300),
  status          TEXT NOT NULL CHECK (status IN ('open','closed')),
  created_by_name TEXT NOT NULL CHECK (length(created_by_name) <= 200),
  created_at      INTEGER NOT NULL,
  closed_at       INTEGER,
  CHECK ((status = 'closed') = (closed_at IS NOT NULL))
) STRICT;
CREATE TABLE opportunities (
  id                  TEXT PRIMARY KEY,
  org_id              TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name            TEXT NOT NULL CHECK (length(org_name) <= 200),
  org_level           TEXT NOT NULL CHECK (org_level IN ('pro','academy','agency','grassroots')),
  type                TEXT NOT NULL CHECK (type IN ('trial','open_day','programme','role')),
  title               TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
  team                TEXT CHECK (team IS NULL OR length(team) <= 60),
  category            TEXT NOT NULL CHECK (category IN ('mens','womens','boys','girls','mixed')),
  age_group           TEXT CHECK (age_group IS NULL OR length(age_group) <= 20),
  role                TEXT CHECK (role IS NULL OR length(role) <= 60),
  description         TEXT CHECK (description IS NULL OR length(description) <= 500),
  schedule            TEXT CHECK (schedule IS NULL OR length(schedule) <= 200),
  deadline            TEXT NOT NULL CHECK (length(deadline) = 10),
  capacity            INTEGER CHECK (capacity IS NULL OR capacity >= 1),
  elig_min_age        INTEGER CHECK (elig_min_age IS NULL OR elig_min_age BETWEEN 4 AND 99),
  elig_max_age        INTEGER CHECK (elig_max_age IS NULL OR elig_max_age BETWEEN 4 AND 99),
  elig_position_group TEXT NOT NULL CHECK (elig_position_group IN ('any','GK','DEF','MID','ATT')),
  elig_category       TEXT NOT NULL CHECK (elig_category IN ('mens','womens','boys','girls','mixed')),
  elig_max_level      TEXT CHECK (elig_max_level IS NULL OR elig_max_level IN ('amateur','semi_pro','pro')),
  elig_radius_km      REAL CHECK (elig_radius_km IS NULL OR elig_radius_km BETWEEN 0 AND 1000),
  status              TEXT NOT NULL CHECK (status IN ('published','closed')),
  created_by_name     TEXT NOT NULL CHECK (length(created_by_name) <= 200),
  created_at          INTEGER NOT NULL,
  closed_at           INTEGER,
  structured_declared INTEGER NOT NULL CHECK (structured_declared IN (0,1)),
  relocation_required INTEGER NOT NULL CHECK (relocation_required IN (0,1)),
  fee_minor           INTEGER CHECK (fee_minor IS NULL OR fee_minor >= 0),
  currency            TEXT CHECK (currency IS NULL OR (length(currency) = 3 AND currency GLOB '[A-Z][A-Z][A-Z]')),
  expenses_covered    INTEGER NOT NULL CHECK (expenses_covered IN (0,1)),
  CHECK ((status = 'closed') = (closed_at IS NOT NULL)),
  CHECK (elig_min_age IS NULL OR elig_max_age IS NULL OR elig_min_age <= elig_max_age),
  CHECK ((structured_declared = 1) = (currency IS NOT NULL)),
  CHECK (structured_declared = 1 OR (relocation_required = 0 AND expenses_covered = 0 AND fee_minor IS NULL))
) STRICT;
CREATE TABLE opportunity_training_slots (
  opportunity_id TEXT NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,
  ordinal    INTEGER NOT NULL CHECK (ordinal >= 0),
  day        TEXT NOT NULL CHECK (day IN ('mon','tue','wed','thu','fri','sat','sun')),
  start_time TEXT NOT NULL CHECK (length(start_time) = 5 AND start_time GLOB '[0-2][0-9]:[0-5][0-9]' AND start_time <= '23:59'),
  end_time   TEXT NOT NULL CHECK (length(end_time) = 5 AND end_time GLOB '[0-2][0-9]:[0-5][0-9]' AND end_time <= '23:59'),
  tz         TEXT NOT NULL CHECK (length(tz) BETWEEN 1 AND 40),
  PRIMARY KEY (opportunity_id, ordinal),
  CHECK (start_time < end_time)
) STRICT;
CREATE TABLE opportunity_texts (
  opportunity_id TEXT NOT NULL REFERENCES opportunities(id) ON DELETE CASCADE,
  kind           TEXT NOT NULL CHECK (kind IN ('requirement','environment','accommodation')),
  ordinal        INTEGER NOT NULL CHECK (ordinal >= 0),
  text           TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 120),
  PRIMARY KEY (opportunity_id, kind, ordinal)
) STRICT;
CREATE TABLE applications (
  id                      TEXT PRIMARY KEY,
  opportunity_id          TEXT NOT NULL REFERENCES opportunities(id) ON DELETE RESTRICT,
  org_id                  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id               TEXT NOT NULL,
  player_name             TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  submitted_by_kind       TEXT NOT NULL CHECK (submitted_by_kind IN ('player','guardian')),
  submitted_by_id         TEXT NOT NULL CHECK (length(submitted_by_id) BETWEEN 1 AND 80),
  submitted_by_name       TEXT CHECK (submitted_by_name IS NULL OR length(submitted_by_name) <= 200),
  note                    TEXT CHECK (note IS NULL OR length(note) <= 300),
  status                  TEXT NOT NULL CHECK (status IN ('submitted','withdrawn','accepted','declined')),
  outcome_note            TEXT CHECK (outcome_note IS NULL OR length(outcome_note) <= 300),
  outcome_by_user_id      TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  outcome_by_name         TEXT CHECK (outcome_by_name IS NULL OR length(outcome_by_name) <= 200),
  outcome_at              INTEGER,
  created_at              INTEGER NOT NULL,
  reminded_at             INTEGER,
  suitability_approved_at INTEGER,
  suitability_approved_by TEXT CHECK (suitability_approved_by IS NULL OR suitability_approved_by IN ('player','guardian')),
  CHECK ((status IN ('accepted','declined')) = (outcome_at IS NOT NULL)),
  CHECK ((outcome_at IS NULL) = (outcome_by_user_id IS NULL)),
  CHECK (outcome_at IS NOT NULL OR (outcome_note IS NULL AND outcome_by_name IS NULL)),
  CHECK ((suitability_approved_at IS NULL) = (suitability_approved_by IS NULL))
) STRICT;
CREATE TABLE application_suitability (
  application_id TEXT NOT NULL REFERENCES applications(id) ON DELETE CASCADE,
  ordinal        INTEGER NOT NULL CHECK (ordinal >= 0),
  dimension      TEXT NOT NULL CHECK (dimension IN ('schedule','travel','relocation','compensation','environment','accessibility')),
  verdict        TEXT NOT NULL CHECK (verdict IN ('compatible','conflict','unknown')),
  PRIMARY KEY (application_id, ordinal),
  UNIQUE (application_id, dimension)
) STRICT;
CREATE TABLE application_history (
  id          TEXT PRIMARY KEY,
  application_id    TEXT NOT NULL REFERENCES applications(id) ON DELETE RESTRICT,
  position    INTEGER NOT NULL,
  at          INTEGER NOT NULL,
  by_kind     TEXT CHECK (by_kind IS NULL OR by_kind IN ('player','guardian','org','admin')),
  by_id       TEXT,
  by_name     TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action      TEXT NOT NULL,
  detail      TEXT CHECK (detail IS NULL OR length(detail) <= 500),
  UNIQUE (application_id, position)
) STRICT;
CREATE TABLE campaigns (
  id                  TEXT PRIMARY KEY,
  org_id              TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  org_name            TEXT NOT NULL CHECK (length(org_name) <= 200),
  title               TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 120),
  deadline            TEXT NOT NULL CHECK (length(deadline) = 10),
  attempts_allowed    INTEGER NOT NULL CHECK (attempts_allowed BETWEEN 1 AND 5),
  elig_min_age        INTEGER CHECK (elig_min_age IS NULL OR elig_min_age BETWEEN 4 AND 99),
  elig_max_age        INTEGER CHECK (elig_max_age IS NULL OR elig_max_age BETWEEN 4 AND 99),
  elig_position_group TEXT NOT NULL CHECK (elig_position_group IN ('any','GK','DEF','MID','ATT')),
  elig_max_level      TEXT CHECK (elig_max_level IS NULL OR elig_max_level IN ('amateur','semi_pro','pro')),
  elig_radius_km      REAL CHECK (elig_radius_km IS NULL OR elig_radius_km BETWEEN 0 AND 1000),
  status              TEXT NOT NULL CHECK (status IN ('published')),
  created_by_name     TEXT NOT NULL CHECK (length(created_by_name) <= 200),
  created_at          INTEGER NOT NULL,
  CHECK (elig_min_age IS NULL OR elig_max_age IS NULL OR elig_min_age <= elig_max_age)
) STRICT;
CREATE TABLE campaign_drills (
  campaign_id  TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  ordinal      INTEGER NOT NULL CHECK (ordinal BETWEEN 0 AND 5),
  name         TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
  instructions TEXT NOT NULL CHECK (length(instructions) <= 400),
  equipment    TEXT NOT NULL CHECK (length(equipment) <= 120),
  distance     TEXT NOT NULL CHECK (length(distance) <= 120),
  surface      TEXT NOT NULL CHECK (length(surface) <= 120),
  camera       TEXT NOT NULL CHECK (length(camera) <= 120),
  PRIMARY KEY (campaign_id, ordinal),
  UNIQUE (campaign_id, name)
) STRICT;
CREATE TABLE campaign_rubric (
  campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  ordinal     INTEGER NOT NULL CHECK (ordinal BETWEEN 0 AND 7),
  criterion   TEXT NOT NULL CHECK (length(criterion) BETWEEN 1 AND 100),
  guidance    TEXT NOT NULL CHECK (length(guidance) <= 200),
  PRIMARY KEY (campaign_id, ordinal)
) STRICT;
CREATE TABLE campaign_submissions (
  id                TEXT PRIMARY KEY,
  campaign_id       TEXT NOT NULL REFERENCES campaigns(id) ON DELETE RESTRICT,
  org_id            TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  player_id         TEXT NOT NULL,
  player_name       TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  submitted_by_kind TEXT NOT NULL CHECK (submitted_by_kind IN ('player','guardian')),
  submitted_by_id   TEXT NOT NULL CHECK (length(submitted_by_id) BETWEEN 1 AND 80),
  submitted_by_name TEXT CHECK (submitted_by_name IS NULL OR length(submitted_by_name) <= 200),
  created_at        INTEGER NOT NULL,
  UNIQUE (campaign_id, player_id)
) STRICT;
CREATE TABLE campaign_attempts (
  id                 TEXT PRIMARY KEY,
  submission_id      TEXT NOT NULL REFERENCES campaign_submissions(id) ON DELETE CASCADE,
  ordinal            INTEGER NOT NULL CHECK (ordinal >= 0),
  media_id           TEXT CHECK (media_id IS NULL OR length(media_id) <= 80),
  drill_name         TEXT NOT NULL CHECK (length(drill_name) BETWEEN 1 AND 80),
  note               TEXT CHECK (note IS NULL OR length(note) <= 300),
  file_checks_passed INTEGER NOT NULL CHECK (file_checks_passed IN (0,1)),
  file_checked_at    INTEGER NOT NULL,
  status             TEXT NOT NULL CHECK (status IN ('submitted','failed_checks','accepted','returned')),
  review_by_user_id  TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  review_by_name     TEXT CHECK (review_by_name IS NULL OR length(review_by_name) <= 200),
  reviewed_at        INTEGER,
  review_reasons     TEXT CHECK (review_reasons IS NULL OR length(review_reasons) <= 400),
  review_rubric_notes TEXT CHECK (review_rubric_notes IS NULL OR length(review_rubric_notes) <= 400),
  submitted_at       INTEGER NOT NULL,
  UNIQUE (submission_id, ordinal),
  CHECK ((status = 'failed_checks') = (file_checks_passed = 0)),
  CHECK ((status IN ('accepted','returned')) = (reviewed_at IS NOT NULL)),
  CHECK ((reviewed_at IS NULL) = (review_by_user_id IS NULL)),
  CHECK (reviewed_at IS NOT NULL OR (review_by_name IS NULL AND review_reasons IS NULL AND review_rubric_notes IS NULL)),
  CHECK (status <> 'returned' OR review_reasons IS NOT NULL)
) STRICT;
CREATE TABLE campaign_attempt_issues (
  attempt_id TEXT NOT NULL REFERENCES campaign_attempts(id) ON DELETE CASCADE,
  ordinal    INTEGER NOT NULL CHECK (ordinal >= 0),
  issue      TEXT NOT NULL CHECK (issue IN ('media_missing','not_video','not_uploaded')),
  PRIMARY KEY (attempt_id, ordinal),
  UNIQUE (attempt_id, issue)
) STRICT;
CREATE TABLE player_prefs (
  player_id       TEXT PRIMARY KEY,
  travel_limit_km REAL CHECK (travel_limit_km IS NULL OR travel_limit_km BETWEEN 0 AND 500),
  transport       TEXT CHECK (transport IS NULL OR transport IN ('own','public','lift_needed')),
  relocation      TEXT CHECK (relocation IS NULL OR relocation IN ('yes','no','discuss')),
  ambitions       TEXT CHECK (ambitions IS NULL OR length(ambitions) <= 300),
  max_fee_minor   INTEGER CHECK (max_fee_minor IS NULL OR max_fee_minor >= 0),
  currency        TEXT NOT NULL CHECK (length(currency) = 3 AND currency GLOB '[A-Z][A-Z][A-Z]'),
  expenses_needed INTEGER NOT NULL CHECK (expenses_needed IN (0,1)),
  updated_at      INTEGER NOT NULL
) STRICT;
CREATE TABLE player_pref_slots (
  player_id  TEXT NOT NULL REFERENCES player_prefs(player_id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('commitment','available')),
  ordinal    INTEGER NOT NULL CHECK (ordinal >= 0),
  day        TEXT NOT NULL CHECK (day IN ('mon','tue','wed','thu','fri','sat','sun')),
  start_time TEXT NOT NULL CHECK (length(start_time) = 5 AND start_time GLOB '[0-2][0-9]:[0-5][0-9]' AND start_time <= '23:59'),
  end_time   TEXT NOT NULL CHECK (length(end_time) = 5 AND end_time GLOB '[0-2][0-9]:[0-5][0-9]' AND end_time <= '23:59'),
  tz         TEXT NOT NULL CHECK (length(tz) BETWEEN 1 AND 40),
  label      TEXT CHECK (label IS NULL OR length(label) <= 60),
  PRIMARY KEY (player_id, kind, ordinal),
  CHECK (start_time < end_time)
) STRICT;
CREATE TABLE player_pref_texts (
  player_id TEXT NOT NULL REFERENCES player_prefs(player_id) ON DELETE CASCADE,
  kind      TEXT NOT NULL CHECK (kind IN ('environment','accessibility')),
  ordinal   INTEGER NOT NULL CHECK (ordinal >= 0),
  text      TEXT NOT NULL CHECK (length(text) BETWEEN 1 AND 80),
  PRIMARY KEY (player_id, kind, ordinal)
) STRICT;
CREATE TABLE ver_root_requests (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  status                                   TEXT NOT NULL CHECK (status IN ('collecting_evidence','requires_human_review','approved','rejected')),
  org_name                                 TEXT NOT NULL CHECK (length(org_name) <= 120 AND length(org_name) > 0),
  org_type                                 TEXT NOT NULL CHECK (org_type IN ('professional club','academy','grassroots club','federation/association','agency','other approved football organisation')),
  country                                  TEXT NOT NULL CHECK (length(country) <= 40),
  federation                               TEXT CHECK (federation IS NULL OR length(federation) <= 80),
  website                                  TEXT NOT NULL CHECK (length(website) <= 200),
  domain                                   TEXT NOT NULL CHECK (length(domain) <= 253),
  applicant_name                           TEXT NOT NULL CHECK (length(applicant_name) <= 80 AND length(applicant_name) > 0),
  applicant_role                           TEXT NOT NULL CHECK (length(applicant_role) <= 60),
  work_email                               TEXT NOT NULL CHECK (length(work_email) <= 254 AND length(work_email) > 0),
  official_contact                         TEXT CHECK (official_contact IS NULL OR length(official_contact) <= 200),
  declared_authorised                      INTEGER CHECK (declared_authorised IS NULL OR declared_authorised IN (0,1)),
  check_email_syntax                       TEXT NOT NULL CHECK (check_email_syntax IN ('passed')),
  check_email_domain_alignment             TEXT NOT NULL CHECK (check_email_domain_alignment IN ('passed','mismatch')),
  check_free_email_provider                TEXT NOT NULL CHECK (check_free_email_provider IN ('passed','flagged')),
  check_disposable_email                   TEXT NOT NULL CHECK (check_disposable_email IN ('passed','flagged')),
  check_domain_normalized                  TEXT NOT NULL CHECK (length(check_domain_normalized) <= 263),
  check_dns_ownership                      TEXT NOT NULL CHECK (check_dns_ownership IN ('not_configured')),
  check_duplicate_organisation             TEXT NOT NULL CHECK (check_duplicate_organisation IN ('passed','flagged')),
  check_duplicate_request                  TEXT NOT NULL CHECK (check_duplicate_request IN ('passed','flagged')),
  check_domain_already_verified_elsewhere  TEXT NOT NULL CHECK (check_domain_already_verified_elsewhere IN ('passed','flagged')),
  check_evidence_completeness              TEXT NOT NULL CHECK (check_evidence_completeness IN ('pending_email_proof','email_proved')),
  email_proved                             INTEGER NOT NULL CHECK (email_proved IN (0,1)),
  existing_org_id                          TEXT CHECK (existing_org_id IS NULL OR length(existing_org_id) <= 80),
  applicant_secret_hash                    TEXT NOT NULL CHECK (length(applicant_secret_hash) <= 64 AND length(applicant_secret_hash) > 0),
  created_at                               INTEGER NOT NULL,
  decided_at                               INTEGER,
  decided_by_name                          TEXT CHECK (decided_by_name IS NULL OR length(decided_by_name) <= 200),
  decided_by_id                            TEXT CHECK (decided_by_id IS NULL OR length(decided_by_id) <= 80),
  decision_attribution                     TEXT CHECK (decision_attribution IS NULL OR decision_attribution IN ('authenticated_reviewer','declared_reviewer','shared_admin_key')),
  decision_reason                          TEXT CHECK (decision_reason IS NULL OR length(decision_reason) <= 400),
  result_org_id                            TEXT CHECK (result_org_id IS NULL OR length(result_org_id) <= 80),
  result_user_id                           TEXT CHECK (result_user_id IS NULL OR length(result_user_id) <= 80),
  identity_link                            TEXT CHECK (identity_link IS NULL OR identity_link IN ('trust_safety_selection','provisioned_new_user','verified_work_email')),
  FOREIGN KEY (existing_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (result_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (result_user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_root_request_codes (
  root_request_id  TEXT NOT NULL REFERENCES ver_root_requests(id) ON DELETE CASCADE,
  list      TEXT NOT NULL CHECK (list IN ('review_reason','risk_flag')),
  position  INTEGER NOT NULL,
  code      TEXT NOT NULL CHECK ((list = 'review_reason' AND code IN ('ROOT_ORGANISATION_BOOTSTRAP','NO_AUTHORITATIVE_SOURCE','CONFLICTING_EVIDENCE','IDENTITY_MISMATCH','DOMAIN_OWNERSHIP_AMBIGUOUS','DUPLICATE_ORGANISATION','HIGH_RISK_ADMIN_CHANGE','DOCUMENT_AUTHENTICITY_UNCONFIRMED','REGISTRY_AMBIGUOUS_MATCH','DISPUTED_CLAIM','SUSPECTED_FRAUD_SIGNALS','MANUAL_EXCEPTION_REQUESTED','REGISTRY_RECORD_UNREADABLE')) OR (list = 'risk_flag' AND code IN ('DISPOSABLE_EMAIL','FREE_EMAIL_PROVIDER','ORG_DOMAIN_MISMATCH','REPEATED_EMAIL_CHALLENGE_FAILURES','COMPETING_ORGANISATION_CLAIMS','CREDENTIAL_REUSED_ACROSS_USERS','DUPLICATE_EVIDENCE_HASH','RECENT_REVOCATION_REAPPLY','ORGANISATION_SUSPENDED','CONFLICTING_ACTIVE_ROLES','UNUSUAL_MASS_ACTIVITY','SELF_VERIFICATION_ATTEMPT'))),
  PRIMARY KEY (root_request_id, list, position),
  UNIQUE (root_request_id, list, code)
) STRICT;
CREATE TABLE ver_claims (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  subject_kind                             TEXT NOT NULL CHECK (subject_kind IN ('user','org')),
  subject_id                               TEXT NOT NULL CHECK (length(subject_id) <= 80 AND length(subject_id) > 0),
  claim_type                               TEXT NOT NULL CHECK (claim_type IN ('PERSON_IDENTITY','ORGANISATION_IDENTITY','ORGANISATION_DOMAIN','ORGANISATION_ADMIN','CLUB_AFFILIATION','CLUB_ROLE','LICENCE','AGENCY_AFFILIATION','AGENCY_ROLE','GRASSROOTS_AFFILIATION','FEDERATION_AFFILIATION')),
  organisation_id                          TEXT CHECK (organisation_id IS NULL OR length(organisation_id) <= 80),
  role                                     TEXT CHECK (role IS NULL OR length(role) <= 60),
  status                                   TEXT NOT NULL CHECK (status IN ('unverified','collecting_evidence','pending','automated_checks_passed','requires_human_review','verified','rejected','expired','suspended','revoked','disputed','superseded')),
  valid_from                               INTEGER,
  valid_until                              INTEGER,
  current                                  INTEGER NOT NULL CHECK (current IN (0,1)),
  verification_method                      TEXT CHECK (verification_method IS NULL OR verification_method IN ('official_domain_email','organisation_admin_confirmation','authoritative_registry','federation_confirmation','existing_verified_org_admin','scoutbox_manual_review','document_submitted','reference_confirmation','migration')),
  authority_kind                           TEXT CHECK (authority_kind IS NULL OR authority_kind IN ('org_admin','trust_safety')),
  authority_id                             TEXT CHECK (authority_id IS NULL OR length(authority_id) <= 80),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  verified_at                              INTEGER,
  verified_by_kind                         TEXT CHECK (verified_by_kind IS NULL OR verified_by_kind IN ('system','org_user','org_admin','trust_safety')),
  verified_by_id                           TEXT CHECK (verified_by_id IS NULL OR length(verified_by_id) <= 80),
  revoked_at                               INTEGER,
  revoked_by_kind                          TEXT CHECK (revoked_by_kind IS NULL OR revoked_by_kind IN ('system','org_user','org_admin','trust_safety')),
  revoked_by_id                            TEXT CHECK (revoked_by_id IS NULL OR length(revoked_by_id) <= 80),
  revocation_reason                        TEXT CHECK (revocation_reason IS NULL OR length(revocation_reason) <= 600),
  suspended_at                             INTEGER,
  suspend_reason                           TEXT CHECK (suspend_reason IS NULL OR length(suspend_reason) <= 600),
  disputed_at                              INTEGER,
  expired_at                               INTEGER,
  declared_name                            TEXT CHECK (declared_name IS NULL OR length(declared_name) <= 200),
  pair_id                                  TEXT CHECK (pair_id IS NULL OR length(pair_id) <= 80),
  requested_start                          INTEGER,
  work_email                               TEXT CHECK (work_email IS NULL OR length(work_email) <= 254),
  domain_control                           TEXT CHECK (domain_control IS NULL OR domain_control IN ('passed')),
  domain_covered_by_org                    INTEGER CHECK (domain_covered_by_org IS NULL OR domain_covered_by_org IN (0,1)),
  domain                                   TEXT CHECK (domain IS NULL OR length(domain) <= 253),
  licence_type                             TEXT CHECK (licence_type IS NULL OR length(licence_type) <= 80),
  issuer                                   TEXT CHECK (issuer IS NULL OR length(issuer) <= 80),
  identifier                               TEXT CHECK (identifier IS NULL OR length(identifier) <= 60),
  holder_name                              TEXT CHECK (holder_name IS NULL OR length(holder_name) <= 80),
  display                                  TEXT CHECK (display IS NULL OR length(display) <= 300),
  registry_provider                        TEXT CHECK (registry_provider IS NULL OR length(registry_provider) <= 60),
  registry_state                           TEXT CHECK (registry_state IS NULL OR registry_state IN ('not_configured','temporarily_unavailable','unsupported')),
  registry_result                          TEXT CHECK (registry_result IS NULL OR registry_result IN ('match','no_match','unreadable_record')),
  registry_checked_at                      INTEGER,
  registry_reference                       TEXT CHECK (registry_reference IS NULL OR length(registry_reference) <= 60),
  root_request_id                          TEXT CHECK (root_request_id IS NULL OR length(root_request_id) <= 80),
  org_type                                 TEXT CHECK (org_type IS NULL OR org_type IN ('professional club','academy','grassroots club','federation/association','agency','other approved football organisation')),
  website                                  TEXT CHECK (website IS NULL OR length(website) <= 200),
  admin_level                              TEXT CHECK (admin_level IS NULL OR admin_level IN ('verification_viewer','verification_reviewer','verification_admin','verification_root_admin')),
  identity_link                            TEXT CHECK (identity_link IS NULL OR identity_link IN ('trust_safety_selection','provisioned_new_user','verified_work_email')),
  appointed_reason                         TEXT CHECK (appointed_reason IS NULL OR length(appointed_reason) <= 300),
  via                                      TEXT CHECK (via IS NULL OR length(via) <= 60),
  flagged_at                               INTEGER,
  flagged_reason                           TEXT CHECK (flagged_reason IS NULL OR length(flagged_reason) <= 300),
  migrated_from                            TEXT CHECK (migrated_from IS NULL OR length(migrated_from) <= 200),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 400),
  representation_id                        TEXT CHECK (representation_id IS NULL OR length(representation_id) <= 80),
  document_reviewed                        TEXT CHECK (document_reviewed IS NULL OR length(document_reviewed) <= 200),
  assigned_to                              TEXT CHECK (assigned_to IS NULL OR length(assigned_to) <= 60),
  expiry_warned_at                         INTEGER,
  FOREIGN KEY (organisation_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (root_request_id) REFERENCES ver_root_requests(id) ON DELETE RESTRICT,
  CHECK (verified_by_kind IS NOT NULL OR verified_by_id IS NULL),
  CHECK (revoked_by_kind IS NOT NULL OR revoked_by_id IS NULL),
  CHECK ((flagged_at IS NULL) = (flagged_reason IS NULL)),
  CHECK (registry_provider IS NOT NULL OR (registry_state IS NULL AND registry_result IS NULL AND registry_checked_at IS NULL AND registry_reference IS NULL)),
  CHECK (registry_provider IS NULL OR registry_checked_at IS NOT NULL)
) STRICT;
CREATE TABLE ver_claim_codes (
  claim_id  TEXT NOT NULL REFERENCES ver_claims(id) ON DELETE CASCADE,
  list      TEXT NOT NULL CHECK (list IN ('review_reason','risk_flag')),
  position  INTEGER NOT NULL,
  code      TEXT NOT NULL CHECK ((list = 'review_reason' AND code IN ('ROOT_ORGANISATION_BOOTSTRAP','NO_AUTHORITATIVE_SOURCE','CONFLICTING_EVIDENCE','IDENTITY_MISMATCH','DOMAIN_OWNERSHIP_AMBIGUOUS','DUPLICATE_ORGANISATION','HIGH_RISK_ADMIN_CHANGE','DOCUMENT_AUTHENTICITY_UNCONFIRMED','REGISTRY_AMBIGUOUS_MATCH','DISPUTED_CLAIM','SUSPECTED_FRAUD_SIGNALS','MANUAL_EXCEPTION_REQUESTED','REGISTRY_RECORD_UNREADABLE')) OR (list = 'risk_flag' AND code IN ('DISPOSABLE_EMAIL','FREE_EMAIL_PROVIDER','ORG_DOMAIN_MISMATCH','REPEATED_EMAIL_CHALLENGE_FAILURES','COMPETING_ORGANISATION_CLAIMS','CREDENTIAL_REUSED_ACROSS_USERS','DUPLICATE_EVIDENCE_HASH','RECENT_REVOCATION_REAPPLY','ORGANISATION_SUSPENDED','CONFLICTING_ACTIVE_ROLES','UNUSUAL_MASS_ACTIVITY','SELF_VERIFICATION_ATTEMPT'))),
  PRIMARY KEY (claim_id, list, position),
  UNIQUE (claim_id, list, code)
) STRICT;
CREATE TABLE ver_evidence (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  type                                     TEXT NOT NULL CHECK (type IN ('official_email','document','registry_result','organisation_confirmation','federation_confirmation','reference','existing_claim')),
  source                                   TEXT NOT NULL CHECK (length(source) <= 60 AND length(source) > 0),
  supplied_by_kind                         TEXT NOT NULL CHECK (supplied_by_kind IN ('org_user','applicant','system')),
  supplied_by_id                           TEXT CHECK (supplied_by_id IS NULL OR length(supplied_by_id) <= 80),
  org_id                                   TEXT CHECK (org_id IS NULL OR length(org_id) <= 80),
  received_at                              INTEGER NOT NULL,
  media_id                                 TEXT CHECK (media_id IS NULL OR length(media_id) <= 80),
  sha256                                   TEXT CHECK (sha256 IS NULL OR length(sha256) <= 64),
  mime                                     TEXT CHECK (mime IS NULL OR mime IN ('application/pdf','image/png','image/jpeg','image/webp')),
  bytes                                    INTEGER,
  filename                                 TEXT CHECK (filename IS NULL OR length(filename) <= 120),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 400),
  domain                                   TEXT CHECK (domain IS NULL OR length(domain) <= 253),
  domain_covered_by_org                    INTEGER CHECK (domain_covered_by_org IS NULL OR domain_covered_by_org IN (0,1)),
  address_hash                             TEXT CHECK (address_hash IS NULL OR length(address_hash) <= 64),
  root_request_id                          TEXT CHECK (root_request_id IS NULL OR length(root_request_id) <= 80),
  identifier                               TEXT CHECK (identifier IS NULL OR length(identifier) <= 60),
  licence_type                             TEXT CHECK (licence_type IS NULL OR length(licence_type) <= 80),
  registry_valid_until                     TEXT CHECK (registry_valid_until IS NULL OR length(registry_valid_until) <= 40),
  signing_package_id                       TEXT CHECK (signing_package_id IS NULL OR length(signing_package_id) <= 80),
  signing_document_kind                    TEXT CHECK (signing_document_kind IS NULL OR signing_document_kind IN ('signing','executed')),
  label                                    TEXT CHECK (label IS NULL OR length(label) <= 120),
  check_malware_scan                       TEXT NOT NULL CHECK (check_malware_scan IN ('not_configured')),
  check_content_signature                  TEXT CHECK (check_content_signature IS NULL OR check_content_signature IN ('matched_claimed_type')),
  retention                                TEXT NOT NULL CHECK (retention IN ('until_claim_resolution','until_signing_resolution')),
  visibility                               TEXT NOT NULL CHECK (visibility IN ('trust_and_safety','organisation_internal','subject_only')),
  expires_at                               INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (root_request_id) REFERENCES ver_root_requests(id) ON DELETE RESTRICT,
  CHECK (sha256 IS NULL OR length(sha256) = 64),
  CHECK (bytes IS NULL OR (bytes > 0 AND bytes <= 8388608))
) STRICT;
CREATE TABLE ver_claim_evidence (
  claim_id     TEXT NOT NULL REFERENCES ver_claims(id) ON DELETE CASCADE,
  position     INTEGER NOT NULL,
  evidence_id  TEXT NOT NULL REFERENCES ver_evidence(id) ON DELETE RESTRICT,
  PRIMARY KEY (claim_id, position),
  UNIQUE (claim_id, evidence_id)
) STRICT;
CREATE TABLE ver_events (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  occurred_at                              INTEGER NOT NULL,
  type                                     TEXT NOT NULL CHECK (type IN ('claim.created','claim.collecting_evidence','claim.pending','claim.automated_checks_passed','claim.requires_human_review','claim.verified','claim.rejected','claim.expired','claim.suspended','claim.revoked','claim.disputed','claim.superseded','claim.unverified','claim.reinstated','claim.corrected','review.requested','review.assigned','review.approved','review.rejected','automated_check.passed','automated_check.failed','evidence.added','evidence.accessed','email.challenge_sent','email.challenge_passed','security.self_verification_blocked','organisation.domain_added','organisation.domain_verified','organisation.domain_removed','admin.invited','admin.accepted','admin.revoked')),
  actor_kind                               TEXT NOT NULL CHECK (actor_kind IN ('org_user','system','trust_safety')),
  actor_id                                 TEXT CHECK (actor_id IS NULL OR length(actor_id) <= 80),
  actor_name                               TEXT CHECK (actor_name IS NULL OR length(actor_name) <= 200),
  actor_org_id                             TEXT CHECK (actor_org_id IS NULL OR length(actor_org_id) <= 80),
  request_id                               TEXT CHECK (request_id IS NULL OR length(request_id) <= 120),
  attribution                              TEXT CHECK (attribution IS NULL OR attribution IN ('authenticated_reviewer','declared_reviewer','shared_admin_key')),
  claim_id                                 TEXT CHECK (claim_id IS NULL OR length(claim_id) <= 80),
  subject_id                               TEXT CHECK (subject_id IS NULL OR length(subject_id) <= 80),
  org_id                                   TEXT CHECK (org_id IS NULL OR length(org_id) <= 80),
  detail                                   TEXT CHECK (detail IS NULL OR length(detail) <= 1000),
  reason                                   TEXT CHECK (reason IS NULL OR length(reason) <= 600),
  FOREIGN KEY (actor_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (claim_id) REFERENCES ver_claims(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_tokens (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  token_hash                               TEXT NOT NULL CHECK (length(token_hash) <= 64 AND length(token_hash) > 0),
  purpose                                  TEXT NOT NULL CHECK (purpose IN ('work_email','domain_email','player_invite','root_email')),
  email                                    TEXT CHECK (email IS NULL OR length(email) <= 254),
  subject_kind                             TEXT CHECK (subject_kind IS NULL OR subject_kind IN ('org_user','player')),
  subject_id                               TEXT CHECK (subject_id IS NULL OR length(subject_id) <= 80),
  org_id                                   TEXT CHECK (org_id IS NULL OR length(org_id) <= 80),
  ref_id                                   TEXT CHECK (ref_id IS NULL OR length(ref_id) <= 80),
  created_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  used_at                                  INTEGER,
  attempts_failed                          INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (length(token_hash) = 64),
  CHECK (attempts_failed >= 0)
) STRICT;
CREATE TABLE ver_admins (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) <= 80 AND length(user_id) > 0),
  level                                    TEXT NOT NULL CHECK (level IN ('verification_viewer','verification_reviewer','verification_admin','verification_root_admin')),
  status                                   TEXT NOT NULL CHECK (status IN ('active','revoked')),
  invited_by                               TEXT NOT NULL CHECK (length(invited_by) <= 80 AND length(invited_by) > 0),
  created_at                               INTEGER NOT NULL,
  accepted_at                              INTEGER,
  revoked_at                               INTEGER,
  revoked_by                               TEXT CHECK (revoked_by IS NULL OR length(revoked_by) <= 80),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (revoked_by) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_root_transfers (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  to_user_id                               TEXT NOT NULL CHECK (length(to_user_id) <= 80 AND length(to_user_id) > 0),
  proposed_by                              TEXT NOT NULL CHECK (length(proposed_by) <= 80 AND length(proposed_by) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('pending','approved')),
  created_at                               INTEGER NOT NULL,
  approved_by                              TEXT CHECK (approved_by IS NULL OR length(approved_by) <= 80),
  approved_at                              INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (to_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (proposed_by) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (approved_by) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_disputes (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  claim_id                                 TEXT NOT NULL CHECK (length(claim_id) <= 80 AND length(claim_id) > 0),
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('org_user')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  reason                                   TEXT NOT NULL CHECK (length(reason) <= 600 AND length(reason) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('open','resolved')),
  resolution                               TEXT CHECK (resolution IS NULL OR length(resolution) <= 320),
  created_at                               INTEGER NOT NULL,
  resolved_at                              INTEGER,
  resolved_by_name                         TEXT CHECK (resolved_by_name IS NULL OR length(resolved_by_name) <= 200),
  resolved_by_id                           TEXT CHECK (resolved_by_id IS NULL OR length(resolved_by_id) <= 80),
  resolution_attribution                   TEXT CHECK (resolution_attribution IS NULL OR resolution_attribution IN ('authenticated_reviewer','declared_reviewer','shared_admin_key')),
  FOREIGN KEY (claim_id) REFERENCES ver_claims(id) ON DELETE RESTRICT,
  FOREIGN KEY (by_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_references (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  version                                  INTEGER NOT NULL,
  supersedes_id                            TEXT CHECK (supersedes_id IS NULL OR length(supersedes_id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  player_name                              TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  coach_user_id                            TEXT NOT NULL CHECK (length(coach_user_id) <= 80 AND length(coach_user_id) > 0),
  coach_name                               TEXT CHECK (coach_name IS NULL OR length(coach_name) <= 200),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  org_name                                 TEXT CHECK (org_name IS NULL OR length(org_name) <= 200),
  role_at_time                             TEXT CHECK (role_at_time IS NULL OR length(role_at_time) <= 200),
  provenance_claim_id                      TEXT NOT NULL CHECK (length(provenance_claim_id) <= 80 AND length(provenance_claim_id) > 0),
  provenance_claim_type                    TEXT NOT NULL CHECK (provenance_claim_type IN ('PERSON_IDENTITY','ORGANISATION_IDENTITY','ORGANISATION_DOMAIN','ORGANISATION_ADMIN','CLUB_AFFILIATION','CLUB_ROLE','LICENCE','AGENCY_AFFILIATION','AGENCY_ROLE','GRASSROOTS_AFFILIATION','FEDERATION_AFFILIATION')),
  provenance_status                        TEXT NOT NULL CHECK (provenance_status IN ('verified')),
  provenance_method                        TEXT CHECK (provenance_method IS NULL OR provenance_method IN ('official_domain_email','organisation_admin_confirmation','authoritative_registry','federation_confirmation','existing_verified_org_admin','scoutbox_manual_review','document_submitted','reference_confirmation','migration')),
  provenance_verified_at                   INTEGER,
  provenance_snapshot_at                   INTEGER NOT NULL,
  relationship                             TEXT NOT NULL CHECK (length(relationship) <= 80 AND length(relationship) > 0),
  capacity                                 TEXT NOT NULL CHECK (length(capacity) <= 120),
  from_year                                INTEGER,
  to_year                                  INTEGER,
  strengths                                TEXT NOT NULL CHECK (length(strengths) <= 500),
  development                              TEXT NOT NULL CHECK (length(development) <= 500),
  summary                                  TEXT NOT NULL CHECK (length(summary) <= 800 AND length(summary) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('active','withdrawn','superseded')),
  withdrawn_at                             INTEGER,
  withdraw_reason                          TEXT CHECK (withdraw_reason IS NULL OR length(withdraw_reason) <= 300),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (supersedes_id, player_id, coach_user_id, org_id) REFERENCES ver_references(id, player_id, coach_user_id, org_id) ON DELETE RESTRICT,
  FOREIGN KEY (coach_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (provenance_claim_id, coach_user_id, org_id) REFERENCES ver_claims(id, subject_id, organisation_id) ON DELETE RESTRICT,
  CHECK (version >= 1),
  CHECK ((supersedes_id IS NULL) = (version = 1))
) STRICT;
CREATE TABLE ver_player_invites (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  by_user_id                               TEXT NOT NULL CHECK (length(by_user_id) <= 80 AND length(by_user_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  invitee_name                             TEXT NOT NULL CHECK (length(invitee_name) <= 80 AND length(invitee_name) > 0),
  squad                                    TEXT NOT NULL CHECK (length(squad) <= 60),
  status                                   TEXT NOT NULL CHECK (status IN ('pending','accepted')),
  player_id                                TEXT CHECK (player_id IS NULL OR length(player_id) <= 80),
  target_player_id                         TEXT CHECK (target_player_id IS NULL OR length(target_player_id) <= 80),
  guardian_approved_id                     TEXT CHECK (guardian_approved_id IS NULL OR length(guardian_approved_id) <= 80 AND length(guardian_approved_id) > 0),
  guardian_approved_at                     INTEGER,
  created_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  accepted_at                              INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK ((status = 'accepted') = (player_id IS NOT NULL AND accepted_at IS NOT NULL)),
  CHECK ((guardian_approved_id IS NULL) = (guardian_approved_at IS NULL))
) STRICT;
CREATE TABLE ver_conflicts (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) <= 80 AND length(user_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  kind                                     TEXT NOT NULL CHECK (kind IN ('family_relationship','agent_relationship','financial_interest','coaching_relationship','other')),
  subject                                  TEXT NOT NULL CHECK (length(subject) <= 120),
  note                                     TEXT NOT NULL CHECK (length(note) <= 400),
  created_at                               INTEGER NOT NULL,
  withdrawn_at                             INTEGER,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_domain_requests (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  domain                                   TEXT NOT NULL CHECK (length(domain) <= 253 AND length(domain) > 0),
  requested_by                             TEXT NOT NULL CHECK (length(requested_by) <= 80 AND length(requested_by) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('email_challenge','requires_human_review','verified','rejected')),
  method                                   TEXT CHECK (method IS NULL OR method IN ('official_domain_email','scoutbox_manual_review')),
  created_at                               INTEGER NOT NULL,
  decided_at                               INTEGER,
  decided_by_name                          TEXT CHECK (decided_by_name IS NULL OR length(decided_by_name) <= 200),
  decided_by_id                            TEXT CHECK (decided_by_id IS NULL OR length(decided_by_id) <= 80),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (requested_by) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE ver_domain_request_codes (
  domain_request_id  TEXT NOT NULL REFERENCES ver_domain_requests(id) ON DELETE CASCADE,
  list      TEXT NOT NULL CHECK (list IN ('review_reason')),
  position  INTEGER NOT NULL,
  code      TEXT NOT NULL CHECK ((list = 'review_reason' AND code IN ('ROOT_ORGANISATION_BOOTSTRAP','NO_AUTHORITATIVE_SOURCE','CONFLICTING_EVIDENCE','IDENTITY_MISMATCH','DOMAIN_OWNERSHIP_AMBIGUOUS','DUPLICATE_ORGANISATION','HIGH_RISK_ADMIN_CHANGE','DOCUMENT_AUTHENTICITY_UNCONFIRMED','REGISTRY_AMBIGUOUS_MATCH','DISPUTED_CLAIM','SUSPECTED_FRAUD_SIGNALS','MANUAL_EXCEPTION_REQUESTED','REGISTRY_RECORD_UNREADABLE'))),
  PRIMARY KEY (domain_request_id, list, position),
  UNIQUE (domain_request_id, list, code)
) STRICT;
CREATE TABLE org_verified_domains (
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  domain                                   TEXT NOT NULL CHECK (length(domain) <= 253 AND length(domain) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('verified')),
  method                                   TEXT NOT NULL CHECK (method IN ('official_domain_email','scoutbox_manual_review')),
  verified_at                              INTEGER NOT NULL,
  added_by                                 TEXT NOT NULL CHECK (length(added_by) <= 80 AND length(added_by) > 0),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (org_id, domain)
) STRICT;
CREATE TABLE ver_migrations (
  key            TEXT PRIMARY KEY CHECK (key IN ('m14')),
  ran_at         INTEGER NOT NULL,
  claims_created INTEGER NOT NULL CHECK (claims_created >= 0)
) STRICT;
CREATE TABLE passport_prefs (
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  bio                                      TEXT CHECK (bio IS NULL OR length(bio) <= 400),
  position_primary                         TEXT CHECK (position_primary IS NULL OR position_primary IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  availability                             TEXT CHECK (availability IS NULL OR availability IN ('open_to_trials','open_to_contact','not_looking')),
  available_from                           TEXT CHECK (available_from IS NULL OR (available_from GLOB '[0-9][0-9][0-9][0-9]' OR available_from GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]' OR available_from GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
  updated_at                               INTEGER NOT NULL,
  PRIMARY KEY (player_id)
) STRICT;
CREATE TABLE passport_pref_positions (
  player_id  TEXT NOT NULL REFERENCES passport_prefs(player_id) ON DELETE CASCADE,
  ord       INTEGER NOT NULL CHECK (ord >= 0),
  code    TEXT NOT NULL CHECK (code IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF') AND ord < 3),
  PRIMARY KEY (player_id, ord),
  UNIQUE (player_id, code)
) STRICT;
CREATE TABLE passport_position_history (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  from_date                                TEXT NOT NULL CHECK ((from_date GLOB '[0-9][0-9][0-9][0-9]' OR from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]' OR from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
  position_primary                         TEXT NOT NULL CHECK (position_primary IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  submitted_by                             TEXT NOT NULL CHECK (submitted_by IN ('player','guardian')),
  recorded_at                              INTEGER NOT NULL,
  FOREIGN KEY (player_id) REFERENCES passport_prefs(player_id) ON DELETE CASCADE
) STRICT;
CREATE TABLE passport_position_history_positions (
  history_id  TEXT NOT NULL REFERENCES passport_position_history(id) ON DELETE CASCADE,
  ord       INTEGER NOT NULL CHECK (ord >= 0),
  code    TEXT NOT NULL CHECK (code IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF') AND ord < 3),
  PRIMARY KEY (history_id, ord),
  UNIQUE (history_id, code)
) STRICT;
CREATE TABLE passport_public_selections (
  player_id  TEXT NOT NULL REFERENCES passport_prefs(player_id) ON DELETE CASCADE,
  ord       INTEGER NOT NULL CHECK (ord >= 0),
  selection    TEXT NOT NULL CHECK (length(selection) > 0 AND length(selection) <= 120 AND ord < 100),
  PRIMARY KEY (player_id, ord),
  UNIQUE (player_id, selection)
) STRICT;
CREATE TABLE passport_career_entries (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  org_name                                 TEXT NOT NULL CHECK (length(org_name) <= 100 AND length(org_name) > 0),
  role                                     TEXT CHECK (role IS NULL OR length(role) <= 60),
  from_date                                TEXT NOT NULL CHECK ((from_date GLOB '[0-9][0-9][0-9][0-9]' OR from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]' OR from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
  to_date                                  TEXT CHECK (to_date IS NULL OR (to_date GLOB '[0-9][0-9][0-9][0-9]' OR to_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]' OR to_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 200),
  submitted_by                             TEXT NOT NULL CHECK (submitted_by IN ('player','guardian')),
  created_at                               INTEGER NOT NULL,
  withdrawn_at                             INTEGER
) STRICT;
CREATE TABLE passport_achievements (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  org_name                                 TEXT CHECK (org_name IS NULL OR length(org_name) <= 100),
  when_date                                TEXT CHECK (when_date IS NULL OR (when_date GLOB '[0-9][0-9][0-9][0-9]' OR when_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]' OR when_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
  submitted_by                             TEXT NOT NULL CHECK (submitted_by IN ('player','guardian')),
  confirmation_provenance                  TEXT CHECK (confirmation_provenance IS NULL OR confirmation_provenance IN ('verified_club_confirmed')),
  confirmation_org_id                      TEXT CHECK (confirmation_org_id IS NULL OR length(confirmation_org_id) <= 80 AND length(confirmation_org_id) > 0),
  confirmation_org_name                    TEXT CHECK (confirmation_org_name IS NULL OR length(confirmation_org_name) <= 200),
  confirmation_by_name                     TEXT CHECK (confirmation_by_name IS NULL OR length(confirmation_by_name) <= 200),
  confirmation_at                          INTEGER,
  created_at                               INTEGER NOT NULL,
  withdrawn_at                             INTEGER,
  FOREIGN KEY (confirmation_org_id) REFERENCES orgs(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE passport_shares (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  mode                                     TEXT NOT NULL CHECK (mode IN ('public','recruitment')),
  token_hash                               TEXT NOT NULL CHECK (length(token_hash) <= 64 AND length(token_hash) > 0),
  created_by_kind                          TEXT NOT NULL CHECK (created_by_kind IN ('player','guardian')),
  created_by_id                            TEXT NOT NULL CHECK (length(created_by_id) <= 80 AND length(created_by_id) > 0),
  created_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  revoked_at                               INTEGER,
  revoked_by_kind                          TEXT CHECK (revoked_by_kind IS NULL OR revoked_by_kind IN ('player','guardian','trust_safety')),
  revoked_by_id                            TEXT CHECK (revoked_by_id IS NULL OR length(revoked_by_id) <= 80 AND length(revoked_by_id) > 0),
  views                                    INTEGER NOT NULL DEFAULT 0,
  CHECK (length(token_hash) = 64),
  CHECK (views >= 0),
  CHECK ((revoked_at IS NULL) = (revoked_by_kind IS NULL))
) STRICT;
CREATE TABLE passport_corrections (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  target_kind                              TEXT NOT NULL CHECK (target_kind IN ('timeline_event','career_entry','club_history','reference','trial','assessment','achievement','signing')),
  target_id                                TEXT CHECK (target_id IS NULL OR length(target_id) <= 80),
  reason                                   TEXT NOT NULL CHECK (length(reason) <= 500 AND length(reason) > 0),
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('player','guardian')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  status                                   TEXT NOT NULL CHECK (status IN ('open','resolved')),
  resolution_outcome                       TEXT CHECK (resolution_outcome IS NULL OR resolution_outcome IN ('corrected','rejected','referred')),
  resolution_reason                        TEXT CHECK (resolution_reason IS NULL OR length(resolution_reason) <= 400 AND length(resolution_reason) > 0),
  resolved_at                              INTEGER,
  created_at                               INTEGER NOT NULL,
  CHECK ((status = 'resolved') = (resolution_outcome IS NOT NULL))
) STRICT;
CREATE TABLE transition_cases (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  player_name                              TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  started_by_kind                          TEXT NOT NULL CHECK (started_by_kind IN ('player','guardian')),
  started_by_id                            TEXT NOT NULL CHECK (length(started_by_id) <= 80 AND length(started_by_id) > 0),
  started_by_name                          TEXT CHECK (started_by_name IS NULL OR length(started_by_name) <= 200),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 500),
  period_ends_at                           INTEGER NOT NULL,
  status                                   TEXT NOT NULL CHECK (status IN ('open','withdrawn','placed','expired')),
  placement_org_id                         TEXT CHECK (placement_org_id IS NULL OR length(placement_org_id) <= 80 AND length(placement_org_id) > 0),
  placement_org_name                       TEXT CHECK (placement_org_name IS NULL OR length(placement_org_name) <= 200),
  placement_at                             INTEGER,
  placement_note                           TEXT CHECK (placement_note IS NULL OR length(placement_note) <= 300),
  follow_up_due_at                         INTEGER,
  follow_up_notified_at                    INTEGER,
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (placement_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK ((status = 'placed') = (placement_org_id IS NOT NULL)),
  CHECK (follow_up_due_at IS NULL OR placement_org_id IS NOT NULL),
  CHECK (placement_org_id IS NULL OR placement_at IS NOT NULL),
  CHECK (placement_org_id IS NOT NULL OR (placement_org_name IS NULL AND placement_at IS NULL AND placement_note IS NULL)),
  CHECK (follow_up_due_at IS NOT NULL OR follow_up_notified_at IS NULL)
) STRICT;
CREATE TABLE transition_case_pack_items (
  transition_case_id TEXT NOT NULL REFERENCES transition_cases(id) ON DELETE CASCADE,
  item_kind         TEXT NOT NULL CHECK (item_kind IN ('media','evidence','feedback')),
  ord                INTEGER NOT NULL CHECK (ord >= 0 AND ord < 100),
  item_id            TEXT NOT NULL CHECK (length(item_id) > 0 AND length(item_id) <= 80),
  PRIMARY KEY (transition_case_id, item_kind, item_id),
  UNIQUE (transition_case_id, item_kind, ord)
) STRICT;
CREATE TABLE transition_case_recipients (
  transition_case_id                       TEXT NOT NULL CHECK (length(transition_case_id) <= 80 AND length(transition_case_id) > 0),
  ord                                      INTEGER NOT NULL,
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  org_name                                 TEXT CHECK (org_name IS NULL OR length(org_name) <= 200),
  granted_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  revoked_at                               INTEGER,
  viewed_at                                INTEGER,
  FOREIGN KEY (transition_case_id) REFERENCES transition_cases(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (transition_case_id, ord),
  CHECK (ord >= 0),
  CHECK (expires_at >= granted_at)
) STRICT;
CREATE TABLE transition_case_history (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transition_case_id                       TEXT NOT NULL CHECK (length(transition_case_id) <= 80 AND length(transition_case_id) > 0),
  at                                       INTEGER NOT NULL,
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('player','guardian','system')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action                                   TEXT NOT NULL CHECK (action IN ('opened','recipient_added','recipient_revoked','withdrawn','placed','expired')),
  detail_items                             INTEGER,
  detail_org_id                            TEXT CHECK (detail_org_id IS NULL OR length(detail_org_id) <= 80 AND length(detail_org_id) > 0),
  FOREIGN KEY (transition_case_id) REFERENCES transition_cases(id) ON DELETE CASCADE,
  CHECK (detail_items IS NULL OR detail_items > 0),
  CHECK ((action = 'opened') = (detail_items IS NOT NULL)),
  CHECK ((action IN ('recipient_added','recipient_revoked','placed')) = (detail_org_id IS NOT NULL))
) STRICT;
CREATE TABLE vouches (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  player_name                              TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  coach_name                               TEXT NOT NULL CHECK (length(coach_name) <= 100 AND length(coach_name) > 0),
  coach_email                              TEXT CHECK (coach_email IS NULL OR length(coach_email) <= 254),
  role                                     TEXT NOT NULL CHECK (length(role) <= 200 AND length(role) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('pending','published','revoked')),
  code_hash                                TEXT CHECK (code_hash IS NULL OR length(code_hash) <= 64),
  text                                     TEXT CHECK (text IS NULL OR length(text) <= 400),
  seasons                                  TEXT CHECK (seasons IS NULL OR length(seasons) <= 40),
  created_at                               INTEGER NOT NULL,
  published_at                             INTEGER,
  conflict_of_interest                     TEXT CHECK (conflict_of_interest IS NULL OR length(conflict_of_interest) <= 200),
  withdrawn_at                             INTEGER,
  withdrawn_by                             TEXT CHECK (withdrawn_by IS NULL OR withdrawn_by IN ('admin')),
  withdrawn_reason                         TEXT CHECK (withdrawn_reason IS NULL OR length(withdrawn_reason) <= 200 AND length(withdrawn_reason) > 0),
  CHECK (length(code_hash) = 64 AND code_hash NOT GLOB '*[^0-9a-f]*'),
  CHECK ((status = 'pending') = (code_hash IS NOT NULL)),
  CHECK (status <> 'published' OR (text IS NOT NULL AND published_at IS NOT NULL)),
  CHECK ((withdrawn_at IS NULL) = (withdrawn_by IS NULL) AND (withdrawn_at IS NULL) = (withdrawn_reason IS NULL))
) STRICT;
CREATE TABLE agent_profiles (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) <= 80 AND length(user_id) > 0),
  agency_org_id                            TEXT NOT NULL CHECK (length(agency_org_id) <= 80 AND length(agency_org_id) > 0),
  display_name                             TEXT NOT NULL CHECK (length(display_name) <= 80 AND length(display_name) > 0),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  rev_by_id                                TEXT CHECK (rev_by_id IS NULL OR length(rev_by_id) <= 80),
  declared_fifa_licence_number             TEXT CHECK (declared_fifa_licence_number IS NULL OR length(declared_fifa_licence_number) <= 40 AND length(declared_fifa_licence_number) > 0),
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (agency_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  UNIQUE (user_id),
  CHECK (rev >= 1)
) STRICT;
CREATE TABLE agent_profile_jurisdictions (
  profile_id    TEXT NOT NULL REFERENCES agent_profiles(id) ON DELETE CASCADE,
  ord           INTEGER NOT NULL CHECK (ord >= 0),
  jurisdiction  TEXT NOT NULL CHECK (jurisdiction IN ('INT','ENG','USA')),
  PRIMARY KEY (profile_id, jurisdiction),
  UNIQUE (profile_id, ord)
) STRICT;
CREATE TABLE agent_profile_facets (
  profile_id                               TEXT NOT NULL CHECK (length(profile_id) <= 80 AND length(profile_id) > 0),
  facet                                    TEXT NOT NULL CHECK (facet IN ('fifa_licence','national_registration','domestic_authorisation','minors_authorisation')),
  member_association                       TEXT NOT NULL CHECK (member_association IN ('INT','ENG','USA')),
  state                                    TEXT NOT NULL CHECK (state IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  reference                                TEXT CHECK (reference IS NULL OR length(reference) <= 60 AND length(reference) > 0),
  provenance_provider                      TEXT CHECK (provenance_provider IS NULL OR provenance_provider IN ('none','local-synthetic-test-provider','attributed_review')),
  provenance_kind                          TEXT CHECK (provenance_kind IS NULL OR provenance_kind IN ('none','synthetic','human_review')),
  provenance_at                            INTEGER,
  provenance_reviewer_id                   TEXT CHECK (provenance_reviewer_id IS NULL OR length(provenance_reviewer_id) <= 80 AND length(provenance_reviewer_id) > 0),
  provenance_review_id                     TEXT CHECK (provenance_review_id IS NULL OR length(provenance_review_id) <= 80 AND length(provenance_review_id) > 0),
  submitted_at                             INTEGER,
  verified_at                              INTEGER,
  recheck_at                               INTEGER,
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 1000),
  stale_notified_at                        INTEGER,
  FOREIGN KEY (profile_id) REFERENCES agent_profiles(id) ON DELETE CASCADE,
  PRIMARY KEY (profile_id, facet, member_association),
  CHECK ((facet = 'fifa_licence') = (member_association = 'INT')),
  CHECK (provenance_reviewer_id IS NULL OR provenance_provider = 'attributed_review')
) STRICT;
CREATE TABLE agent_profile_history (
  id                    TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  profile_id            TEXT NOT NULL REFERENCES agent_profiles(id) ON DELETE CASCADE,
  ord                   INTEGER NOT NULL CHECK (ord >= 0),
  at                    INTEGER NOT NULL,
  by_kind               TEXT NOT NULL CHECK (by_kind IN ('org','player','ts_reviewer','system')),
  by_id                 TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name               TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role               TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  action                TEXT NOT NULL CHECK (action IN ('agent_profile_created','agent_profile_updated','agent_verification_submitted','agent_verification_state_changed','agent_facet_rechecked')),
  detail_display_name   INTEGER CHECK (detail_display_name IN (0,1)),
  detail_jurisdictions  INTEGER CHECK (detail_jurisdictions IN (0,1)),
  detail_licence_number INTEGER CHECK (detail_licence_number IN (0,1)),
  detail_facet          TEXT CHECK (detail_facet IS NULL OR detail_facet IN ('fifa_licence','national_registration','domestic_authorisation','minors_authorisation')),
  detail_ma             TEXT CHECK (detail_ma IS NULL OR detail_ma IN ('INT','ENG','USA')),
  detail_from TEXT CHECK (detail_from IS NULL OR detail_from IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  detail_to TEXT CHECK (detail_to IS NULL OR detail_to IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  detail_state TEXT CHECK (detail_state IS NULL OR detail_state IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  detail_review_id      TEXT CHECK (detail_review_id IS NULL OR (length(detail_review_id) > 0 AND length(detail_review_id) <= 80)),
  UNIQUE (profile_id, ord),
  CHECK ((action = 'agent_profile_updated') = (detail_display_name IS NOT NULL)),
  CHECK ((detail_display_name IS NULL) = (detail_jurisdictions IS NULL) AND (detail_display_name IS NULL) = (detail_licence_number IS NULL)),
  CHECK ((action IN ('agent_verification_submitted','agent_verification_state_changed','agent_facet_rechecked')) = (detail_facet IS NOT NULL)),
  CHECK ((action IN ('agent_verification_state_changed','agent_facet_rechecked')) = (detail_to IS NOT NULL)),
  CHECK ((detail_from IS NULL) = (detail_to IS NULL)),
  CHECK ((action = 'agent_verification_state_changed') = (detail_state IS NOT NULL)),
  CHECK (detail_review_id IS NULL OR action = 'agent_verification_state_changed')
) STRICT;
CREATE TABLE agency_affiliations (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  agency_org_id                            TEXT NOT NULL CHECK (length(agency_org_id) <= 80 AND length(agency_org_id) > 0),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) <= 80 AND length(user_id) > 0),
  started_at                               INTEGER NOT NULL,
  ended_at                                 INTEGER,
  ended_reason                             TEXT CHECK (ended_reason IS NULL OR length(ended_reason) <= 40),
  created_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  rev_by_id                                TEXT CHECK (rev_by_id IS NULL OR length(rev_by_id) <= 80),
  create_key                               TEXT CHECK (create_key IS NULL OR length(create_key) <= 64 AND length(create_key) > 0),
  create_fp                                TEXT CHECK (create_fp IS NULL OR length(create_fp) <= 4000),
  FOREIGN KEY (agency_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (rev >= 1),
  CHECK (ended_at IS NULL OR ended_reason IS NOT NULL),
  CHECK ((create_key IS NULL) = (create_fp IS NULL))
) STRICT;
CREATE TABLE agency_affiliation_tiers (
  affiliation_id  TEXT NOT NULL REFERENCES agency_affiliations(id) ON DELETE CASCADE,
  ord             INTEGER NOT NULL CHECK (ord >= 0),
  tier            TEXT NOT NULL CHECK (tier IN ('licensed_agent','agency_admin','analyst','assistant','finance')),
  PRIMARY KEY (affiliation_id, tier),
  UNIQUE (affiliation_id, ord)
) STRICT;
CREATE TABLE agency_affiliation_history (
  id                    TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  affiliation_id        TEXT NOT NULL REFERENCES agency_affiliations(id) ON DELETE CASCADE,
  ord                   INTEGER NOT NULL CHECK (ord >= 0),
  at                    INTEGER NOT NULL,
  by_kind               TEXT NOT NULL CHECK (by_kind IN ('org','player','ts_reviewer','system')),
  by_id                 TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name               TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role               TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  action                TEXT NOT NULL CHECK (action IN ('agency_affiliation_created','agency_affiliation_updated','agency_affiliation_ended')),
  detail_bootstrap      INTEGER CHECK (detail_bootstrap IN (1)),
  detail_reason_code    TEXT CHECK (detail_reason_code IS NULL OR length(detail_reason_code) <= 40),
  UNIQUE (affiliation_id, ord),
  CHECK (detail_bootstrap IS NULL OR action = 'agency_affiliation_created'),
  CHECK ((action = 'agency_affiliation_ended') = (detail_reason_code IS NOT NULL))
) STRICT;
CREATE TABLE agency_affiliation_history_tiers (
  history_id  TEXT NOT NULL REFERENCES agency_affiliation_history(id) ON DELETE CASCADE,
  list        TEXT NOT NULL CHECK (list IN ('from','to')),
  ord         INTEGER NOT NULL CHECK (ord >= 0),
  tier        TEXT NOT NULL CHECK (tier IN ('licensed_agent','agency_admin','analyst','assistant','finance')),
  PRIMARY KEY (history_id, list, ord)
) STRICT;
CREATE TABLE representation_agreements (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  agent_user_id                            TEXT NOT NULL CHECK (length(agent_user_id) <= 80 AND length(agent_user_id) > 0),
  agency_org_id                            TEXT NOT NULL CHECK (length(agency_org_id) <= 80 AND length(agency_org_id) > 0),
  client_kind                              TEXT NOT NULL CHECK (client_kind IN ('player')),
  client_id                                TEXT NOT NULL CHECK (length(client_id) <= 80 AND length(client_id) > 0),
  jurisdiction                             TEXT NOT NULL CHECK (jurisdiction IN ('INT','ENG','USA')),
  exclusive                                INTEGER NOT NULL CHECK (exclusive IN (0,1)),
  term_months                              INTEGER NOT NULL,
  start_at                                 INTEGER,
  end_at                                   INTEGER,
  status                                   TEXT NOT NULL CHECK (status IN ('proposed','active','declined','terminated_by_client','terminated_by_agent','disputed')),
  proposed_at                              INTEGER NOT NULL,
  confirmed_at                             INTEGER,
  declined_at                              INTEGER,
  terminated_at                            INTEGER,
  terminated_by                            TEXT CHECK (terminated_by IS NULL OR terminated_by IN ('agent','client','trust_safety')),
  termination_reason_code                  TEXT CHECK (termination_reason_code IS NULL OR length(termination_reason_code) <= 40),
  disputed_at                              INTEGER,
  dispute_reason                           TEXT CHECK (dispute_reason IS NULL OR length(dispute_reason) <= 300),
  dispute_resolved_at                      INTEGER,
  dispute_review_id                        TEXT CHECK (dispute_review_id IS NULL OR length(dispute_review_id) <= 80 AND length(dispute_review_id) > 0),
  dispute_outcome                          TEXT CHECK (dispute_outcome IS NULL OR dispute_outcome IN ('reinstated','ended')),
  share_with_agency_staff                  INTEGER NOT NULL CHECK (share_with_agency_staff IN (0,1)),
  disclosure_club_presence                 INTEGER NOT NULL CHECK (disclosure_club_presence IN (0,1)),
  disclosure_contact_routing               INTEGER NOT NULL CHECK (disclosure_contact_routing IN (0,1)),
  disclosure_trial_visibility              INTEGER NOT NULL CHECK (disclosure_trial_visibility IN (0,1)),
  subject_removed_at                       INTEGER,
  expiry_notified_at                       INTEGER,
  created_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  rev_by_id                                TEXT CHECK (rev_by_id IS NULL OR length(rev_by_id) <= 80),
  confirmed_by_player_id                   TEXT CHECK (confirmed_by_player_id IS NULL OR length(confirmed_by_player_id) <= 80 AND length(confirmed_by_player_id) > 0),
  request_key                              TEXT CHECK (request_key IS NULL OR length(request_key) <= 64 AND length(request_key) > 0),
  request_fp                               TEXT CHECK (request_fp IS NULL OR length(request_fp) <= 4000),
  confirm_key                              TEXT CHECK (confirm_key IS NULL OR length(confirm_key) <= 64 AND length(confirm_key) > 0),
  confirm_fp                               TEXT CHECK (confirm_fp IS NULL OR length(confirm_fp) <= 4000),
  decline_key                              TEXT CHECK (decline_key IS NULL OR length(decline_key) <= 64 AND length(decline_key) > 0),
  decline_fp                               TEXT CHECK (decline_fp IS NULL OR length(decline_fp) <= 4000),
  client_terminate_key                     TEXT CHECK (client_terminate_key IS NULL OR length(client_terminate_key) <= 64 AND length(client_terminate_key) > 0),
  client_terminate_fp                      TEXT CHECK (client_terminate_fp IS NULL OR length(client_terminate_fp) <= 4000),
  dispute_key                              TEXT CHECK (dispute_key IS NULL OR length(dispute_key) <= 64 AND length(dispute_key) > 0),
  dispute_fp                               TEXT CHECK (dispute_fp IS NULL OR length(dispute_fp) <= 4000),
  agent_terminate_key                      TEXT CHECK (agent_terminate_key IS NULL OR length(agent_terminate_key) <= 64 AND length(agent_terminate_key) > 0),
  agent_terminate_fp                       TEXT CHECK (agent_terminate_fp IS NULL OR length(agent_terminate_fp) <= 4000),
  FOREIGN KEY (agent_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (agency_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (term_months BETWEEN 1 AND 24),
  CHECK (rev >= 1),
  CHECK ((confirmed_at IS NULL) = (confirmed_by_player_id IS NULL)),
  CHECK ((status = 'declined') = (declined_at IS NOT NULL)),
  CHECK ((terminated_at IS NULL) = (terminated_by IS NULL)),
  CHECK (status NOT IN ('terminated_by_client','terminated_by_agent') OR terminated_at IS NOT NULL),
  CHECK (status <> 'disputed' OR disputed_at IS NOT NULL),
  CHECK ((dispute_resolved_at IS NULL) = (dispute_review_id IS NULL)),
  CHECK ((request_key IS NULL) = (request_fp IS NULL)),
  CHECK ((confirm_key IS NULL) = (confirm_fp IS NULL)),
  CHECK ((decline_key IS NULL) = (decline_fp IS NULL)),
  CHECK ((client_terminate_key IS NULL) = (client_terminate_fp IS NULL)),
  CHECK ((dispute_key IS NULL) = (dispute_fp IS NULL)),
  CHECK ((agent_terminate_key IS NULL) = (agent_terminate_fp IS NULL))
) STRICT;
CREATE TABLE agreement_scopes (
  agreement_id  TEXT NOT NULL REFERENCES representation_agreements(id) ON DELETE CASCADE,
  ord           INTEGER NOT NULL CHECK (ord >= 0),
  scope         TEXT NOT NULL CHECK (scope IN ('employment','transfer','commercial','other_services')),
  PRIMARY KEY (agreement_id, scope),
  UNIQUE (agreement_id, ord)
) STRICT;
CREATE TABLE agreement_policy_versions (
  agreement_id       TEXT NOT NULL REFERENCES representation_agreements(id) ON DELETE CASCADE,
  ord                INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL CHECK (length(policy_version_id) > 0 AND length(policy_version_id) <= 80),
  PRIMARY KEY (agreement_id, policy_version_id),
  UNIQUE (agreement_id, ord)
) STRICT;
CREATE TABLE agreement_opportunity_shares (
  agreement_id                             TEXT NOT NULL CHECK (length(agreement_id) <= 80 AND length(agreement_id) > 0),
  ord                                      INTEGER NOT NULL,
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  opportunity_id                           TEXT NOT NULL CHECK (length(opportunity_id) <= 80 AND length(opportunity_id) > 0),
  via                                      TEXT CHECK (via IS NULL OR via IN ('opportunity','open_trial')),
  title                                    TEXT CHECK (title IS NULL OR length(title) <= 200),
  org_name                                 TEXT CHECK (org_name IS NULL OR length(org_name) <= 200),
  deadline                                 TEXT CHECK (deadline IS NULL OR length(deadline) <= 40),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 300 AND length(note) > 0),
  shared_at                                INTEGER NOT NULL,
  shared_by_kind                           TEXT NOT NULL CHECK (shared_by_kind IN ('org')),
  shared_by_user_id                        TEXT NOT NULL CHECK (length(shared_by_user_id) <= 80 AND length(shared_by_user_id) > 0),
  shared_by_name                           TEXT CHECK (shared_by_name IS NULL OR length(shared_by_name) <= 200),
  withdrawn_at                             INTEGER,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER NOT NULL,
  share_key                                TEXT CHECK (share_key IS NULL OR length(share_key) <= 64 AND length(share_key) > 0),
  share_fp                                 TEXT CHECK (share_fp IS NULL OR length(share_fp) <= 4000),
  FOREIGN KEY (agreement_id) REFERENCES representation_agreements(id) ON DELETE CASCADE,
  FOREIGN KEY (shared_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  UNIQUE (agreement_id, ord),
  CHECK (ord >= 0 AND ord < 200),
  CHECK (rev >= 1),
  CHECK ((share_key IS NULL) = (share_fp IS NULL))
) STRICT;
CREATE TABLE agreement_history (
  id                              TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  agreement_id                    TEXT NOT NULL REFERENCES representation_agreements(id) ON DELETE CASCADE,
  ord                             INTEGER NOT NULL CHECK (ord >= 0),
  at                              INTEGER NOT NULL,
  by_kind                         TEXT NOT NULL CHECK (by_kind IN ('org','player','ts_reviewer','system')),
  by_id                           TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name                         TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role                         TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  action                          TEXT NOT NULL CHECK (action IN ('representation_requested','representation_confirmed','representation_rejected','representation_terminated','representation_disputed','representation_sharing_changed','opportunity_shared','opportunity_share_withdrawn')),
  detail_by                       TEXT CHECK (detail_by IS NULL OR detail_by IN ('agent','client','trust_safety')),
  detail_from TEXT CHECK (detail_from IS NULL OR detail_from IN ('proposed','active','declined','expired','terminated_by_client','terminated_by_agent','disputed')),
  detail_to TEXT CHECK (detail_to IS NULL OR detail_to IN ('proposed','active','declined','expired','terminated_by_client','terminated_by_agent','disputed')),
  detail_had_reason               INTEGER CHECK (detail_had_reason IN (0,1)),
  detail_phase TEXT CHECK (detail_phase IS NULL OR detail_phase IN ('proposed','active','declined','expired','terminated_by_client','terminated_by_agent','disputed')),
  detail_reason_code              TEXT CHECK (detail_reason_code IS NULL OR length(detail_reason_code) <= 40),
  detail_review_id                TEXT CHECK (detail_review_id IS NULL OR (length(detail_review_id) > 0 AND length(detail_review_id) <= 80)),
  detail_share_with_agency_staff  INTEGER CHECK (detail_share_with_agency_staff IN (0,1)),
  detail_club_presence            INTEGER CHECK (detail_club_presence IN (0,1)),
  detail_contact_routing          INTEGER CHECK (detail_contact_routing IN (0,1)),
  detail_trial_visibility         INTEGER CHECK (detail_trial_visibility IN (0,1)),
  detail_share_id                 TEXT CHECK (detail_share_id IS NULL OR (length(detail_share_id) > 0 AND length(detail_share_id) <= 80)),
  detail_via                      TEXT CHECK (detail_via IS NULL OR detail_via IN ('opportunity','open_trial')),
  UNIQUE (agreement_id, ord),
  CHECK ((action IN ('representation_confirmed','representation_rejected','representation_terminated','representation_disputed')) = (detail_by IS NOT NULL)),
  CHECK ((detail_by = 'client') = (detail_from IS NOT NULL AND detail_to IS NOT NULL AND detail_had_reason IS NOT NULL)),
  CHECK (detail_by IS NULL OR detail_by = 'client' OR (detail_phase IS NOT NULL AND detail_reason_code IS NOT NULL)),
  CHECK ((detail_by = 'trust_safety') = (detail_review_id IS NOT NULL)),
  CHECK ((action IN ('opportunity_shared','opportunity_share_withdrawn')) = (detail_share_id IS NOT NULL)),
  CHECK (detail_via IS NULL OR action = 'opportunity_shared'),
  CHECK ((action = 'representation_sharing_changed') = (coalesce(detail_share_with_agency_staff, detail_club_presence, detail_contact_routing, detail_trial_visibility) IS NOT NULL))
) STRICT;
CREATE TABLE org_agency_settings (
  org_id       TEXT PRIMARY KEY REFERENCES orgs(id) ON DELETE RESTRICT,
  description  TEXT NOT NULL CHECK (length(description) <= 300),
  updated_at   INTEGER NOT NULL
) STRICT;
CREATE TABLE org_agency_jurisdictions (
  org_id        TEXT NOT NULL REFERENCES org_agency_settings(org_id) ON DELETE CASCADE,
  ord           INTEGER NOT NULL CHECK (ord >= 0),
  jurisdiction  TEXT NOT NULL CHECK (jurisdiction IN ('INT','ENG','USA')),
  PRIMARY KEY (org_id, jurisdiction),
  UNIQUE (org_id, ord)
) STRICT;
CREATE TABLE ts_reviewers (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  name                                     TEXT NOT NULL CHECK (length(name) <= 80 AND length(name) > 0),
  role                                     TEXT NOT NULL CHECK (role IN ('trust_safety_reviewer','trust_safety_admin')),
  status                                   TEXT NOT NULL CHECK (status IN ('active','revoked')),
  secret_hash                              TEXT NOT NULL CHECK (length(secret_hash) <= 400 AND length(secret_hash) > 0),
  created_at                               INTEGER NOT NULL,
  created_by_kind                          TEXT NOT NULL CHECK (created_by_kind IN ('ts_reviewer','system')),
  created_by_id                            TEXT CHECK (created_by_id IS NULL OR length(created_by_id) <= 80 AND length(created_by_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_by_role                          TEXT CHECK (created_by_role IS NULL OR length(created_by_role) <= 60 AND length(created_by_role) > 0),
  revoked_at                               INTEGER,
  revoked_by_id                            TEXT CHECK (revoked_by_id IS NULL OR length(revoked_by_id) <= 40 AND length(revoked_by_id) > 0),
  revoked_by_name                          TEXT CHECK (revoked_by_name IS NULL OR length(revoked_by_name) <= 80),
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  rev_by_id                                TEXT CHECK (rev_by_id IS NULL OR length(rev_by_id) <= 80),
  FOREIGN KEY (revoked_by_id) REFERENCES ts_reviewers(id) ON DELETE RESTRICT,
  CHECK (rev >= 1),
  CHECK ((status = 'revoked') = (revoked_at IS NOT NULL)),
  CHECK ((revoked_at IS NULL) = (revoked_by_id IS NULL)),
  CHECK (created_by_kind = 'ts_reviewer' OR (created_by_id IS NULL AND created_by_role IS NULL))
) STRICT;
CREATE TABLE ts_reviewer_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  reviewer_id  TEXT NOT NULL REFERENCES ts_reviewers(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR by_role IN ('trust_safety_reviewer','trust_safety_admin')),
  action  TEXT NOT NULL CHECK (action IN ('reviewer_created','reviewer_revoked')),
  detail_role  TEXT CHECK (detail_role IS NULL OR detail_role IN ('trust_safety_reviewer','trust_safety_admin')),
  detail_reason  TEXT CHECK (detail_reason IS NULL OR (length(detail_reason) > 0 AND length(detail_reason) <= 200)),
  UNIQUE (reviewer_id, ord),
  CHECK ((action = 'reviewer_created') = (detail_role IS NOT NULL)),
  CHECK (action = 'reviewer_revoked' OR detail_reason IS NULL)
) STRICT;
CREATE TABLE jurisdiction_policies (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  regulator                                TEXT NOT NULL CHECK (length(regulator) <= 20 AND length(regulator) > 0),
  jurisdiction                             TEXT NOT NULL CHECK (jurisdiction IN ('INT','ENG','USA')),
  policy_version                           INTEGER NOT NULL,
  supersedes_id                            TEXT CHECK (supersedes_id IS NULL OR length(supersedes_id) <= 80 AND length(supersedes_id) > 0),
  effective_from_date                      TEXT NOT NULL CHECK (length(effective_from_date) <= 10),
  effective_to_date                        TEXT CHECK (effective_to_date IS NULL OR length(effective_to_date) <= 10),
  status                                   TEXT NOT NULL CHECK (status IN ('proposed','published')),
  proposed_by_id                           TEXT CHECK (proposed_by_id IS NULL OR length(proposed_by_id) <= 40 AND length(proposed_by_id) > 0),
  proposed_by_name                         TEXT CHECK (proposed_by_name IS NULL OR length(proposed_by_name) <= 80),
  proposed_at                              INTEGER,
  approved_by_id                           TEXT CHECK (approved_by_id IS NULL OR length(approved_by_id) <= 40 AND length(approved_by_id) > 0),
  approved_by_name                         TEXT CHECK (approved_by_name IS NULL OR length(approved_by_name) <= 80),
  approved_at                              INTEGER,
  published_at                             INTEGER,
  created_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  rev_by_id                                TEXT CHECK (rev_by_id IS NULL OR length(rev_by_id) <= 80),
  FOREIGN KEY (supersedes_id) REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  FOREIGN KEY (proposed_by_id) REFERENCES ts_reviewers(id) ON DELETE RESTRICT,
  FOREIGN KEY (approved_by_id) REFERENCES ts_reviewers(id) ON DELETE RESTRICT,
  CHECK (effective_from_date IS NULL OR effective_from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (effective_to_date IS NULL OR effective_to_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (policy_version >= 1),
  CHECK (rev >= 1),
  CHECK (effective_to_date IS NULL OR effective_to_date > effective_from_date),
  CHECK ((status = 'published') = (published_at IS NOT NULL)),
  CHECK (status = 'published' OR approved_by_id IS NULL),
  CHECK (supersedes_id IS NULL OR supersedes_id <> id)
) STRICT;
CREATE TABLE jurisdiction_policy_publishers (
  policy_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 2),
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('ts_reviewer','system')),
  by_id  TEXT NOT NULL CHECK (length(by_id) > 0 AND length(by_id) <= 80),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  PRIMARY KEY (policy_id, ord)
) STRICT;
CREATE TABLE jurisdiction_policy_rules (
  policy_id                                TEXT NOT NULL CHECK (length(policy_id) <= 80 AND length(policy_id) > 0),
  rule_id                                  TEXT NOT NULL CHECK (length(rule_id) <= 40 AND length(rule_id) > 0),
  ord                                      INTEGER NOT NULL,
  rule_status                              TEXT NOT NULL CHECK (rule_status IN ('ACTIVE','SUSPENDED','PARTIALLY_SUSPENDED','JURISDICTION_OVERRIDE','PENDING_IMPLEMENTATION','UNDER_LEGAL_REVIEW','UNKNOWN')),
  text_status                              TEXT CHECK (text_status IS NULL OR text_status IN ('CURRENT','CURRENT_BUT_SUSPENDED','CURRENT_WITH_PARTIAL_SUSPENSION','UNCERTAIN_OPERATIVE_STATUS','HISTORICAL','SUPERSEDED','ANNOUNCED')),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 1000 AND length(note) > 0),
  effective_from_date                      TEXT CHECK (effective_from_date IS NULL OR length(effective_from_date) <= 10),
  PRIMARY KEY (policy_id, rule_id),
  UNIQUE (policy_id, ord),
  CHECK (ord >= 0 AND ord < 200),
  CHECK (effective_from_date IS NULL OR effective_from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  FOREIGN KEY (policy_id) REFERENCES jurisdiction_policies(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE jurisdiction_policy_rule_sources (
  policy_id                                TEXT NOT NULL CHECK (length(policy_id) <= 80 AND length(policy_id) > 0),
  rule_id                                  TEXT NOT NULL CHECK (length(rule_id) <= 40 AND length(rule_id) > 0),
  ord                                      INTEGER NOT NULL,
  source                                   TEXT NOT NULL CHECK (length(source) <= 300 AND length(source) > 0),
  version                                  TEXT CHECK (version IS NULL OR length(version) <= 120 AND length(version) > 0),
  effective_date                           TEXT CHECK (effective_date IS NULL OR length(effective_date) <= 10),
  retrieved_date                           TEXT NOT NULL CHECK (length(retrieved_date) <= 10),
  PRIMARY KEY (policy_id, rule_id, ord),
  CHECK (ord >= 0 AND ord < 20),
  CHECK (effective_date IS NULL OR effective_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (retrieved_date IS NULL OR retrieved_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  FOREIGN KEY (policy_id, rule_id) REFERENCES jurisdiction_policy_rules(policy_id, rule_id) ON DELETE CASCADE
) STRICT;
CREATE TABLE jurisdiction_policy_rule_overrides (
  policy_id                                TEXT NOT NULL CHECK (length(policy_id) <= 80 AND length(policy_id) > 0),
  rule_id                                  TEXT NOT NULL CHECK (length(rule_id) <= 40 AND length(rule_id) > 0),
  ord                                      INTEGER NOT NULL,
  jurisdiction                             TEXT NOT NULL CHECK (jurisdiction IN ('INT','ENG','USA')),
  scope                                    TEXT NOT NULL CHECK (scope IN ('national')),
  override_rule_id                         TEXT NOT NULL CHECK (length(override_rule_id) <= 40 AND length(override_rule_id) > 0),
  PRIMARY KEY (policy_id, rule_id, ord),
  UNIQUE (policy_id, rule_id, jurisdiction),
  CHECK (ord >= 0 AND ord < 10),
  FOREIGN KEY (policy_id, rule_id) REFERENCES jurisdiction_policy_rules(policy_id, rule_id) ON DELETE CASCADE
) STRICT;
CREATE TABLE jurisdiction_policy_rule_params (
  policy_id  TEXT NOT NULL,
  rule_id  TEXT NOT NULL,
  name  TEXT NOT NULL CHECK (name IN ('licenceRequired','licenceHolder','onlyLicensedAgentPerforms','agencyStaffMayNotApproach','onlyLicensedAgentApproaches','maxTermMonthsIndividual','oneAgreementPerPair','legalAdviceNotice','permittedSets','consentKind','consentInAdvance','prohibitedWith','connectedAgentsAreOne','sameAgencyConnected','formula','firstContractAge','guardianConsentBeforeApproach','minorsAccreditationRequired','validityYears','informational','noFeeForMinorWithoutProContract','otherServicesPresumptionMonths','exclusivityWindowMonths','discloseConflicts','effectiveFrom','nationalRegistrationRequired','requiresFifaLicence','cascadeFromFifaLicence','onlyRegisteredAgentPerforms','agencyPartyColleaguePerformance','productionEnabled','pendingLegalReview','pfaLmaNotice','academicYearStart','coversIndirectApproach','minorsAuthorisationRequired','enhancedDbsWithinMonths','permittedMultiple','excludedRole','fullParticularsRequired','legalAdviceOfferRequired','prescribedForm','activeLimbs','lodgeWithinDays','domesticAuthorisationRequired','kind')),
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 46),
  flag_value  INTEGER CHECK (flag_value IS NULL OR flag_value IN (0,1)),
  count_value  INTEGER CHECK (count_value IS NULL OR count_value >= 0),
  text_value  TEXT CHECK (text_value IS NULL OR (length(text_value) > 0 AND length(text_value) <= 200)),
  PRIMARY KEY (policy_id, rule_id, name),
  UNIQUE (policy_id, rule_id, ord),
  CHECK ((flag_value IS NOT NULL) + (count_value IS NOT NULL) + (text_value IS NOT NULL) <= 1),
  FOREIGN KEY (policy_id, rule_id) REFERENCES jurisdiction_policy_rules(policy_id, rule_id) ON DELETE CASCADE
) STRICT;
CREATE TABLE jurisdiction_policy_rule_param_items (
  policy_id  TEXT NOT NULL,
  rule_id  TEXT NOT NULL,
  name  TEXT NOT NULL,
  set_no  INTEGER NOT NULL CHECK (set_no >= 0),
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  member  TEXT CHECK (member IS NULL OR (length(member) = 3 AND member GLOB '[A-Z][A-Z][A-Z]')),
  count_value  INTEGER CHECK (count_value IS NULL OR count_value >= 0),
  text_value  TEXT CHECK (text_value IS NULL OR (length(text_value) > 0 AND length(text_value) <= 200)),
  PRIMARY KEY (policy_id, rule_id, name, set_no, ord),
  CHECK ((member IS NULL) = (count_value IS NULL)),
  CHECK ((member IS NULL) <> (text_value IS NULL)),
  FOREIGN KEY (policy_id, rule_id, name) REFERENCES jurisdiction_policy_rule_params(policy_id, rule_id, name) ON DELETE CASCADE
) STRICT;
CREATE TABLE jurisdiction_policy_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  policy_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR by_role IN ('trust_safety_reviewer','trust_safety_admin')),
  action  TEXT NOT NULL CHECK (action IN ('policy_version_proposed','policy_version_published')),
  detail_seeded  INTEGER NOT NULL DEFAULT 0 CHECK (detail_seeded IN (0,1)),
  UNIQUE (policy_id, ord),
  CHECK (detail_seeded = 0 OR (action = 'policy_version_published' AND by_kind = 'system'))
) STRICT;
CREATE TABLE compliance_contexts (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  agency_org_id  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  agent_user_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  type  TEXT NOT NULL CHECK (type IN ('employment_contract','transfer','loan','other_services')),
  status  TEXT NOT NULL CHECK (status IN ('open','closed')),
  re_evaluation_pending  INTEGER NOT NULL CHECK (re_evaluation_pending IN (0,1)),
  review_rejected_at  INTEGER,
  origin  TEXT CHECK (origin IS NULL OR origin = 'transaction'),
  transaction_id  TEXT CHECK (transaction_id IS NULL OR (length(transaction_id) > 0 AND length(transaction_id) <= 80)),
  opened_at  INTEGER NOT NULL,
  closed_at  INTEGER,
  create_key  TEXT CHECK (create_key IS NULL OR (length(create_key) > 0 AND length(create_key) <= 64)),
  create_fp  TEXT CHECK ((create_fp IS NULL OR length(create_fp) <= 4000) AND ((create_key IS NULL) = (create_fp IS NULL))),
  rev  INTEGER NOT NULL CHECK (rev >= 1),
  rev_at  INTEGER,
  rev_by_id  TEXT CHECK (rev_by_id IS NULL OR (length(rev_by_id) > 0 AND length(rev_by_id) <= 80)),
  rev_by_name  TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  CHECK ((origin IS NULL) = (transaction_id IS NULL)),
  CHECK ((status = 'closed') = (closed_at IS NOT NULL))
) STRICT;
CREATE TABLE compliance_context_jurisdictions (
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 10),
  member_association  TEXT NOT NULL CHECK (member_association GLOB '[A-Z][A-Z][A-Z]'),
  PRIMARY KEY (context_id, ord),
  UNIQUE (context_id, member_association)
) STRICT;
CREATE TABLE compliance_context_parties (
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  id  TEXT NOT NULL CHECK ((length(id) > 0 AND length(id) <= 80)),
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  subject_kind  TEXT NOT NULL CHECK (subject_kind IN ('player','club')),
  subject_id  TEXT NOT NULL CHECK ((length(subject_id) > 0 AND length(subject_id) <= 80)),
  added_at  INTEGER,
  removed  INTEGER NOT NULL CHECK (removed IN (0,1)),
  removed_at  INTEGER,
  PRIMARY KEY (context_id, id),
  UNIQUE (context_id, ord),
  CHECK (removed = 1 OR removed_at IS NULL)
) STRICT;
CREATE TABLE compliance_context_representations (
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  id  TEXT NOT NULL CHECK ((length(id) > 0 AND length(id) <= 80)),
  agent_user_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  agreement_id  TEXT REFERENCES representation_agreements(id) ON DELETE RESTRICT,
  status  TEXT NOT NULL CHECK (status IN ('verified','pending_review','withdrawn')),
  declared_only  INTEGER NOT NULL CHECK (declared_only IN (0,1)),
  review_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  declared_at  INTEGER,
  first_act_at  INTEGER,
  withdrawn_at  INTEGER,
  verified_by_review_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  verified_at  INTEGER,
  declare_key  TEXT CHECK (declare_key IS NULL OR (length(declare_key) > 0 AND length(declare_key) <= 64)),
  declare_fp  TEXT CHECK ((declare_fp IS NULL OR length(declare_fp) <= 4000) AND ((declare_key IS NULL) = (declare_fp IS NULL))),
  PRIMARY KEY (context_id, id),
  UNIQUE (context_id, ord)
) STRICT;
CREATE TABLE compliance_context_resolved_facts (
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  code  TEXT NOT NULL CHECK (code IN ('OTHER_SERVICES_PRESUMPTION','INTEREST_DECLARED','REPRESENTATION_UNVERIFIED')),
  PRIMARY KEY (context_id, ord),
  UNIQUE (context_id, code)
) STRICT;
CREATE TABLE compliance_evaluations (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 100),
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE CASCADE,
  position  INTEGER NOT NULL CHECK (position >= 1),
  outcome  TEXT NOT NULL CHECK (outcome IN ('CLEAR','PERMITTED_DUAL_REPRESENTATION_CONSENT_REQUIRED','PROHIBITED_CONFLICT','MANUAL_REGULATORY_REVIEW_REQUIRED','INSUFFICIENT_DATA')),
  evaluated_at  INTEGER NOT NULL,
  input_hash  TEXT NOT NULL CHECK (length(input_hash) = 64),
  proposed_party_role  TEXT CHECK (proposed_party_role IS NULL OR proposed_party_role IN ('individual','engaging_entity','releasing_entity')),
  proposed_agent_user_id  TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  UNIQUE (context_id, position),
  UNIQUE (id, context_id),
  CHECK (id = context_id || '#' || position),
  CHECK ((proposed_party_role IS NULL) = (proposed_agent_user_id IS NULL))
) STRICT;
CREATE TABLE compliance_evaluation_reasons (
  evaluation_id  TEXT NOT NULL REFERENCES compliance_evaluations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  code  TEXT NOT NULL CHECK ((length(code) > 0 AND length(code) <= 60)),
  rule_id  TEXT CHECK (rule_id IS NULL OR (length(rule_id) > 0 AND length(rule_id) <= 40)),
  rule_status  TEXT CHECK (rule_status IS NULL OR rule_status IN ('ACTIVE','SUSPENDED','PARTIALLY_SUSPENDED','JURISDICTION_OVERRIDE','PENDING_IMPLEMENTATION','UNDER_LEGAL_REVIEW','UNKNOWN')),
  regulator  TEXT CHECK (regulator IS NULL OR (length(regulator) > 0 AND length(regulator) <= 20)),
  jurisdiction  TEXT CHECK (jurisdiction IS NULL OR jurisdiction GLOB '[A-Z][A-Z][A-Z]'),
  policy_version_id  TEXT CHECK (policy_version_id IS NULL OR (length(policy_version_id) > 0 AND length(policy_version_id) <= 80)),
  facet  TEXT CHECK (facet IS NULL OR (length(facet) > 0 AND length(facet) <= 80)),
  member_association  TEXT CHECK (member_association IS NULL OR (length(member_association) > 0 AND length(member_association) <= 80)),
  state  TEXT CHECK (state IS NULL OR (length(state) > 0 AND length(state) <= 80)),
  agent_user_id  TEXT CHECK (agent_user_id IS NULL OR (length(agent_user_id) > 0 AND length(agent_user_id) <= 80)),
  party_role  TEXT CHECK (party_role IS NULL OR (length(party_role) > 0 AND length(party_role) <= 80)),
  consent_kind  TEXT CHECK (consent_kind IS NULL OR (length(consent_kind) > 0 AND length(consent_kind) <= 80)),
  detail_text  TEXT CHECK (detail_text IS NULL OR (length(detail_text) > 0 AND length(detail_text) <= 300)),
  reason_text  TEXT CHECK (reason_text IS NULL OR (length(reason_text) > 0 AND length(reason_text) <= 80)),
  override_rule_id  TEXT CHECK (override_rule_id IS NULL OR (length(override_rule_id) > 0 AND length(override_rule_id) <= 80)),
  kind_text  TEXT CHECK (kind_text IS NULL OR (length(kind_text) > 0 AND length(kind_text) <= 80)),
  via_connected_agent  INTEGER CHECK (via_connected_agent IS NULL OR via_connected_agent = 1),
  has_party_roles  INTEGER NOT NULL DEFAULT 0 CHECK (has_party_roles IN (0,1)),
  has_jurisdictions  INTEGER NOT NULL DEFAULT 0 CHECK (has_jurisdictions IN (0,1)),
  PRIMARY KEY (evaluation_id, ord)
) STRICT;
CREATE TABLE compliance_evaluation_reason_items (
  evaluation_id  TEXT NOT NULL,
  reason_ord  INTEGER NOT NULL,
  list  TEXT NOT NULL CHECK (list IN ('partyRoles','jurisdictions')),
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  value  TEXT NOT NULL CHECK (length(value) > 0 AND length(value) <= 80),
  PRIMARY KEY (evaluation_id, reason_ord, list, ord),
  FOREIGN KEY (evaluation_id, reason_ord) REFERENCES compliance_evaluation_reasons(evaluation_id, ord) ON DELETE CASCADE
) STRICT;
CREATE TABLE compliance_evaluation_consents_outstanding (
  evaluation_id  TEXT NOT NULL REFERENCES compliance_evaluations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  agent_user_id  TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  consent_kind  TEXT NOT NULL CHECK (consent_kind IN ('dual_representation','agency_performance','guardian_approach','guardian_agreement','legal_advice_ack')),
  reason_code  TEXT NOT NULL CHECK ((length(reason_code) > 0 AND length(reason_code) <= 60)),
  PRIMARY KEY (evaluation_id, ord),
  UNIQUE (evaluation_id, party_role, consent_kind)
) STRICT;
CREATE TABLE compliance_evaluation_policy_versions (
  evaluation_id  TEXT NOT NULL REFERENCES compliance_evaluations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  PRIMARY KEY (evaluation_id, ord),
  UNIQUE (evaluation_id, policy_version_id)
) STRICT;
CREATE TABLE compliance_evaluation_snapshot_parties (
  evaluation_id  TEXT NOT NULL REFERENCES compliance_evaluations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  subject_kind  TEXT NOT NULL CHECK (subject_kind IN ('player','club')),
  subject_id  TEXT NOT NULL CHECK ((length(subject_id) > 0 AND length(subject_id) <= 80)),
  PRIMARY KEY (evaluation_id, ord)
) STRICT;
CREATE TABLE compliance_evaluation_snapshot_representations (
  evaluation_id  TEXT NOT NULL REFERENCES compliance_evaluations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  agent_user_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  status  TEXT NOT NULL CHECK (status IN ('verified','pending_review','withdrawn')),
  PRIMARY KEY (evaluation_id, ord)
) STRICT;
CREATE TABLE regulatory_reviews (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  kind  TEXT NOT NULL CHECK (kind IN ('verification_facet','representation_declared','conflict_evaluation','representation_dispute')),
  status  TEXT NOT NULL CHECK (status IN ('PENDING','IN_REVIEW','APPROVED','REJECTED','CANCELLED','SUPERSEDED')),
  agency_org_id  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  agent_user_id  TEXT REFERENCES org_users(id) ON DELETE RESTRICT,
  subject_profile_id  TEXT REFERENCES agent_profiles(id) ON DELETE RESTRICT,
  subject_user_id  TEXT CHECK (subject_user_id IS NULL OR (length(subject_user_id) > 0 AND length(subject_user_id) <= 80)),
  subject_facet  TEXT CHECK (subject_facet IS NULL OR subject_facet IN ('fifa_licence','national_registration','domestic_authorisation','minors_authorisation')),
  subject_member_association  TEXT CHECK (subject_member_association IS NULL OR subject_member_association GLOB '[A-Z][A-Z][A-Z]'),
  subject_agreement_id  TEXT REFERENCES representation_agreements(id) ON DELETE RESTRICT,
  subject_context_id  TEXT REFERENCES compliance_contexts(id) ON DELETE RESTRICT,
  subject_transaction_id  TEXT CHECK (subject_transaction_id IS NULL OR (length(subject_transaction_id) > 0 AND length(subject_transaction_id) <= 80)),
  subject_representation_id  TEXT CHECK (subject_representation_id IS NULL OR (length(subject_representation_id) > 0 AND length(subject_representation_id) <= 80)),
  subject_party_role  TEXT CHECK (subject_party_role IS NULL OR subject_party_role IN ('individual','engaging_entity','releasing_entity')),
  subject_is_approach  INTEGER NOT NULL CHECK (subject_is_approach IN (0,1)),
  subject_player_id  TEXT CHECK (subject_player_id IS NULL OR (length(subject_player_id) > 0 AND length(subject_player_id) <= 80)),
  subject_jurisdiction  TEXT CHECK (subject_jurisdiction IS NULL OR subject_jurisdiction GLOB '[A-Z][A-Z][A-Z]'),
  snapshot_outcome  TEXT CHECK (snapshot_outcome IS NULL OR snapshot_outcome IN ('CLEAR','PERMITTED_DUAL_REPRESENTATION_CONSENT_REQUIRED','PROHIBITED_CONFLICT','MANUAL_REGULATORY_REVIEW_REQUIRED','INSUFFICIENT_DATA')),
  snapshot_evaluation_id  TEXT,
  snapshot_evaluated_at  INTEGER,
  requested_at  INTEGER NOT NULL,
  requested_by_kind  TEXT NOT NULL CHECK (requested_by_kind IN ('org','player','club_user','ts_reviewer','system')),
  requested_by_id  TEXT CHECK (requested_by_id IS NULL OR (length(requested_by_id) > 0 AND length(requested_by_id) <= 80)),
  requested_by_name  TEXT CHECK (requested_by_name IS NULL OR length(requested_by_name) <= 200),
  requested_by_role  TEXT CHECK (requested_by_role IS NULL OR length(requested_by_role) <= 60),
  started_at  INTEGER,
  started_by_id  TEXT REFERENCES ts_reviewers(id) ON DELETE RESTRICT,
  started_by_name  TEXT CHECK (started_by_name IS NULL OR length(started_by_name) <= 200),
  started_by_role  TEXT CHECK (started_by_role IS NULL OR started_by_role IN ('trust_safety_reviewer','trust_safety_admin')),
  decided_at  INTEGER,
  decision_reviewer_id  TEXT REFERENCES ts_reviewers(id) ON DELETE RESTRICT,
  decision_reviewer_name  TEXT CHECK (decision_reviewer_name IS NULL OR length(decision_reviewer_name) <= 200),
  decision_reviewer_role  TEXT CHECK (decision_reviewer_role IS NULL OR decision_reviewer_role IN ('trust_safety_reviewer','trust_safety_admin')),
  decision_outcome  TEXT CHECK (decision_outcome IS NULL OR decision_outcome IN ('APPROVED','REJECTED','CANCELLED')),
  decision_reason_code  TEXT CHECK (decision_reason_code IS NULL OR (length(decision_reason_code) > 0 AND length(decision_reason_code) <= 60)),
  decision_reason  TEXT CHECK (decision_reason IS NULL OR (length(decision_reason) > 0 AND length(decision_reason) <= 1000)),
  decision_at  INTEGER,
  prior_status  TEXT CHECK (prior_status IS NULL OR prior_status IN ('PENDING','IN_REVIEW','APPROVED','REJECTED','CANCELLED','SUPERSEDED')),
  prior_facet_state  TEXT CHECK (prior_facet_state IS NULL OR prior_facet_state IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  prior_agreement_status  TEXT CHECK (prior_agreement_status IS NULL OR prior_agreement_status IN ('proposed','active','declined','expired','terminated_by_client','terminated_by_agent','disputed')),
  prior_context_outcome  TEXT CHECK (prior_context_outcome IS NULL OR prior_context_outcome IN ('CLEAR','PERMITTED_DUAL_REPRESENTATION_CONSENT_REQUIRED','PROHIBITED_CONFLICT','MANUAL_REGULATORY_REVIEW_REQUIRED','INSUFFICIENT_DATA')),
  prior_representation_status  TEXT CHECK (prior_representation_status IS NULL OR prior_representation_status IN ('verified','pending_review','withdrawn')),
  result_facet_state  TEXT CHECK (result_facet_state IS NULL OR result_facet_state IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  result_agreement_status  TEXT CHECK (result_agreement_status IS NULL OR result_agreement_status IN ('proposed','active','declined','expired','terminated_by_client','terminated_by_agent','disputed')),
  result_context_outcome  TEXT CHECK (result_context_outcome IS NULL OR result_context_outcome IN ('CLEAR','PERMITTED_DUAL_REPRESENTATION_CONSENT_REQUIRED','PROHIBITED_CONFLICT','MANUAL_REGULATORY_REVIEW_REQUIRED','INSUFFICIENT_DATA')),
  result_representation_status  TEXT CHECK (result_representation_status IS NULL OR result_representation_status IN ('verified','pending_review','withdrawn')),
  result_note  TEXT CHECK (result_note IS NULL OR result_note IN ('profile gone','not disputed any more','context gone')),
  supersedes_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  resolve_key  TEXT CHECK (resolve_key IS NULL OR (length(resolve_key) > 0 AND length(resolve_key) <= 64)),
  resolve_fp  TEXT CHECK ((resolve_fp IS NULL OR length(resolve_fp) <= 4000) AND ((resolve_key IS NULL) = (resolve_fp IS NULL))),
  rev  INTEGER NOT NULL CHECK (rev >= 1),
  rev_at  INTEGER,
  rev_by_id  TEXT CHECK (rev_by_id IS NULL OR (length(rev_by_id) > 0 AND length(rev_by_id) <= 80)),
  rev_by_name  TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  CHECK ((decision_outcome IS NULL) = (decision_reviewer_id IS NULL)),
  CHECK (snapshot_evaluation_id IS NULL OR snapshot_outcome IS NOT NULL),
  CHECK (snapshot_evaluation_id IS NULL OR subject_context_id IS NOT NULL),
  CHECK ((started_at IS NULL) = (started_by_id IS NULL)),
  CHECK ((decided_at IS NOT NULL) = (decision_outcome IS NOT NULL OR status = 'CANCELLED')),
  CHECK (decision_outcome IS NOT NULL OR status IN ('PENDING','IN_REVIEW','CANCELLED')),
  CHECK (decision_outcome IS NULL OR decision_outcome = status OR (status = 'SUPERSEDED' AND decision_outcome <> 'CANCELLED')),
  FOREIGN KEY (snapshot_evaluation_id, subject_context_id) REFERENCES compliance_evaluations(id, context_id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE regulatory_review_reasons (
  review_id  TEXT NOT NULL REFERENCES regulatory_reviews(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  code  TEXT NOT NULL CHECK ((length(code) > 0 AND length(code) <= 60)),
  rule_id  TEXT CHECK (rule_id IS NULL OR (length(rule_id) > 0 AND length(rule_id) <= 40)),
  rule_status  TEXT CHECK (rule_status IS NULL OR rule_status IN ('ACTIVE','SUSPENDED','PARTIALLY_SUSPENDED','JURISDICTION_OVERRIDE','PENDING_IMPLEMENTATION','UNDER_LEGAL_REVIEW','UNKNOWN')),
  regulator  TEXT CHECK (regulator IS NULL OR (length(regulator) > 0 AND length(regulator) <= 20)),
  jurisdiction  TEXT CHECK (jurisdiction IS NULL OR jurisdiction GLOB '[A-Z][A-Z][A-Z]'),
  policy_version_id  TEXT CHECK (policy_version_id IS NULL OR (length(policy_version_id) > 0 AND length(policy_version_id) <= 80)),
  facet  TEXT CHECK (facet IS NULL OR (length(facet) > 0 AND length(facet) <= 80)),
  member_association  TEXT CHECK (member_association IS NULL OR (length(member_association) > 0 AND length(member_association) <= 80)),
  state  TEXT CHECK (state IS NULL OR (length(state) > 0 AND length(state) <= 80)),
  agent_user_id  TEXT CHECK (agent_user_id IS NULL OR (length(agent_user_id) > 0 AND length(agent_user_id) <= 80)),
  party_role  TEXT CHECK (party_role IS NULL OR (length(party_role) > 0 AND length(party_role) <= 80)),
  consent_kind  TEXT CHECK (consent_kind IS NULL OR (length(consent_kind) > 0 AND length(consent_kind) <= 80)),
  detail_text  TEXT CHECK (detail_text IS NULL OR (length(detail_text) > 0 AND length(detail_text) <= 300)),
  reason_text  TEXT CHECK (reason_text IS NULL OR (length(reason_text) > 0 AND length(reason_text) <= 80)),
  override_rule_id  TEXT CHECK (override_rule_id IS NULL OR (length(override_rule_id) > 0 AND length(override_rule_id) <= 80)),
  kind_text  TEXT CHECK (kind_text IS NULL OR (length(kind_text) > 0 AND length(kind_text) <= 80)),
  via_connected_agent  INTEGER CHECK (via_connected_agent IS NULL OR via_connected_agent = 1),
  has_party_roles  INTEGER NOT NULL DEFAULT 0 CHECK (has_party_roles IN (0,1)),
  has_jurisdictions  INTEGER NOT NULL DEFAULT 0 CHECK (has_jurisdictions IN (0,1)),
  PRIMARY KEY (review_id, ord)
) STRICT;
CREATE TABLE regulatory_review_reason_items (
  review_id  TEXT NOT NULL,
  reason_ord  INTEGER NOT NULL,
  list  TEXT NOT NULL CHECK (list IN ('partyRoles','jurisdictions')),
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  value  TEXT NOT NULL CHECK (length(value) > 0 AND length(value) <= 80),
  PRIMARY KEY (review_id, reason_ord, list, ord),
  FOREIGN KEY (review_id, reason_ord) REFERENCES regulatory_review_reasons(review_id, ord) ON DELETE CASCADE
) STRICT;
CREATE TABLE regulatory_review_policy_versions (
  review_id  TEXT NOT NULL REFERENCES regulatory_reviews(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  PRIMARY KEY (review_id, ord),
  UNIQUE (review_id, policy_version_id)
) STRICT;
CREATE TABLE regulatory_review_evidence_refs (
  review_id  TEXT NOT NULL REFERENCES regulatory_reviews(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 10),
  ref  TEXT NOT NULL CHECK ((length(ref) > 0 AND length(ref) <= 200)),
  PRIMARY KEY (review_id, ord)
) STRICT;
CREATE TABLE regulatory_review_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  review_id  TEXT NOT NULL REFERENCES regulatory_reviews(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','player','club_user','ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  action  TEXT NOT NULL CHECK (action IN ('regulatory_review_requested','regulatory_review_started','regulatory_review_resolved','regulatory_review_cancelled','regulatory_review_superseded')),
  detail_rev  INTEGER,
  detail_review_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  detail_prior_status  TEXT CHECK (detail_prior_status IS NULL OR detail_prior_status IN ('PENDING','IN_REVIEW','APPROVED','REJECTED','CANCELLED','SUPERSEDED')),
  UNIQUE (review_id, ord)
) STRICT;
CREATE TABLE compliance_context_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','player','club_user','ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  action  TEXT NOT NULL CHECK (action IN ('compliance_context_opened','compliance_context_party_added','compliance_context_party_removed','compliance_representation_declared','compliance_representation_verified','compliance_representation_withdrawn','compliance_context_evaluated','compliance_context_policy_changed','compliance_context_closed')),
  detail_party_role  TEXT CHECK (detail_party_role IS NULL OR detail_party_role IN ('individual','engaging_entity','releasing_entity')),
  detail_subject_kind  TEXT CHECK (detail_subject_kind IS NULL OR detail_subject_kind IN ('player','club')),
  detail_status  TEXT CHECK (detail_status IS NULL OR detail_status IN ('verified','pending_review','withdrawn')),
  detail_review_outcome  TEXT CHECK (detail_review_outcome IS NULL OR detail_review_outcome IN ('review_approved','review_rejected')),
  detail_evaluation_id  TEXT REFERENCES compliance_evaluations(id) ON DELETE RESTRICT,
  detail_review_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  detail_policy_version_id  TEXT REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  UNIQUE (context_id, ord)
) STRICT;
CREATE TABLE compliance_context_history_policy_versions (
  history_id  TEXT NOT NULL REFERENCES compliance_context_history(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  PRIMARY KEY (history_id, ord),
  UNIQUE (history_id, policy_version_id)
) STRICT;
CREATE TABLE regulatory_consents (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  kind  TEXT NOT NULL CHECK (kind IN ('dual_representation','agency_performance','guardian_approach','guardian_agreement','legal_advice_ack')),
  context_id  TEXT NOT NULL REFERENCES compliance_contexts(id) ON DELETE RESTRICT,
  agent_user_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  agency_org_id  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  subject_kind  TEXT NOT NULL CHECK (subject_kind IN ('player','club')),
  subject_id  TEXT NOT NULL CHECK ((length(subject_id) > 0 AND length(subject_id) <= 80)),
  status  TEXT NOT NULL CHECK (status IN ('requested','granted','declined')),
  requested_at  INTEGER NOT NULL,
  requested_by_kind  TEXT NOT NULL CHECK (requested_by_kind IN ('org','player','club_user','ts_reviewer','system')),
  requested_by_id  TEXT CHECK (requested_by_id IS NULL OR (length(requested_by_id) > 0 AND length(requested_by_id) <= 80)),
  requested_by_name  TEXT CHECK (requested_by_name IS NULL OR length(requested_by_name) <= 200),
  requested_by_role  TEXT CHECK (requested_by_role IS NULL OR length(requested_by_role) <= 60),
  granted_at  INTEGER,
  granted_by_kind  TEXT CHECK (granted_by_kind IS NULL OR granted_by_kind IN ('player','club_user')),
  granted_by_id  TEXT CHECK (granted_by_id IS NULL OR (length(granted_by_id) > 0 AND length(granted_by_id) <= 80)),
  granted_by_name  TEXT CHECK (granted_by_name IS NULL OR length(granted_by_name) <= 200),
  granted_by_org_id  TEXT CHECK (granted_by_org_id IS NULL OR (length(granted_by_org_id) > 0 AND length(granted_by_org_id) <= 80)),
  granted_by_signatory  INTEGER CHECK (granted_by_signatory IS NULL OR granted_by_signatory = 1),
  declined_at  INTEGER,
  declined_by_kind  TEXT CHECK (declined_by_kind IS NULL OR declined_by_kind IN ('player','club_user')),
  declined_by_id  TEXT CHECK (declined_by_id IS NULL OR (length(declined_by_id) > 0 AND length(declined_by_id) <= 80)),
  declined_by_name  TEXT CHECK (declined_by_name IS NULL OR length(declined_by_name) <= 200),
  declined_by_org_id  TEXT CHECK (declined_by_org_id IS NULL OR (length(declined_by_org_id) > 0 AND length(declined_by_org_id) <= 80)),
  full_particulars_provided  INTEGER NOT NULL CHECK (full_particulars_provided IN (0,1)),
  legal_advice_offered  INTEGER NOT NULL CHECK (legal_advice_offered IN (0,1)),
  proposed_fee_disclosed  INTEGER NOT NULL CHECK (proposed_fee_disclosed IN (0,1)),
  acknowledged_at  INTEGER,
  request_key  TEXT CHECK (request_key IS NULL OR (length(request_key) > 0 AND length(request_key) <= 64)),
  request_fp  TEXT CHECK ((request_fp IS NULL OR length(request_fp) <= 4000) AND ((request_key IS NULL) = (request_fp IS NULL))),
  grant_key  TEXT CHECK (grant_key IS NULL OR (length(grant_key) > 0 AND length(grant_key) <= 64)),
  grant_fp  TEXT CHECK ((grant_fp IS NULL OR length(grant_fp) <= 4000) AND ((grant_key IS NULL) = (grant_fp IS NULL))),
  decline_key  TEXT CHECK (decline_key IS NULL OR (length(decline_key) > 0 AND length(decline_key) <= 64)),
  decline_fp  TEXT CHECK ((decline_fp IS NULL OR length(decline_fp) <= 4000) AND ((decline_key IS NULL) = (decline_fp IS NULL))),
  revoke_key  TEXT CHECK (revoke_key IS NULL OR (length(revoke_key) > 0 AND length(revoke_key) <= 64)),
  revoke_fp  TEXT CHECK ((revoke_fp IS NULL OR length(revoke_fp) <= 4000) AND ((revoke_key IS NULL) = (revoke_fp IS NULL))),
  rev  INTEGER NOT NULL CHECK (rev >= 1),
  rev_at  INTEGER,
  rev_by_id  TEXT CHECK (rev_by_id IS NULL OR (length(rev_by_id) > 0 AND length(rev_by_id) <= 80)),
  rev_by_name  TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  CHECK ((status = 'granted') = (granted_at IS NOT NULL AND granted_by_kind IS NOT NULL)),
  CHECK ((status = 'declined') = (declined_at IS NOT NULL AND declined_by_kind IS NOT NULL)),
  CHECK ((status = 'granted') = (acknowledged_at IS NOT NULL))
) STRICT;
CREATE TABLE regulatory_consent_regarding (
  consent_id  TEXT NOT NULL REFERENCES regulatory_consents(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  PRIMARY KEY (consent_id, ord),
  UNIQUE (consent_id, party_role)
) STRICT;
CREATE TABLE regulatory_consent_policy_versions (
  consent_id  TEXT NOT NULL REFERENCES regulatory_consents(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  PRIMARY KEY (consent_id, ord),
  UNIQUE (consent_id, policy_version_id)
) STRICT;
CREATE TABLE regulatory_consent_rule_ids (
  consent_id  TEXT NOT NULL REFERENCES regulatory_consents(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  rule_id  TEXT NOT NULL CHECK (length(rule_id) > 0 AND length(rule_id) <= 40),
  PRIMARY KEY (consent_id, ord),
  UNIQUE (consent_id, rule_id)
) STRICT;
CREATE TABLE regulatory_consent_revocations (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  consent_id  TEXT NOT NULL UNIQUE REFERENCES regulatory_consents(id) ON DELETE CASCADE,
  revoked_at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('player','club_user')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80))
) STRICT;
CREATE TABLE regulatory_consent_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  consent_id  TEXT NOT NULL REFERENCES regulatory_consents(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','player','club_user','ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  action  TEXT NOT NULL CHECK (action IN ('regulatory_consent_requested','regulatory_consent_granted','regulatory_consent_declined','regulatory_consent_revoked')),
  UNIQUE (consent_id, ord)
) STRICT;
CREATE TABLE agent_transactions (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  agency_org_id  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  agent_user_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  type  TEXT NOT NULL CHECK (type IN ('employment_contract','transfer','loan','other_services')),
  status  TEXT NOT NULL CHECK (status IN ('DRAFT','PARTIES_CONFIRMED','COMPLIANCE_PENDING','COMPLIANCE_BLOCKED','READY','ACTIVE','ON_HOLD','CANCELLED','CLOSED','ARCHIVED')),
  context_id  TEXT NOT NULL UNIQUE REFERENCES compliance_contexts(id) ON DELETE RESTRICT,
  compliance_evaluation_id  TEXT,
  compliance_gate  TEXT CHECK (compliance_gate IS NULL OR compliance_gate IN ('FACET_NOT_VERIFIED','JURISDICTION_UNSUPPORTED')),
  compliance_evaluated_at  INTEGER,
  compliance_pending_reason  TEXT CHECK (compliance_pending_reason IS NULL OR compliance_pending_reason IN ('CONSENT_REQUIRED','MANUAL_REVIEW','INSUFFICIENT_DATA','PROVIDER_UNAVAILABLE','JURISDICTION_UNSUPPORTED','FACET_NOT_VERIFIED','PARTIES_NOT_CONFIRMED','REPRESENTATION_MISSING')),
  compliance_verification_freshness  TEXT CHECK (compliance_verification_freshness IS NULL OR compliance_verification_freshness IN ('UNVERIFIED','PENDING','VERIFIED','STALE','INACTIVE','MANUAL_REVIEW_REQUIRED')),
  compliance_party_revision  TEXT CHECK (compliance_party_revision IS NULL OR (length(compliance_party_revision) = 64 AND compliance_party_revision NOT GLOB '*[^0-9a-f]*')),
  re_evaluation_pending  INTEGER NOT NULL CHECK (re_evaluation_pending IN (0,1)),
  link_trial_id  TEXT CHECK (link_trial_id IS NULL OR (length(link_trial_id) > 0 AND length(link_trial_id) <= 80)),
  link_opportunity_id  TEXT CHECK (link_opportunity_id IS NULL OR (length(link_opportunity_id) > 0 AND length(link_opportunity_id) <= 80)),
  link_recruitment_case_id  TEXT REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  hold_reason_code  TEXT CHECK (hold_reason_code IS NULL OR hold_reason_code IN ('awaiting_party_decision','awaiting_document','awaiting_regulatory_answer','window_closed','party_request','other')),
  hold_reason  TEXT CHECK (hold_reason IS NULL OR (length(hold_reason) > 0 AND length(hold_reason) <= 400)),
  held_at  INTEGER,
  cancel_reason_code  TEXT CHECK (cancel_reason_code IS NULL OR cancel_reason_code IN ('party_withdrew','terms_not_agreed','window_closed','compliance_not_cleared','duplicate','other')),
  cancelled_at  INTEGER,
  close_reason_code  TEXT CHECK (close_reason_code IS NULL OR close_reason_code IN ('process_concluded','proceeded_outside_scoutbox','superseded','other')),
  closed_at  INTEGER,
  archived_at  INTEGER,
  initiated_by_name  TEXT CHECK (initiated_by_name IS NULL OR length(initiated_by_name) <= 200),
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL,
  create_key  TEXT CHECK (create_key IS NULL OR (length(create_key) > 0 AND length(create_key) <= 64)),
  create_fp  TEXT CHECK ((create_fp IS NULL OR length(create_fp) <= 4000) AND ((create_key IS NULL) = (create_fp IS NULL))),
  rev  INTEGER NOT NULL CHECK (rev >= 1),
  rev_at  INTEGER,
  rev_by_label  TEXT CHECK (rev_by_label IS NULL OR length(rev_by_label) <= 200),
  CHECK (compliance_evaluation_id IS NULL OR compliance_gate IS NULL),
  CHECK ((compliance_evaluated_at IS NULL) = (compliance_evaluation_id IS NULL AND compliance_gate IS NULL)),
  CHECK ((compliance_evaluated_at IS NULL) = (compliance_party_revision IS NULL)),
  CHECK (compliance_gate IS NULL OR compliance_pending_reason = compliance_gate),
  CHECK (compliance_evaluated_at IS NOT NULL OR (compliance_pending_reason IS NULL AND compliance_verification_freshness IS NULL)),
  CHECK ((hold_reason_code IS NULL) = (held_at IS NULL) AND (hold_reason IS NULL OR hold_reason_code IS NOT NULL)),
  CHECK ((cancel_reason_code IS NULL) = (cancelled_at IS NULL)),
  CHECK ((close_reason_code IS NULL) = (closed_at IS NULL)),
  FOREIGN KEY (compliance_evaluation_id, context_id) REFERENCES compliance_evaluations(id, context_id) ON DELETE RESTRICT,
  UNIQUE (id, type),
  UNIQUE (id, agency_org_id)
) STRICT;
CREATE TABLE agent_transaction_jurisdictions (
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 10),
  member_association  TEXT NOT NULL CHECK (member_association GLOB '[A-Z][A-Z][A-Z]'),
  PRIMARY KEY (transaction_id, ord),
  UNIQUE (transaction_id, member_association)
) STRICT;
CREATE TABLE transaction_parties (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL,
  transaction_type  TEXT NOT NULL CHECK (transaction_type IN ('employment_contract','transfer','loan','other_services')),
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 12),
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  subject_kind  TEXT NOT NULL CHECK (subject_kind IN ('player','club')),
  subject_id  TEXT NOT NULL CHECK ((length(subject_id) > 0 AND length(subject_id) <= 80)),
  added_at  INTEGER NOT NULL,
  added_by_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  added_by_name  TEXT CHECK (added_by_name IS NULL OR length(added_by_name) <= 200),
  removed  INTEGER NOT NULL CHECK (removed IN (0,1)),
  removed_at  INTEGER,
  confirmed_at  INTEGER,
  confirmed_by_kind  TEXT CHECK (confirmed_by_kind IS NULL OR confirmed_by_kind IN ('player','club_user')),
  confirmed_by_id  TEXT CHECK (confirmed_by_id IS NULL OR (length(confirmed_by_id) > 0 AND length(confirmed_by_id) <= 80)),
  confirmed_by_name  TEXT CHECK (confirmed_by_name IS NULL OR length(confirmed_by_name) <= 200),
  confirmed_by_org_id  TEXT CHECK (confirmed_by_org_id IS NULL OR (length(confirmed_by_org_id) > 0 AND length(confirmed_by_org_id) <= 80)),
  subject_removed_at  INTEGER,
  UNIQUE (transaction_id, ord),
  CHECK (subject_kind <> 'player' OR party_role = 'individual'),
  CHECK (subject_kind <> 'club' OR party_role <> 'individual'),
  CHECK ((removed = 1) = (removed_at IS NOT NULL)),
  CHECK ((confirmed_at IS NULL) = (confirmed_by_kind IS NULL)),
  CHECK ((confirmed_by_kind = 'club_user') = (confirmed_by_org_id IS NOT NULL)),
  CHECK (subject_removed_at IS NULL OR removed = 1),
  CHECK (party_role <> 'releasing_entity' OR transaction_type IN ('transfer','loan')),
  FOREIGN KEY (transaction_id, transaction_type) REFERENCES agent_transactions(id, type) ON DELETE CASCADE
) STRICT;
CREATE TABLE transaction_notes (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 200),
  visibility  TEXT NOT NULL CHECK (visibility IN ('AGENT_PRIVATE','PLAYER_PRIVATE','ENGAGING_CLUB_PRIVATE','RELEASING_CLUB_PRIVATE','PLAYER_AGENT_SHARED','ENGAGING_AGENT_SHARED','RELEASING_AGENT_SHARED','ALL_TRANSACTION_PARTIES')),
  text  TEXT NOT NULL CHECK ((length(text) > 0 AND length(text) <= 2000)),
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','club_user')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  at  INTEGER NOT NULL,
  UNIQUE (transaction_id, ord),
  CHECK ((by_kind = 'club_user') = (by_org_id IS NOT NULL))
) STRICT;
CREATE TABLE transaction_linked_threads (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0 AND ord < 20),
  channel_id  TEXT NOT NULL CHECK ((length(channel_id) > 0 AND length(channel_id) <= 80)),
  linked_by_id  TEXT CHECK (linked_by_id IS NULL OR (length(linked_by_id) > 0 AND length(linked_by_id) <= 80)),
  linked_by_name  TEXT CHECK (linked_by_name IS NULL OR length(linked_by_name) <= 200),
  linked_by_org_id  TEXT NOT NULL CHECK ((length(linked_by_org_id) > 0 AND length(linked_by_org_id) <= 80)),
  linked_at  INTEGER NOT NULL,
  UNIQUE (transaction_id, ord),
  UNIQUE (transaction_id, channel_id)
) STRICT;
CREATE TABLE transaction_terms_versions (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE CASCADE,
  version  INTEGER NOT NULL CHECK (version >= 1 AND version <= 50),
  recorded_at  INTEGER NOT NULL,
  recorded_by_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  recorded_by_name  TEXT CHECK (recorded_by_name IS NULL OR length(recorded_by_name) <= 200),
  recorded_for  TEXT NOT NULL CHECK (recorded_for IN ('individual','engaging_entity','releasing_entity')),
  visibility  TEXT NOT NULL CHECK (visibility IN ('AGENT_PRIVATE','PLAYER_PRIVATE','ENGAGING_CLUB_PRIVATE','RELEASING_CLUB_PRIVATE','PLAYER_AGENT_SHARED','ENGAGING_AGENT_SHARED','RELEASING_AGENT_SHARED','ALL_TRANSACTION_PARTIES')),
  summary  TEXT NOT NULL CHECK ((length(summary) > 0 AND length(summary) <= 2000)),
  UNIQUE (transaction_id, version)
) STRICT;
CREATE TABLE transaction_keys (
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE CASCADE,
  action  TEXT NOT NULL CHECK (action IN ('party','status')),
  key  TEXT NOT NULL CHECK ((length(key) > 0 AND length(key) <= 64)),
  fp  TEXT NOT NULL CHECK (length(fp) <= 4000),
  PRIMARY KEY (transaction_id, action, key)
) STRICT;
CREATE TABLE transaction_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','player','club_user','ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  action  TEXT NOT NULL CHECK (action IN ('transaction_created','transaction_party_added','transaction_party_removed','transaction_party_confirmed','transaction_status_changed','transaction_held','transaction_cancelled','transaction_closed','transaction_archived','transaction_compliance_evaluated','transaction_compliance_stale','transaction_document_added','transaction_document_superseded','transaction_message_linked','transaction_terms_recorded','transaction_representation_attached','transaction_representation_withdrawn','transaction_note_added','transaction_subject_tombstoned')),
  detail_from  TEXT CHECK (detail_from IS NULL OR detail_from IN ('DRAFT','PARTIES_CONFIRMED','COMPLIANCE_PENDING','COMPLIANCE_BLOCKED','READY','ACTIVE','ON_HOLD','CANCELLED','CLOSED','ARCHIVED')),
  detail_to  TEXT CHECK (detail_to IS NULL OR detail_to IN ('DRAFT','PARTIES_CONFIRMED','COMPLIANCE_PENDING','COMPLIANCE_BLOCKED','READY','ACTIVE','ON_HOLD','CANCELLED','CLOSED','ARCHIVED')),
  detail_party_role  TEXT CHECK (detail_party_role IS NULL OR detail_party_role IN ('individual','engaging_entity','releasing_entity')),
  detail_subject_kind  TEXT CHECK (detail_subject_kind IS NULL OR detail_subject_kind IN ('player','club')),
  detail_status  TEXT CHECK (detail_status IS NULL OR detail_status IN ('verified','pending_review','withdrawn')),
  detail_outcome  TEXT CHECK (detail_outcome IS NULL OR detail_outcome IN ('CLEAR','PERMITTED_DUAL_REPRESENTATION_CONSENT_REQUIRED','PROHIBITED_CONFLICT','MANUAL_REGULATORY_REVIEW_REQUIRED','INSUFFICIENT_DATA')),
  detail_pending_reason  TEXT CHECK (detail_pending_reason IS NULL OR detail_pending_reason IN ('CONSENT_REQUIRED','MANUAL_REVIEW','INSUFFICIENT_DATA','PROVIDER_UNAVAILABLE','JURISDICTION_UNSUPPORTED','FACET_NOT_VERIFIED','PARTIES_NOT_CONFIRMED','REPRESENTATION_MISSING')),
  detail_document_type  TEXT CHECK (detail_document_type IS NULL OR detail_document_type IN ('representation_agreement_reference','compliance_consent_reference','guardian_evidence','mandate','term_sheet_draft','employment_contract_draft','club_document','regulatory_evidence','correspondence_attachment')),
  detail_visibility  TEXT CHECK (detail_visibility IS NULL OR detail_visibility IN ('AGENT_PRIVATE','PLAYER_PRIVATE','ENGAGING_CLUB_PRIVATE','RELEASING_CLUB_PRIVATE','PLAYER_AGENT_SHARED','ENGAGING_AGENT_SHARED','RELEASING_AGENT_SHARED','ALL_TRANSACTION_PARTIES','T_AND_S_ONLY')),
  detail_staleness  TEXT CHECK (detail_staleness IS NULL OR detail_staleness IN ('NO_SNAPSHOT','INPUTS_CHANGED','POLICY_CHANGED','EXPIRED')),
  detail_reason_code  TEXT CHECK (detail_reason_code IS NULL OR detail_reason_code IN ('awaiting_party_decision','awaiting_document','awaiting_regulatory_answer','window_closed','party_request','other','party_withdrew','terms_not_agreed','compliance_not_cleared','duplicate','process_concluded','proceeded_outside_scoutbox','superseded')),
  detail_version  INTEGER CHECK (detail_version IS NULL OR detail_version >= 0),
  detail_count  INTEGER CHECK (detail_count IS NULL OR detail_count >= 0),
  has_reason_codes  INTEGER NOT NULL CHECK (has_reason_codes IN (0,1)),
  has_policy_versions  INTEGER NOT NULL CHECK (has_policy_versions IN (0,1)),
  UNIQUE (transaction_id, ord)
) STRICT;
CREATE TABLE transaction_history_reason_codes (
  history_id  TEXT NOT NULL REFERENCES transaction_history(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  code  TEXT NOT NULL CHECK (length(code) > 0 AND length(code) <= 60),
  PRIMARY KEY (history_id, ord),
  UNIQUE (history_id, code)
) STRICT;
CREATE TABLE transaction_history_policy_versions (
  history_id  TEXT NOT NULL REFERENCES transaction_history(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  PRIMARY KEY (history_id, ord),
  UNIQUE (history_id, policy_version_id)
) STRICT;
CREATE TABLE transaction_representations (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL,
  agency_org_id  TEXT NOT NULL REFERENCES orgs(id) ON DELETE RESTRICT,
  agent_user_id  TEXT NOT NULL REFERENCES org_users(id) ON DELETE RESTRICT,
  party_role  TEXT NOT NULL CHECK (party_role IN ('individual','engaging_entity','releasing_entity')),
  agreement_id  TEXT REFERENCES representation_agreements(id) ON DELETE RESTRICT,
  declared_only  INTEGER NOT NULL CHECK (declared_only IN (0,1)),
  jurisdiction  TEXT CHECK (jurisdiction IS NULL OR jurisdiction GLOB '[A-Z][A-Z][A-Z]'),
  status  TEXT NOT NULL CHECK (status IN ('verified','pending_review','withdrawn')),
  review_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  created_at  INTEGER NOT NULL,
  verified_at  INTEGER,
  verified_by_review_id  TEXT REFERENCES regulatory_reviews(id) ON DELETE RESTRICT,
  first_act_at  INTEGER,
  withdrawn_at  INTEGER,
  withdrawn_reason  TEXT CHECK (withdrawn_reason IS NULL OR withdrawn_reason IN ('party_removed','agent_withdrew','subject_removed','review_rejected')),
  attach_key  TEXT CHECK (attach_key IS NULL OR (length(attach_key) > 0 AND length(attach_key) <= 64)),
  attach_fp  TEXT CHECK ((attach_fp IS NULL OR length(attach_fp) <= 4000) AND ((attach_key IS NULL) = (attach_fp IS NULL))),
  rev  INTEGER NOT NULL CHECK (rev >= 1),
  rev_at  INTEGER,
  rev_by_id  TEXT CHECK (rev_by_id IS NULL OR (length(rev_by_id) > 0 AND length(rev_by_id) <= 80)),
  rev_by_name  TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  CHECK ((status = 'withdrawn') = (withdrawn_at IS NOT NULL)),
  CHECK ((withdrawn_at IS NULL) = (withdrawn_reason IS NULL)),
  CHECK (status <> 'pending_review' OR (declared_only = 1 AND review_id IS NOT NULL)),
  CHECK (declared_only = 1 OR agreement_id IS NOT NULL OR verified_by_review_id IS NOT NULL),
  FOREIGN KEY (transaction_id, agency_org_id) REFERENCES agent_transactions(id, agency_org_id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE transaction_representation_scopes (
  representation_id  TEXT NOT NULL REFERENCES transaction_representations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  scope  TEXT NOT NULL CHECK (scope IN ('employment','transfer','commercial','other_services')),
  PRIMARY KEY (representation_id, ord),
  UNIQUE (representation_id, scope)
) STRICT;
CREATE TABLE transaction_representation_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  representation_id  TEXT NOT NULL REFERENCES transaction_representations(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','player','club_user','ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  action  TEXT NOT NULL CHECK (action IN ('transaction_representation_attached','transaction_representation_withdrawn')),
  detail_party_role  TEXT CHECK (detail_party_role IS NULL OR detail_party_role IN ('individual','engaging_entity','releasing_entity')),
  detail_status  TEXT CHECK (detail_status IS NULL OR detail_status IN ('verified','pending_review','withdrawn')),
  has_policy_versions  INTEGER NOT NULL CHECK (has_policy_versions IN (0,1)),
  UNIQUE (representation_id, ord)
) STRICT;
CREATE TABLE transaction_representation_history_policy_versions (
  history_id  TEXT NOT NULL REFERENCES transaction_representation_history(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  policy_version_id  TEXT NOT NULL REFERENCES jurisdiction_policies(id) ON DELETE RESTRICT,
  PRIMARY KEY (history_id, ord),
  UNIQUE (history_id, policy_version_id)
) STRICT;
CREATE TABLE transaction_documents (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  transaction_id  TEXT NOT NULL REFERENCES agent_transactions(id) ON DELETE RESTRICT,
  document_type  TEXT NOT NULL CHECK (document_type IN ('representation_agreement_reference','compliance_consent_reference','guardian_evidence','mandate','term_sheet_draft','employment_contract_draft','club_document','regulatory_evidence','correspondence_attachment')),
  visibility  TEXT NOT NULL CHECK (visibility IN ('AGENT_PRIVATE','PLAYER_PRIVATE','ENGAGING_CLUB_PRIVATE','RELEASING_CLUB_PRIVATE','PLAYER_AGENT_SHARED','ENGAGING_AGENT_SHARED','RELEASING_AGENT_SHARED','ALL_TRANSACTION_PARTIES','T_AND_S_ONLY')),
  label  TEXT NOT NULL CHECK ((length(label) > 0 AND length(label) <= 120)),
  version  INTEGER NOT NULL CHECK (version >= 1),
  owner_kind  TEXT NOT NULL CHECK (owner_kind IN ('agent','club','player')),
  owner_id  TEXT CHECK (owner_id IS NULL OR (length(owner_id) > 0 AND length(owner_id) <= 80)),
  owner_party_role  TEXT CHECK (owner_party_role IS NULL OR owner_party_role IN ('individual','engaging_entity','releasing_entity')),
  uploaded_by_kind  TEXT NOT NULL CHECK (uploaded_by_kind IN ('org','club_user','player')),
  uploaded_by_id  TEXT CHECK (uploaded_by_id IS NULL OR (length(uploaded_by_id) > 0 AND length(uploaded_by_id) <= 80)),
  uploaded_by_name  TEXT CHECK (uploaded_by_name IS NULL OR length(uploaded_by_name) <= 200),
  uploaded_by_org_id  TEXT CHECK (uploaded_by_org_id IS NULL OR (length(uploaded_by_org_id) > 0 AND length(uploaded_by_org_id) <= 80)),
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER,
  evidence_id  TEXT REFERENCES ver_evidence(id) ON DELETE RESTRICT,
  supersedes_id  TEXT,
  removed_at  INTEGER,
  add_key  TEXT CHECK (add_key IS NULL OR (length(add_key) > 0 AND length(add_key) <= 64)),
  add_fp  TEXT CHECK ((add_fp IS NULL OR length(add_fp) <= 4000) AND ((add_key IS NULL) = (add_fp IS NULL))),
  rev  INTEGER NOT NULL CHECK (rev >= 1),
  rev_at  INTEGER,
  rev_by_id  TEXT CHECK (rev_by_id IS NULL OR (length(rev_by_id) > 0 AND length(rev_by_id) <= 80)),
  rev_by_name  TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  CHECK ((owner_kind = 'agent') = (owner_party_role IS NULL)),
  CHECK ((uploaded_by_kind = 'club_user') = (uploaded_by_org_id IS NOT NULL)),
  CHECK ((version = 1) = (supersedes_id IS NULL)),
  UNIQUE (id, transaction_id),
  FOREIGN KEY (supersedes_id, transaction_id) REFERENCES transaction_documents(id, transaction_id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE transaction_document_history (
  id  TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  document_id  TEXT NOT NULL REFERENCES transaction_documents(id) ON DELETE CASCADE,
  ord  INTEGER NOT NULL CHECK (ord >= 0),
  at  INTEGER NOT NULL,
  by_kind  TEXT NOT NULL CHECK (by_kind IN ('org','player','club_user','ts_reviewer','system')),
  by_id  TEXT CHECK (by_id IS NULL OR (length(by_id) > 0 AND length(by_id) <= 80)),
  by_name  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  by_role  TEXT CHECK (by_role IS NULL OR length(by_role) <= 60),
  by_org_id  TEXT CHECK (by_org_id IS NULL OR (length(by_org_id) > 0 AND length(by_org_id) <= 80)),
  action  TEXT NOT NULL CHECK (action IN ('transaction_document_added','transaction_document_superseded')),
  UNIQUE (document_id, ord)
) STRICT;
CREATE TABLE dev_objectives (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  source_assessment_id                     TEXT NOT NULL CHECK (length(source_assessment_id) <= 80 AND length(source_assessment_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  reviewer_user_id                         TEXT NOT NULL CHECK (length(reviewer_user_id) <= 80 AND length(reviewer_user_id) > 0),
  reviewer_name                            TEXT CHECK (reviewer_name IS NULL OR length(reviewer_name) <= 200),
  reviewer_org_name                        TEXT CHECK (reviewer_org_name IS NULL OR length(reviewer_org_name) <= 200),
  review_at                                INTEGER,
  status                                   TEXT NOT NULL CHECK (status IN ('active')),
  created_by_kind                          TEXT NOT NULL CHECK (created_by_kind IN ('player','guardian')),
  created_by_id                            TEXT NOT NULL CHECK (length(created_by_id) <= 80 AND length(created_by_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (reviewer_user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE dev_objective_items (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  objective_id                             TEXT NOT NULL CHECK (length(objective_id) <= 80 AND length(objective_id) > 0),
  text                                     TEXT NOT NULL CHECK (length(text) <= 200 AND length(text) > 0),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 2),
  FOREIGN KEY (objective_id) REFERENCES dev_objectives(id) ON DELETE CASCADE,
  UNIQUE (objective_id, ord)
) STRICT;
CREATE TABLE dev_objective_item_exercises (
  item_id                                  TEXT NOT NULL CHECK (length(item_id) > 0 AND length(item_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 4),
  ref                                      TEXT NOT NULL CHECK (length(ref) > 0 AND length(ref) <= 200),
  FOREIGN KEY (item_id) REFERENCES dev_objective_items(id) ON DELETE CASCADE,
  PRIMARY KEY (item_id, ord)
) STRICT;
CREATE TABLE dev_objective_item_evidence (
  item_id                                  TEXT NOT NULL CHECK (length(item_id) > 0 AND length(item_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 50),
  evidence_id                              TEXT NOT NULL CHECK (length(evidence_id) > 0 AND length(evidence_id) <= 80),
  FOREIGN KEY (item_id) REFERENCES dev_objective_items(id) ON DELETE CASCADE,
  PRIMARY KEY (item_id, ord),
  UNIQUE (item_id, evidence_id)
) STRICT;
CREATE TABLE dev_objective_progress (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  objective_id                             TEXT NOT NULL CHECK (length(objective_id) <= 80 AND length(objective_id) > 0),
  at                                       INTEGER NOT NULL,
  item_id                                  TEXT CHECK (item_id IS NULL OR length(item_id) <= 80 AND length(item_id) > 0),
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 300),
  evidence_id                              TEXT CHECK (evidence_id IS NULL OR length(evidence_id) <= 80 AND length(evidence_id) > 0),
  FOREIGN KEY (objective_id) REFERENCES dev_objectives(id) ON DELETE CASCADE,
  FOREIGN KEY (item_id) REFERENCES dev_objective_items(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE dev_objective_shares (
  objective_id                             TEXT NOT NULL CHECK (length(objective_id) > 0 AND length(objective_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) > 0 AND length(org_id) <= 80),
  FOREIGN KEY (objective_id) REFERENCES dev_objectives(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (objective_id, org_id),
  UNIQUE (objective_id, ord)
) STRICT;
CREATE TABLE dev_objective_reassessments (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  objective_id                             TEXT NOT NULL CHECK (length(objective_id) <= 80 AND length(objective_id) > 0),
  requested_by_kind                        TEXT NOT NULL CHECK (requested_by_kind IN ('player','guardian')),
  requested_by_id                          TEXT NOT NULL CHECK (length(requested_by_id) <= 80 AND length(requested_by_id) > 0),
  requested_by_name                        TEXT CHECK (requested_by_name IS NULL OR length(requested_by_name) <= 200),
  requested_at                             INTEGER NOT NULL,
  status                                   TEXT NOT NULL CHECK (status IN ('requested','completed')),
  outcome_note                             TEXT CHECK (outcome_note IS NULL OR length(outcome_note) <= 500 AND length(outcome_note) > 0),
  outcome_by_user_id                       TEXT CHECK (outcome_by_user_id IS NULL OR length(outcome_by_user_id) <= 80 AND length(outcome_by_user_id) > 0),
  outcome_by_name                          TEXT CHECK (outcome_by_name IS NULL OR length(outcome_by_name) <= 200),
  outcome_at                               INTEGER,
  FOREIGN KEY (objective_id) REFERENCES dev_objectives(id) ON DELETE CASCADE,
  FOREIGN KEY (outcome_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK ((status = 'completed') = (outcome_at IS NOT NULL)),
  CHECK ((outcome_at IS NULL) = (outcome_note IS NULL) AND (outcome_at IS NULL) = (outcome_by_user_id IS NULL))
) STRICT;
CREATE TABLE dev_objective_reassessment_evidence (
  reassessment_id                          TEXT NOT NULL CHECK (length(reassessment_id) > 0 AND length(reassessment_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 50),
  evidence_id                              TEXT NOT NULL CHECK (length(evidence_id) > 0 AND length(evidence_id) <= 80),
  FOREIGN KEY (reassessment_id) REFERENCES dev_objective_reassessments(id) ON DELETE CASCADE,
  PRIMARY KEY (reassessment_id, ord),
  UNIQUE (reassessment_id, evidence_id)
) STRICT;
CREATE TABLE drill_guidance (
  drill_id                                 TEXT NOT NULL CHECK (length(drill_id) <= 80 AND length(drill_id) > 0),
  reviewer                                 TEXT NOT NULL CHECK (length(reviewer) <= 60 AND length(reviewer) > 0),
  reviewed_at                              INTEGER NOT NULL,
  PRIMARY KEY (drill_id)
) STRICT;
CREATE TABLE development_plans (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  owner_kind                               TEXT NOT NULL CHECK (owner_kind IN ('player','org')),
  owner_org_id                             TEXT CHECK (owner_org_id IS NULL OR length(owner_org_id) <= 80 AND length(owner_org_id) > 0),
  owner_org_name                           TEXT CHECK (owner_org_name IS NULL OR length(owner_org_name) <= 200),
  created_by_kind                          TEXT NOT NULL CHECK (created_by_kind IN ('player','guardian','org')),
  created_by_id                            TEXT NOT NULL CHECK (length(created_by_id) <= 80 AND length(created_by_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('draft','active','paused','completed','archived')),
  visibility                               TEXT NOT NULL CHECK (visibility IN ('private','player_guardian','shared_with_org','org_private')),
  start_at                                 INTEGER NOT NULL,
  next_review_at                           INTEGER,
  end_at                                   INTEGER,
  template_id                              TEXT CHECK (template_id IS NULL OR template_id IN ('technical_development','positional_development','trial_follow_up')),
  origin_objective_id                      TEXT CHECK (origin_objective_id IS NULL OR length(origin_objective_id) <= 80 AND length(origin_objective_id) > 0),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_user_id                           TEXT CHECK (rev_by_user_id IS NULL OR length(rev_by_user_id) <= 80 AND length(rev_by_user_id) > 0),
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  completed_at                             INTEGER,
  archived_at                              INTEGER,
  FOREIGN KEY (owner_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (origin_objective_id) REFERENCES dev_objectives(id) ON DELETE RESTRICT,
  CHECK ((owner_kind = 'org') = (owner_org_id IS NOT NULL)),
  CHECK (owner_kind <> 'player' OR visibility IN ('private','player_guardian','shared_with_org')),
  CHECK (owner_kind <> 'org' OR visibility IN ('org_private','player_guardian')),
  CHECK (status <> 'completed' OR completed_at IS NOT NULL),
  CHECK (status <> 'archived' OR archived_at IS NOT NULL)
) STRICT;
CREATE TABLE development_plan_shares (
  plan_id                                  TEXT NOT NULL CHECK (length(plan_id) > 0 AND length(plan_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) > 0 AND length(org_id) <= 80),
  FOREIGN KEY (plan_id) REFERENCES development_plans(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (plan_id, org_id),
  UNIQUE (plan_id, ord)
) STRICT;
CREATE TABLE development_goals (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  plan_id                                  TEXT NOT NULL CHECK (length(plan_id) <= 80 AND length(plan_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  description                              TEXT CHECK (description IS NULL OR length(description) <= 1000),
  category                                 TEXT NOT NULL CHECK (category IN ('technical','tactical','physical','psychological','match_understanding','position_specific','other')),
  status                                   TEXT NOT NULL CHECK (status IN ('not_started','in_progress','blocked','achieved','stopped')),
  block_reason                             TEXT CHECK (block_reason IS NULL OR block_reason IN ('waiting_for_assessment','schedule','facility','coach_review','other')),
  block_note                               TEXT CHECK (block_note IS NULL OR length(block_note) <= 300),
  target_at                                INTEGER,
  target_source_type                       TEXT CHECK (target_source_type IS NULL OR target_source_type IN ('combine_attempt')),
  target_protocol_id                       TEXT CHECK (target_protocol_id IS NULL OR length(target_protocol_id) <= 80 AND length(target_protocol_id) > 0),
  target_protocol_version                  INTEGER,
  target_metric_type                       TEXT CHECK (target_metric_type IS NULL OR target_metric_type IN ('count','time','distance','duration','set','percentage')),
  target_metric_unit                       TEXT CHECK (target_metric_unit IS NULL OR length(target_metric_unit) <= 40 AND length(target_metric_unit) > 0),
  target_operator                          TEXT CHECK (target_operator IS NULL OR target_operator IN ('gte','gt','lte','lt','eq')),
  target_value                             REAL,
  target_protocol_title                    TEXT CHECK (target_protocol_title IS NULL OR length(target_protocol_title) <= 120 AND length(target_protocol_title) > 0),
  target_direction                         TEXT CHECK (target_direction IS NULL OR target_direction IN ('higher','lower')),
  target_precision                         TEXT CHECK (target_precision IS NULL OR target_precision IN ('integer','tenths','hundredths','centimetres')),
  origin_objective_id                      TEXT CHECK (origin_objective_id IS NULL OR length(origin_objective_id) <= 80 AND length(origin_objective_id) > 0),
  created_by_kind                          TEXT NOT NULL CHECK (created_by_kind IN ('player','guardian','org')),
  created_by_id                            TEXT NOT NULL CHECK (length(created_by_id) <= 80 AND length(created_by_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  completed_at                             INTEGER,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_user_id                           TEXT CHECK (rev_by_user_id IS NULL OR length(rev_by_user_id) <= 80 AND length(rev_by_user_id) > 0),
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  FOREIGN KEY (plan_id) REFERENCES development_plans(id) ON DELETE RESTRICT,
  FOREIGN KEY (origin_objective_id) REFERENCES dev_objectives(id) ON DELETE RESTRICT,
  CHECK ((status = 'blocked') = (block_reason IS NOT NULL)),
  CHECK (status = 'blocked' OR block_note IS NULL),
  CHECK ((status = 'achieved') = (completed_at IS NOT NULL))
) STRICT;
CREATE TABLE development_actions (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  plan_id                                  TEXT NOT NULL CHECK (length(plan_id) <= 80 AND length(plan_id) > 0),
  goal_id                                  TEXT NOT NULL CHECK (length(goal_id) <= 80 AND length(goal_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  type                                     TEXT NOT NULL CHECK (type IN ('training','assessment','video_review','match_objective','coach_review','combine','box_cam','evidence_request','custom')),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  due_at                                   INTEGER,
  assignee_kind                            TEXT CHECK (assignee_kind IS NULL OR assignee_kind IN ('player','guardian','org_user')),
  assignee_id                              TEXT CHECK (assignee_id IS NULL OR length(assignee_id) <= 80 AND length(assignee_id) > 0),
  assignee_name                            TEXT CHECK (assignee_name IS NULL OR length(assignee_name) <= 200),
  status                                   TEXT NOT NULL CHECK (status IN ('todo','in_progress','done','blocked','cancelled')),
  created_by_kind                          TEXT NOT NULL CHECK (created_by_kind IN ('player','guardian','org')),
  created_by_id                            TEXT NOT NULL CHECK (length(created_by_id) <= 80 AND length(created_by_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  completed_at                             INTEGER,
  FOREIGN KEY (plan_id) REFERENCES development_plans(id) ON DELETE RESTRICT,
  FOREIGN KEY (goal_id) REFERENCES development_goals(id) ON DELETE RESTRICT,
  CHECK ((status = 'done') = (completed_at IS NOT NULL))
) STRICT;
CREATE TABLE development_evidence_links (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  plan_id                                  TEXT NOT NULL CHECK (length(plan_id) <= 80 AND length(plan_id) > 0),
  goal_id                                  TEXT CHECK (goal_id IS NULL OR length(goal_id) <= 80 AND length(goal_id) > 0),
  action_id                                TEXT CHECK (action_id IS NULL OR length(action_id) <= 80 AND length(action_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  source_type                              TEXT NOT NULL CHECK (source_type IN ('passport_evidence','assessment','box_cam_session','combine_attempt','trial_report')),
  source_id                                TEXT NOT NULL CHECK (length(source_id) <= 80 AND length(source_id) > 0),
  linked_by_kind                           TEXT NOT NULL CHECK (linked_by_kind IN ('player','guardian','org')),
  linked_by_id                             TEXT NOT NULL CHECK (length(linked_by_id) <= 80 AND length(linked_by_id) > 0),
  linked_by_name                           TEXT CHECK (linked_by_name IS NULL OR length(linked_by_name) <= 200),
  linked_at                                INTEGER NOT NULL,
  FOREIGN KEY (plan_id) REFERENCES development_plans(id) ON DELETE RESTRICT,
  FOREIGN KEY (goal_id) REFERENCES development_goals(id) ON DELETE RESTRICT,
  FOREIGN KEY (action_id) REFERENCES development_actions(id) ON DELETE RESTRICT,
  CHECK ((goal_id IS NULL) <> (action_id IS NULL))
) STRICT;
CREATE TABLE development_reviews (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  plan_id                                  TEXT NOT NULL CHECK (length(plan_id) <= 80 AND length(plan_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  reviewer_kind                            TEXT NOT NULL CHECK (reviewer_kind IN ('player_reflection','guardian_reflection','coach_review')),
  reviewed_by_kind                         TEXT NOT NULL CHECK (reviewed_by_kind IN ('player','guardian','org')),
  reviewed_by_id                           TEXT NOT NULL CHECK (length(reviewed_by_id) <= 80 AND length(reviewed_by_id) > 0),
  reviewed_by_name                         TEXT CHECK (reviewed_by_name IS NULL OR length(reviewed_by_name) <= 200),
  org_id                                   TEXT CHECK (org_id IS NULL OR length(org_id) <= 80 AND length(org_id) > 0),
  reviewed_at                              INTEGER NOT NULL,
  shared_summary                           TEXT CHECK (shared_summary IS NULL OR length(shared_summary) <= 2000),
  internal_note                            TEXT CHECK (internal_note IS NULL OR length(internal_note) <= 2000),
  next_review_at                           INTEGER,
  shared_with_player_at                    INTEGER,
  supersedes_review_id                     TEXT CHECK (supersedes_review_id IS NULL OR length(supersedes_review_id) <= 80 AND length(supersedes_review_id) > 0),
  created_at                               INTEGER NOT NULL,
  share_summary                            INTEGER NOT NULL CHECK (share_summary IN (0,1)),
  share_goals                              INTEGER NOT NULL CHECK (share_goals IN (0,1)),
  share_actions                            INTEGER NOT NULL CHECK (share_actions IN (0,1)),
  FOREIGN KEY (plan_id) REFERENCES development_plans(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (supersedes_review_id) REFERENCES development_reviews(id) ON DELETE RESTRICT,
  CHECK (shared_summary IS NOT NULL OR internal_note IS NOT NULL),
  CHECK ((reviewer_kind = 'coach_review') = (org_id IS NOT NULL)),
  CHECK (reviewer_kind = 'coach_review' OR internal_note IS NULL),
  CHECK ((share_summary + share_goals + share_actions = 0) OR shared_with_player_at IS NOT NULL)
) STRICT;
CREATE TABLE development_review_snapshots (
  review_id                                TEXT NOT NULL CHECK (length(review_id) <= 80 AND length(review_id) > 0),
  ord                                      INTEGER NOT NULL,
  goal_id                                  TEXT NOT NULL CHECK (length(goal_id) <= 80 AND length(goal_id) > 0),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  category                                 TEXT NOT NULL CHECK (category IN ('technical','tactical','physical','psychological','match_understanding','position_specific','other')),
  status                                   TEXT NOT NULL CHECK (status IN ('not_started','in_progress','blocked','achieved','stopped')),
  actions_total                            INTEGER NOT NULL,
  actions_done                             INTEGER NOT NULL,
  actions_blocked                          INTEGER NOT NULL,
  actions_cancelled                        INTEGER NOT NULL,
  target_state                             TEXT CHECK (target_state IS NULL OR target_state IN ('target_met','target_not_met','no_current_valid_measurement')),
  target_reason                            TEXT CHECK (target_reason IS NULL OR target_reason IN ('no_attempts','no_production_valid_attempt','protocol_version_mismatch','measurement_invalidated')),
  target_measured                          REAL,
  FOREIGN KEY (review_id) REFERENCES development_reviews(id) ON DELETE CASCADE,
  FOREIGN KEY (goal_id) REFERENCES development_goals(id) ON DELETE RESTRICT,
  PRIMARY KEY (review_id, goal_id),
  UNIQUE (review_id, ord),
  CHECK (ord >= 0),
  CHECK (actions_total >= 0 AND actions_done >= 0 AND actions_blocked >= 0 AND actions_cancelled >= 0 AND actions_done + actions_blocked + actions_cancelled <= actions_total)
) STRICT;
CREATE TABLE development_review_snapshot_refs (
  review_id                                TEXT NOT NULL CHECK (length(review_id) > 0 AND length(review_id) <= 80),
  goal_id                                  TEXT NOT NULL CHECK (length(goal_id) > 0 AND length(goal_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  source_type                              TEXT NOT NULL CHECK (source_type IN ('passport_evidence','assessment','box_cam_session','combine_attempt','trial_report')),
  source_id                                TEXT NOT NULL CHECK (length(source_id) > 0 AND length(source_id) <= 80),
  FOREIGN KEY (review_id, goal_id) REFERENCES development_review_snapshots(review_id, goal_id) ON DELETE CASCADE,
  PRIMARY KEY (review_id, goal_id, ord)
) STRICT;
CREATE TABLE development_history (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  plan_id                                  TEXT NOT NULL CHECK (length(plan_id) <= 80 AND length(plan_id) > 0),
  goal_id                                  TEXT CHECK (goal_id IS NULL OR length(goal_id) <= 80 AND length(goal_id) > 0),
  action_id                                TEXT CHECK (action_id IS NULL OR length(action_id) <= 80 AND length(action_id) > 0),
  review_id                                TEXT CHECK (review_id IS NULL OR length(review_id) <= 80 AND length(review_id) > 0),
  at                                       INTEGER NOT NULL,
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('player','guardian','org')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action                                   TEXT NOT NULL CHECK (action IN ('plan_created','plan_activated','plan_paused','plan_completed','plan_archived','plan_shared','plan_unshared','plan_visibility_changed','plan_updated','goal_created','goal_updated','goal_status_changed','goal_target_set','action_created','action_status_changed','action_completed','evidence_linked','evidence_unlinked','review_submitted','review_shared','review_superseded')),
  detail_from                              TEXT CHECK (detail_from IS NULL OR length(detail_from) <= 40 AND length(detail_from) > 0),
  detail_to                                TEXT CHECK (detail_to IS NULL OR length(detail_to) <= 40 AND length(detail_to) > 0),
  detail_visibility                        TEXT CHECK (detail_visibility IS NULL OR detail_visibility IN ('private','player_guardian','shared_with_org','org_private')),
  detail_owner                             TEXT CHECK (detail_owner IS NULL OR detail_owner IN ('player','org')),
  detail_kind                              TEXT CHECK (detail_kind IS NULL OR length(detail_kind) <= 40 AND length(detail_kind) > 0),
  detail_protocol_id                       TEXT CHECK (detail_protocol_id IS NULL OR length(detail_protocol_id) <= 80 AND length(detail_protocol_id) > 0),
  detail_note                              INTEGER CHECK (detail_note IS NULL OR detail_note IN (0,1)),
  FOREIGN KEY (plan_id) REFERENCES development_plans(id) ON DELETE CASCADE,
  FOREIGN KEY (goal_id) REFERENCES development_goals(id) ON DELETE CASCADE,
  FOREIGN KEY (action_id) REFERENCES development_actions(id) ON DELETE CASCADE,
  FOREIGN KEY (review_id) REFERENCES development_reviews(id) ON DELETE CASCADE,
  CHECK ((goal_id IS NOT NULL) + (action_id IS NOT NULL) + (review_id IS NOT NULL) <= 1)
) STRICT;
CREATE TABLE box_cam_prefs (
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  share_development_activity               TEXT NOT NULL CHECK (share_development_activity IN ('private','recruitment')),
  retain_clips                             INTEGER NOT NULL CHECK (retain_clips IN (0,1)),
  updated_at                               INTEGER,
  updated_by_kind                          TEXT CHECK (updated_by_kind IS NULL OR updated_by_kind IN ('player','guardian')),
  updated_by_id                            TEXT CHECK (updated_by_id IS NULL OR length(updated_by_id) <= 80 AND length(updated_by_id) > 0),
  PRIMARY KEY (player_id),
  CHECK ((updated_at IS NULL) = (updated_by_kind IS NULL) AND (updated_at IS NULL) = (updated_by_id IS NULL))
) STRICT;
CREATE TABLE box_challenges (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  publisher_kind                           TEXT NOT NULL CHECK (publisher_kind IN ('org','scoutbox')),
  publisher_org_id                         TEXT CHECK (publisher_org_id IS NULL OR length(publisher_org_id) <= 80 AND length(publisher_org_id) > 0),
  publisher_org_name                       TEXT CHECK (publisher_org_name IS NULL OR length(publisher_org_name) <= 200),
  publisher_by_name                        TEXT CHECK (publisher_by_name IS NULL OR length(publisher_by_name) <= 200),
  drill_id                                 TEXT NOT NULL CHECK (length(drill_id) <= 80 AND length(drill_id) > 0),
  metric                                   TEXT NOT NULL CHECK (metric IN ('reps','active_minutes')),
  target_total                             INTEGER NOT NULL,
  starts_at                                INTEGER NOT NULL,
  ends_at                                  INTEGER NOT NULL,
  adult_only                               INTEGER NOT NULL CHECK (adult_only IN (0,1)),
  cap                                      INTEGER,
  status                                   TEXT NOT NULL CHECK (status IN ('active')),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (publisher_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK ((publisher_kind = 'org') = (publisher_org_id IS NOT NULL)),
  CHECK (publisher_kind = 'org' OR (publisher_org_name IS NULL AND publisher_by_name IS NULL)),
  CHECK (target_total >= 1),
  CHECK (ends_at > starts_at),
  CHECK (cap IS NULL OR cap >= 1)
) STRICT;
CREATE TABLE box_challenge_entries (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  challenge_id                             TEXT NOT NULL CHECK (length(challenge_id) <= 80 AND length(challenge_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('active','completed')),
  progress                                 INTEGER NOT NULL,
  joined_at                                INTEGER NOT NULL,
  joined_by_kind                           TEXT NOT NULL CHECK (joined_by_kind IN ('player','guardian')),
  joined_by_id                             TEXT NOT NULL CHECK (length(joined_by_id) <= 80 AND length(joined_by_id) > 0),
  completed_at                             INTEGER,
  FOREIGN KEY (challenge_id) REFERENCES box_challenges(id) ON DELETE RESTRICT,
  UNIQUE (id, player_id),
  CHECK (progress >= 0),
  CHECK ((status = 'completed') = (completed_at IS NOT NULL))
) STRICT;
CREATE TABLE box_assignments (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  org_name                                 TEXT CHECK (org_name IS NULL OR length(org_name) <= 200),
  assigned_by_user_id                      TEXT NOT NULL CHECK (length(assigned_by_user_id) <= 80 AND length(assigned_by_user_id) > 0),
  assigned_by_name                         TEXT CHECK (assigned_by_name IS NULL OR length(assigned_by_name) <= 200),
  assigned_by_role                         TEXT CHECK (assigned_by_role IS NULL OR length(assigned_by_role) <= 80),
  assigned_by_org_verified                 INTEGER NOT NULL CHECK (assigned_by_org_verified IN (0,1)),
  assigned_at                              INTEGER NOT NULL,
  drill_id                                 TEXT NOT NULL CHECK (length(drill_id) <= 80 AND length(drill_id) > 0),
  drill_version                            INTEGER NOT NULL,
  target_type                              TEXT NOT NULL CHECK (target_type IN ('repetitions','duration','sets')),
  target_value                             REAL NOT NULL,
  frequency_per_week                       INTEGER,
  due_date                                 TEXT CHECK (due_date IS NULL OR length(due_date) <= 10),
  instructions                             TEXT CHECK (instructions IS NULL OR length(instructions) <= 300),
  objective_id                             TEXT CHECK (objective_id IS NULL OR length(objective_id) <= 80 AND length(objective_id) > 0),
  state                                    TEXT NOT NULL CHECK (state IN ('assigned','accepted','in_progress','partially_completed','completed','cancelled')),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (assigned_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (objective_id) REFERENCES dev_objectives(id) ON DELETE RESTRICT,
  UNIQUE (id, player_id),
  CHECK (target_value > 0),
  CHECK (frequency_per_week IS NULL OR frequency_per_week BETWEEN 1 AND 14),
  CHECK (due_date IS NULL OR (length(due_date) = 10 AND due_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'))
) STRICT;
CREATE TABLE box_sessions (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  drill_id                                 TEXT NOT NULL CHECK (length(drill_id) <= 80 AND length(drill_id) > 0),
  drill_version                            INTEGER NOT NULL,
  assignment_id                            TEXT CHECK (assignment_id IS NULL OR length(assignment_id) <= 80 AND length(assignment_id) > 0),
  challenge_entry_id                       TEXT CHECK (challenge_entry_id IS NULL OR length(challenge_entry_id) <= 80 AND length(challenge_entry_id) > 0),
  target_type                              TEXT NOT NULL CHECK (target_type IN ('repetitions','duration','sets')),
  target_value                             REAL NOT NULL,
  nonce_hash                               TEXT NOT NULL CHECK (length(nonce_hash) <= 64 AND length(nonce_hash) > 0),
  liveness_challenge                       TEXT NOT NULL CHECK (liveness_challenge IN ('raise_right_hand','show_ball','left_foot_touch','step_into_zone')),
  provider_id                              TEXT NOT NULL CHECK (provider_id IN ('production_cv','web_client','local_test')),
  provider_version                         INTEGER NOT NULL,
  status                                   TEXT NOT NULL CHECK (status IN ('setup_required','recording','processing','verified','partially_verified','unable_to_verify','completed_unverified','cancelled','invalidated')),
  created_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  started_at                               INTEGER,
  ended_at                                 INTEGER,
  liveness_passed_at                       INTEGER,
  last_seq                                 INTEGER NOT NULL,
  batches                                  INTEGER NOT NULL,
  capture_context                          TEXT CHECK (capture_context IS NULL OR capture_context IN ('at_home','club','event')),
  session_duration_ms                      REAL,
  verified_active_ms                       REAL,
  verified_reps                            INTEGER,
  sets_completed                           INTEGER,
  target_completed                         INTEGER CHECK (target_completed IS NULL OR target_completed IN (0,1)),
  quality                                  TEXT CHECK (quality IS NULL OR quality IN ('good','degraded','insufficient')),
  interruptions_count                      INTEGER,
  verification_state                       TEXT CHECK (verification_state IS NULL OR verification_state IN ('verified','partially_verified','unable_to_verify','completed_unverified','cancelled','invalidated')),
  result_hash                              TEXT CHECK (result_hash IS NULL OR length(result_hash) <= 64),
  finalized_at                             INTEGER,
  note                                     TEXT CHECK (note IS NULL OR length(note) <= 300),
  clip_media_id                            TEXT CHECK (clip_media_id IS NULL OR length(clip_media_id) <= 80 AND length(clip_media_id) > 0),
  previous_verification_state              TEXT CHECK (previous_verification_state IS NULL OR previous_verification_state IN ('verified','partially_verified','unable_to_verify','completed_unverified','cancelled')),
  invalidated_at                           INTEGER,
  cv_provider_session_id                   TEXT CHECK (cv_provider_session_id IS NULL OR length(cv_provider_session_id) <= 80 AND length(cv_provider_session_id) > 0),
  FOREIGN KEY (assignment_id, player_id) REFERENCES box_assignments(id, player_id) ON DELETE RESTRICT,
  FOREIGN KEY (challenge_entry_id, player_id) REFERENCES box_challenge_entries(id, player_id) ON DELETE RESTRICT,
  UNIQUE (id, player_id),
  CHECK (length(nonce_hash) = 64 AND nonce_hash NOT GLOB '*[^0-9a-f]*'),
  CHECK (last_seq >= 0 AND batches >= 0),
  CHECK (status NOT IN ('verified','partially_verified','unable_to_verify','completed_unverified','invalidated') OR status = verification_state),
  CHECK ((verification_state = 'invalidated') = (previous_verification_state IS NOT NULL))
) STRICT;
CREATE TABLE box_session_observations (
  session_id                               TEXT NOT NULL CHECK (length(session_id) > 0 AND length(session_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 4000),
  kind                                     TEXT NOT NULL CHECK (kind IN ('active','presence','ball','rep','set','pause','interruption','multi_person')),
  from_ms                                  REAL,
  to_ms                                    REAL,
  at_ms                                    REAL,
  quality                                  TEXT CHECK (quality IS NULL OR quality IN ('good','degraded','insufficient')),
  confidence                               REAL CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),
  FOREIGN KEY (session_id) REFERENCES box_sessions(id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, ord),
  CHECK (kind NOT IN ('active','presence','ball','interruption','multi_person') OR (from_ms IS NOT NULL AND to_ms IS NOT NULL AND at_ms IS NULL)),
  CHECK (kind NOT IN ('rep','set') OR (at_ms IS NOT NULL AND from_ms IS NULL AND to_ms IS NULL)),
  CHECK (kind <> 'pause' OR (from_ms IS NOT NULL AND at_ms IS NULL)),
  CHECK (kind IN ('active','presence') OR quality IS NULL),
  CHECK (kind = 'rep' OR confidence IS NULL)
) STRICT;
CREATE TABLE box_session_reasons (
  session_id                               TEXT NOT NULL CHECK (length(session_id) > 0 AND length(session_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 40),
  code                                     TEXT NOT NULL CHECK (length(code) > 0 AND length(code) <= 80 AND code NOT GLOB '*[^A-Za-z0-9_]*'),
  FOREIGN KEY (session_id) REFERENCES box_sessions(id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, ord)
) STRICT;
CREATE TABLE box_session_integrity_events (
  session_id                               TEXT NOT NULL CHECK (length(session_id) <= 80 AND length(session_id) > 0),
  ord                                      INTEGER NOT NULL,
  type                                     TEXT NOT NULL CHECK (type IN ('invalidated','restored')),
  at                                       INTEGER NOT NULL,
  dispute_id                               TEXT CHECK (dispute_id IS NULL OR length(dispute_id) <= 80 AND length(dispute_id) > 0),
  outcome                                  TEXT CHECK (outcome IS NULL OR outcome IN ('invalidated','provider_bug')),
  to_state                                 TEXT CHECK (to_state IS NULL OR to_state IN ('verified','partially_verified','unable_to_verify','completed_unverified','cancelled')),
  FOREIGN KEY (session_id) REFERENCES box_sessions(id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, ord),
  CHECK (ord >= 0),
  CHECK ((type = 'invalidated') = (outcome IS NOT NULL)),
  CHECK ((type = 'restored') = (to_state IS NOT NULL)),
  CHECK (type = 'invalidated' OR dispute_id IS NULL)
) STRICT;
CREATE TABLE box_cam_disputes (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  session_id                               TEXT NOT NULL CHECK (length(session_id) <= 80 AND length(session_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('player','guardian')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  reason                                   TEXT NOT NULL CHECK (length(reason) <= 500 AND length(reason) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('open','resolved')),
  resolution_outcome                       TEXT CHECK (resolution_outcome IS NULL OR resolution_outcome IN ('stands','invalidated','provider_bug')),
  resolution_reason                        TEXT CHECK (resolution_reason IS NULL OR length(resolution_reason) <= 400 AND length(resolution_reason) > 0),
  resolved_at                              INTEGER,
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (session_id, player_id) REFERENCES box_sessions(id, player_id) ON DELETE CASCADE,
  CHECK ((status = 'resolved') = (resolved_at IS NOT NULL)),
  CHECK ((resolved_at IS NULL) = (resolution_outcome IS NULL) AND (resolved_at IS NULL) = (resolution_reason IS NULL))
) STRICT;
CREATE TABLE combine_requests (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  org_name                                 TEXT CHECK (org_name IS NULL OR length(org_name) <= 200),
  requested_by_user_id                     TEXT NOT NULL CHECK (length(requested_by_user_id) <= 80 AND length(requested_by_user_id) > 0),
  requested_by_name                        TEXT CHECK (requested_by_name IS NULL OR length(requested_by_name) <= 200),
  requested_by_role                        TEXT CHECK (requested_by_role IS NULL OR length(requested_by_role) <= 80),
  requested_at                             INTEGER NOT NULL,
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  title                                    TEXT CHECK (title IS NULL OR length(title) <= 120 AND length(title) > 0),
  deadline_date                            TEXT CHECK (deadline_date IS NULL OR length(deadline_date) <= 10),
  instructions                             TEXT CHECK (instructions IS NULL OR length(instructions) <= 300),
  state                                    TEXT NOT NULL CHECK (state IN ('requested','completed','cancelled')),
  created_at                               INTEGER NOT NULL,
  completed_at                             INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (requested_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  UNIQUE (id, player_id),
  CHECK (deadline_date IS NULL OR (length(deadline_date) = 10 AND deadline_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')),
  CHECK ((state = 'completed') = (completed_at IS NOT NULL) OR state = 'cancelled')
) STRICT;
CREATE TABLE combine_request_protocols (
  request_id                               TEXT NOT NULL CHECK (length(request_id) > 0 AND length(request_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 20),
  protocol_id                              TEXT NOT NULL CHECK (length(protocol_id) > 0 AND length(protocol_id) <= 80),
  FOREIGN KEY (request_id) REFERENCES combine_requests(id) ON DELETE CASCADE,
  PRIMARY KEY (request_id, ord),
  UNIQUE (request_id, protocol_id)
) STRICT;
CREATE TABLE combine_attempts (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  protocol_id                              TEXT NOT NULL CHECK (length(protocol_id) <= 80 AND length(protocol_id) > 0),
  protocol_version                         INTEGER NOT NULL,
  box_session_id                           TEXT NOT NULL CHECK (length(box_session_id) <= 80 AND length(box_session_id) > 0),
  attempt_number                           INTEGER NOT NULL,
  mode                                     TEXT NOT NULL CHECK (mode IN ('verified','practice')),
  capture_context                          TEXT NOT NULL CHECK (capture_context IN ('at_home','club','event')),
  request_id                               TEXT CHECK (request_id IS NULL OR length(request_id) <= 80 AND length(request_id) > 0),
  metric_type                              TEXT NOT NULL CHECK (metric_type IN ('count','time','distance','duration','set','percentage')),
  metric_unit                              TEXT NOT NULL CHECK (length(metric_unit) <= 40 AND length(metric_unit) > 0),
  direction                                TEXT NOT NULL CHECK (direction IN ('higher','lower')),
  measurement_algorithm_version            INTEGER NOT NULL,
  provider_id                              TEXT NOT NULL CHECK (provider_id IN ('production_cv','web_client','local_test')),
  provider_version                         INTEGER NOT NULL,
  measured_value                           REAL,
  measurement_state                        TEXT CHECK (measurement_state IS NULL OR measurement_state IN ('measured','practice','partially_measured','measurement_unavailable','protocol_invalid','invalidated','cancelled')),
  combine_state                            TEXT NOT NULL CHECK (combine_state IN ('ready','combine_verified','partially_measured','measurement_unavailable','protocol_invalid','invalidated','cancelled')),
  started_at                               INTEGER,
  completed_at                             INTEGER,
  result_hash                              TEXT CHECK (result_hash IS NULL OR length(result_hash) <= 64),
  created_at                               INTEGER NOT NULL,
  calibration_passed                       INTEGER CHECK (calibration_passed IS NULL OR calibration_passed IN (0,1)),
  calibrated_at                            INTEGER,
  FOREIGN KEY (box_session_id, player_id) REFERENCES box_sessions(id, player_id) ON DELETE RESTRICT,
  FOREIGN KEY (request_id, player_id) REFERENCES combine_requests(id, player_id) ON DELETE RESTRICT,
  CHECK ((calibration_passed IS NULL) = (calibrated_at IS NULL)),
  CHECK (attempt_number >= 1)
) STRICT;
CREATE TABLE combine_attempt_reasons (
  attempt_id                               TEXT NOT NULL CHECK (length(attempt_id) > 0 AND length(attempt_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 40),
  code                                     TEXT NOT NULL CHECK (length(code) > 0 AND length(code) <= 80 AND code NOT GLOB '*[^A-Za-z0-9_]*'),
  FOREIGN KEY (attempt_id) REFERENCES combine_attempts(id) ON DELETE CASCADE,
  PRIMARY KEY (attempt_id, ord)
) STRICT;
CREATE TABLE combine_attempt_calibration_checks (
  attempt_id                               TEXT NOT NULL CHECK (length(attempt_id) > 0 AND length(attempt_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 10),
  check_name                               TEXT NOT NULL CHECK (length(check_name) > 0 AND length(check_name) <= 60),
  FOREIGN KEY (attempt_id) REFERENCES combine_attempts(id) ON DELETE CASCADE,
  PRIMARY KEY (attempt_id, ord)
) STRICT;
CREATE TABLE box_cam_cv_results (
  provider_session_id                      TEXT NOT NULL CHECK (length(provider_session_id) <= 80 AND length(provider_session_id) > 0),
  session_id                               TEXT NOT NULL CHECK (length(session_id) <= 80 AND length(session_id) > 0),
  protocol_id                              TEXT NOT NULL CHECK (protocol_id IN ('combine-box-touch-60','combine-box-juggle','combine-box-control-60')),
  provider_id                              TEXT NOT NULL CHECK (provider_id IN ('production_cv')),
  provider_version                         INTEGER NOT NULL,
  engine_version                           INTEGER NOT NULL,
  cv_policy_version                        INTEGER NOT NULL,
  outcome                                  TEXT NOT NULL CHECK (outcome IN ('accepted','refused')),
  refusal_reason                           TEXT CHECK (refusal_reason IS NULL OR length(refusal_reason) <= 80),
  refusal_detail                           TEXT CHECK (refusal_detail IS NULL OR length(refusal_detail) <= 300),
  oq_sufficient                            INTEGER NOT NULL CHECK (oq_sufficient IN (0,1)),
  oq_state                                 TEXT CHECK (oq_state IS NULL OR oq_state IN ('sufficient','insufficient')),
  oq_aggregate_confidence                  REAL,
  oq_coverage                              REAL,
  person_present                           INTEGER NOT NULL CHECK (person_present IN (0,1)),
  ball_present                             INTEGER NOT NULL CHECK (ball_present IN (0,1)),
  touch_count                              INTEGER,
  juggle_count                             INTEGER,
  active_duration_ms                       REAL NOT NULL,
  experimental_exact_count                 INTEGER,
  experimental_status                      TEXT NOT NULL CHECK (experimental_status IN ('experimental_unvalidated')),
  integrity_ok                             INTEGER NOT NULL CHECK (integrity_ok IN (0,1)),
  frames_accepted                          INTEGER NOT NULL,
  frames_rejected                          INTEGER NOT NULL,
  frames_dropped_by_server                 INTEGER NOT NULL,
  duplicates_rejected                      INTEGER NOT NULL,
  out_of_order_rejected                    INTEGER NOT NULL,
  client_clock_anomalies                   INTEGER NOT NULL,
  frames_analysed                          INTEGER,
  duplicate_frames                         INTEGER,
  effective_fps                            REAL,
  max_ball_gap_ms                          REAL,
  nonce_bound                              INTEGER NOT NULL CHECK (nonce_bound IN (0,1)),
  server_timeline                          INTEGER NOT NULL CHECK (server_timeline IN (0,1)),
  trace_truncated                          INTEGER NOT NULL CHECK (trace_truncated IN (0,1)),
  server_started_at                        INTEGER,
  server_ended_at                          INTEGER,
  server_duration_ms                       INTEGER NOT NULL,
  combine_verified                         INTEGER NOT NULL CHECK (combine_verified IN (0,1)),
  combine_verified_blocked_by              TEXT CHECK (combine_verified_blocked_by IS NULL OR length(combine_verified_blocked_by) <= 80),
  FOREIGN KEY (session_id) REFERENCES box_sessions(id) ON DELETE CASCADE,
  PRIMARY KEY (provider_session_id),
  CHECK ((outcome = 'refused') = (refusal_reason IS NOT NULL)),
  CHECK (combine_verified = 0)
) STRICT;
CREATE TABLE box_cam_cv_result_codes (
  provider_session_id                      TEXT NOT NULL CHECK (length(provider_session_id) > 0 AND length(provider_session_id) <= 80),
  list                                     TEXT NOT NULL CHECK (list IN ('quality','secondary')),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 40),
  code                                     TEXT NOT NULL CHECK (length(code) > 0 AND length(code) <= 80 AND code NOT GLOB '*[^A-Za-z0-9_]*'),
  value                                    REAL,
  threshold                                REAL,
  FOREIGN KEY (provider_session_id) REFERENCES box_cam_cv_results(provider_session_id) ON DELETE CASCADE,
  PRIMARY KEY (provider_session_id, list, ord),
  CHECK (list = 'quality' OR (value IS NULL AND threshold IS NULL))
) STRICT;
CREATE TABLE box_cam_cv_result_trace (
  provider_session_id                      TEXT NOT NULL CHECK (length(provider_session_id) > 0 AND length(provider_session_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0 AND ord < 256),
  at_ms                                    REAL,
  confidence                               REAL,
  FOREIGN KEY (provider_session_id) REFERENCES box_cam_cv_results(provider_session_id) ON DELETE CASCADE,
  PRIMARY KEY (provider_session_id, ord)
) STRICT;
CREATE TABLE recruitment_briefs (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  version                                  INTEGER NOT NULL,
  status                                   TEXT NOT NULL CHECK (status IN ('draft','active','paused','closed','archived')),
  active_from_date                         TEXT CHECK (active_from_date IS NULL OR length(active_from_date) <= 10),
  active_until_date                        TEXT CHECK (active_until_date IS NULL OR length(active_until_date) <= 10),
  role_id                                  TEXT CHECK (role_id IS NULL OR length(role_id) <= 64 AND length(role_id) > 0),
  vacancy_id                               TEXT CHECK (vacancy_id IS NULL OR length(vacancy_id) <= 64 AND length(vacancy_id) > 0),
  created_by_user_id                       TEXT NOT NULL CHECK (length(created_by_user_id) <= 80 AND length(created_by_user_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_user_id                           TEXT CHECK (rev_by_user_id IS NULL OR length(rev_by_user_id) <= 80 AND length(rev_by_user_id) > 0),
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  min_age                                  INTEGER,
  max_age                                  INTEGER,
  radius_km                                REAL,
  max_level                                TEXT CHECK (max_level IS NULL OR max_level IN ('amateur','semi_pro','pro')),
  foot                                     TEXT CHECK (foot IS NULL OR foot IN ('Left','Right','Both')),
  availability                             TEXT CHECK (availability IS NULL OR length(availability) <= 40),
  min_trust_band                           TEXT CHECK (min_trust_band IS NULL OR min_trust_band IN ('limited_evidence','developing_evidence','established_evidence','strong_evidence','very_strong_evidence')),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (active_from_date IS NULL OR active_from_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (active_until_date IS NULL OR active_until_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (version >= 1),
  CHECK (rev >= 1),
  CHECK (min_age IS NULL OR (min_age >= 5 AND min_age <= 60)),
  CHECK (max_age IS NULL OR (max_age >= 5 AND max_age <= 60)),
  CHECK (min_age IS NULL OR max_age IS NULL OR min_age <= max_age),
  CHECK (radius_km IS NULL OR (radius_km > 0 AND radius_km <= 20000)),
  CHECK (active_from_date IS NULL OR active_until_date IS NULL OR active_from_date <= active_until_date)
) STRICT;
CREATE TABLE recruitment_brief_values (
  brief_id                                 TEXT NOT NULL CHECK (length(brief_id) > 0 AND length(brief_id) <= 80),
  kind                                     TEXT NOT NULL CHECK (kind IN ('position','evidence_requirement','combine_protocol')),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  value                                    TEXT NOT NULL CHECK (length(value) > 0 AND length(value) <= 80),
  CHECK (kind <> 'position' OR value IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  CHECK (kind <> 'evidence_requirement' OR value IN ('recent_full_match','coach_reference','confirmed_current_club','combine_verified')),
  FOREIGN KEY (brief_id) REFERENCES recruitment_briefs(id) ON DELETE CASCADE,
  PRIMARY KEY (brief_id, kind, ord),
  UNIQUE (brief_id, kind, value)
) STRICT;
CREATE TABLE recruitment_brief_history (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  brief_id                                 TEXT NOT NULL CHECK (length(brief_id) <= 80 AND length(brief_id) > 0),
  at                                       INTEGER NOT NULL,
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('org')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action                                   TEXT NOT NULL CHECK (action IN ('recruitment_brief_created','recruitment_brief_activated','recruitment_brief_updated')),
  detail_version                           INTEGER,
  detail_from                              TEXT CHECK (detail_from IS NULL OR detail_from IN ('draft','active','paused','closed','archived')),
  detail_to                                TEXT CHECK (detail_to IS NULL OR detail_to IN ('draft','active','paused','closed','archived')),
  detail_criteria_changed                  INTEGER CHECK (detail_criteria_changed IS NULL OR detail_criteria_changed IN (0,1)),
  FOREIGN KEY (brief_id) REFERENCES recruitment_briefs(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE nobody_missed_reviews (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  brief_id                                 TEXT NOT NULL CHECK (length(brief_id) <= 80 AND length(brief_id) > 0),
  brief_version                            INTEGER NOT NULL,
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  state                                    TEXT NOT NULL CHECK (state IN ('open','reviewed','added_to_room','dismissed')),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  reviewed_by_user_id                      TEXT CHECK (reviewed_by_user_id IS NULL OR length(reviewed_by_user_id) <= 80 AND length(reviewed_by_user_id) > 0),
  reviewed_by_name                         TEXT CHECK (reviewed_by_name IS NULL OR length(reviewed_by_name) <= 200),
  reviewed_at                              INTEGER,
  dismiss_reason                           TEXT CHECK (dismiss_reason IS NULL OR dismiss_reason IN ('already_known','not_current_need','evidence_insufficient','role_mismatch_after_review','timing','other')),
  dismissed_by_user_id                     TEXT CHECK (dismissed_by_user_id IS NULL OR length(dismissed_by_user_id) <= 80 AND length(dismissed_by_user_id) > 0),
  dismissed_by_name                        TEXT CHECK (dismissed_by_name IS NULL OR length(dismissed_by_name) <= 200),
  dismissed_at                             INTEGER,
  room_id                                  TEXT CHECK (room_id IS NULL OR length(room_id) <= 80 AND length(room_id) > 0),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (brief_id) REFERENCES recruitment_briefs(id) ON DELETE RESTRICT,
  FOREIGN KEY (reviewed_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (dismissed_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (room_id) REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  CHECK (state <> 'dismissed' OR dismissed_at IS NOT NULL),
  CHECK (state <> 'added_to_room' OR room_id IS NOT NULL),
  UNIQUE (org_id, brief_id, player_id)
) STRICT;
CREATE TABLE nobody_missed_review_history (
  review_id                                TEXT NOT NULL CHECK (length(review_id) <= 80 AND length(review_id) > 0),
  ord                                      INTEGER NOT NULL,
  at                                       INTEGER NOT NULL,
  state                                    TEXT NOT NULL CHECK (state IN ('open','reviewed','added_to_room','dismissed')),
  by_user_id                               TEXT NOT NULL CHECK (length(by_user_id) <= 80 AND length(by_user_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  FOREIGN KEY (review_id) REFERENCES nobody_missed_reviews(id) ON DELETE CASCADE,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  PRIMARY KEY (review_id, ord),
  CHECK (ord >= 0)
) STRICT;
CREATE TABLE second_look_items (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  room_id                                  TEXT NOT NULL CHECK (length(room_id) <= 80 AND length(room_id) > 0),
  decision_id                              TEXT NOT NULL CHECK (length(decision_id) <= 80 AND length(decision_id) > 0),
  policy_version                           INTEGER NOT NULL,
  trigger_type                             TEXT NOT NULL CHECK (trigger_type IN ('direct_reason_resolved','significant_new_evidence','evidence_removed','general_update')),
  status                                   TEXT NOT NULL CHECK (status IN ('open','reviewed','dismissed','reopened_room','expired')),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  latest_change_at                         INTEGER NOT NULL,
  reviewed_at                              INTEGER,
  reviewed_by_user_id                      TEXT CHECK (reviewed_by_user_id IS NULL OR length(reviewed_by_user_id) <= 80 AND length(reviewed_by_user_id) > 0),
  reviewed_by_name                         TEXT CHECK (reviewed_by_name IS NULL OR length(reviewed_by_name) <= 200),
  dismissed_at                             INTEGER,
  dismissed_by_user_id                     TEXT CHECK (dismissed_by_user_id IS NULL OR length(dismissed_by_user_id) <= 80 AND length(dismissed_by_user_id) > 0),
  dismissed_by_name                        TEXT CHECK (dismissed_by_name IS NULL OR length(dismissed_by_name) <= 200),
  dismiss_reason                           TEXT CHECK (dismiss_reason IS NULL OR dismiss_reason IN ('already_reviewed_elsewhere','change_not_material','timing_not_right','squad_need_changed','no_action_required','other')),
  reopened_at                              INTEGER,
  reopened_by_user_id                      TEXT CHECK (reopened_by_user_id IS NULL OR length(reopened_by_user_id) <= 80 AND length(reopened_by_user_id) > 0),
  reopened_by_name                         TEXT CHECK (reopened_by_name IS NULL OR length(reopened_by_name) <= 200),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (room_id) REFERENCES recruitment_cases(id) ON DELETE RESTRICT,
  FOREIGN KEY (decision_id) REFERENCES room_decisions(id) ON DELETE RESTRICT,
  FOREIGN KEY (reviewed_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (dismissed_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (reopened_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (status <> 'reviewed' OR reviewed_at IS NOT NULL),
  CHECK (status <> 'dismissed' OR dismissed_at IS NOT NULL),
  CHECK (status <> 'reopened_room' OR reopened_at IS NOT NULL),
  UNIQUE (org_id, room_id, decision_id)
) STRICT;
CREATE TABLE second_look_item_fingerprints (
  item_id                                  TEXT NOT NULL CHECK (length(item_id) > 0 AND length(item_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  fingerprint                              TEXT NOT NULL CHECK (length(fingerprint) > 0 AND length(fingerprint) <= 400),
  FOREIGN KEY (item_id) REFERENCES second_look_items(id) ON DELETE CASCADE,
  PRIMARY KEY (item_id, ord),
  UNIQUE (item_id, fingerprint)
) STRICT;
CREATE TABLE second_look_item_reasons (
  item_id                                  TEXT NOT NULL CHECK (length(item_id) > 0 AND length(item_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  code                                     TEXT NOT NULL CHECK (code IN ('insufficient_recent_evidence','insufficient_full_match','reference_missing','combine_missing','trial_needed','continue_monitoring','physical_profile','technical_fit','tactical_fit','development_upside','not_current_priority','position_need','trial_outcome','squad_space','budget','timing','registration','travel_logistics','eligibility','player_unavailable')),
  FOREIGN KEY (item_id) REFERENCES second_look_items(id) ON DELETE CASCADE,
  PRIMARY KEY (item_id, ord),
  UNIQUE (item_id, code)
) STRICT;
CREATE TABLE second_look_item_history (
  item_id                                  TEXT NOT NULL CHECK (length(item_id) > 0 AND length(item_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  at                                       INTEGER NOT NULL,
  action                                   TEXT NOT NULL CHECK (action IN ('surfaced','resurfaced','reviewed','dismissed','reopened_room')),
  by_user_id                               TEXT CHECK (by_user_id IS NULL OR (length(by_user_id) > 0 AND length(by_user_id) <= 80)),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  reason                                   TEXT CHECK (reason IS NULL OR reason IN ('materially_new_evidence','already_reviewed_elsewhere','change_not_material','timing_not_right','squad_need_changed','no_action_required','other')),
  FOREIGN KEY (item_id) REFERENCES second_look_items(id) ON DELETE CASCADE,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  PRIMARY KEY (item_id, ord),
  CHECK ((action IN ('surfaced','resurfaced')) = (by_user_id IS NULL)),
  CHECK (by_user_id IS NOT NULL OR by_name IS NULL),
  CHECK (action IN ('resurfaced','dismissed') OR reason IS NULL),
  CHECK (action <> 'resurfaced' OR reason IS NOT NULL)
) STRICT;
CREATE TABLE dynamic_watchlists (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  name                                     TEXT NOT NULL CHECK (length(name) <= 80 AND length(name) > 0),
  mode                                     TEXT NOT NULL CHECK (mode IN ('live_linked','snapshot')),
  status                                   TEXT NOT NULL CHECK (status IN ('active','paused','archived')),
  source_type                              TEXT NOT NULL CHECK (source_type IN ('brief','saved_search','criteria')),
  brief_id                                 TEXT CHECK (brief_id IS NULL OR length(brief_id) <= 80 AND length(brief_id) > 0),
  source_ref                               TEXT CHECK (source_ref IS NULL OR length(source_ref) <= 64 AND length(source_ref) > 0),
  schema_version                           INTEGER NOT NULL,
  criteria_version                         TEXT NOT NULL CHECK (length(criteria_version) <= 40 AND length(criteria_version) > 0),
  notify                                   INTEGER NOT NULL CHECK (notify IN (0,1)),
  created_by_user_id                       TEXT NOT NULL CHECK (length(created_by_user_id) <= 80 AND length(created_by_user_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  rev                                      INTEGER NOT NULL,
  rev_at                                   INTEGER,
  rev_by_user_id                           TEXT CHECK (rev_by_user_id IS NULL OR length(rev_by_user_id) <= 80 AND length(rev_by_user_id) > 0),
  rev_by_name                              TEXT CHECK (rev_by_name IS NULL OR length(rev_by_name) <= 200),
  last_criteria_version                    TEXT CHECK (last_criteria_version IS NULL OR length(last_criteria_version) <= 40 AND length(last_criteria_version) > 0),
  last_brief_version                       INTEGER,
  last_reconciled_at                       INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (brief_id) REFERENCES recruitment_briefs(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK ((source_type = 'brief') = (brief_id IS NOT NULL)),
  CHECK (source_type <> 'brief' OR source_ref IS NULL),
  CHECK (mode <> 'live_linked' OR source_type = 'brief'),
  CHECK (rev >= 1),
  CHECK ((last_reconciled_at IS NULL) = (last_criteria_version IS NULL))
) STRICT;
CREATE TABLE watchlist_criteria (
  watchlist_id                             TEXT NOT NULL CHECK (length(watchlist_id) > 0 AND length(watchlist_id) <= 80),
  class                                    TEXT NOT NULL CHECK (class IN ('required','preferred')),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  criterion_id                             TEXT NOT NULL CHECK (length(criterion_id) > 0 AND length(criterion_id) <= 600),
  type                                     TEXT NOT NULL CHECK (type IN ('position','age','geography','level','foot','availability','evidence','evidence_recency','trust_band','combine_result','combine_measurement')),
  operator                                 TEXT NOT NULL CHECK (operator IN ('in','between','gte','lte','within_radius','equals','exists','within_days')),
  value_text                               TEXT CHECK (value_text IS NULL OR (length(value_text) > 0 AND length(value_text) <= 80)),
  value_num                                REAL,
  range_min                                INTEGER,
  range_max                                INTEGER,
  primary_only                             INTEGER CHECK (primary_only IS NULL OR primary_only IN (0,1)),
  evidence_kind                            TEXT CHECK (evidence_kind IS NULL OR evidence_kind IN ('any','footage')),
  protocol                                 TEXT CHECK (protocol IS NULL OR (length(protocol) > 0 AND length(protocol) <= 80)),
  FOREIGN KEY (watchlist_id) REFERENCES dynamic_watchlists(id) ON DELETE CASCADE,
  PRIMARY KEY (watchlist_id, class, ord),
  UNIQUE (watchlist_id, class, criterion_id),
  CHECK ((range_min IS NULL) = (range_max IS NULL))
) STRICT;
CREATE TABLE watchlist_criterion_values (
  watchlist_id                             TEXT NOT NULL CHECK (length(watchlist_id) > 0 AND length(watchlist_id) <= 80),
  class                                    TEXT NOT NULL CHECK (class IN ('required','preferred')),
  criterion_ord                            INTEGER NOT NULL CHECK (criterion_ord >= 0),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  value                                    TEXT NOT NULL CHECK (length(value) > 0 AND length(value) <= 80),
  FOREIGN KEY (watchlist_id, class, criterion_ord) REFERENCES watchlist_criteria(watchlist_id, class, ord) ON DELETE CASCADE,
  PRIMARY KEY (watchlist_id, class, criterion_ord, ord)
) STRICT;
CREATE TABLE watchlist_members (
  watchlist_id                             TEXT NOT NULL CHECK (length(watchlist_id) > 0 AND length(watchlist_id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) > 0 AND length(player_id) <= 80),
  FOREIGN KEY (watchlist_id) REFERENCES dynamic_watchlists(id) ON DELETE CASCADE,
  PRIMARY KEY (watchlist_id, player_id)
) STRICT;
CREATE TABLE watchlist_member_checks (
  watchlist_id                             TEXT NOT NULL CHECK (length(watchlist_id) > 0 AND length(watchlist_id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) > 0 AND length(player_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  criterion_id                             TEXT NOT NULL CHECK (length(criterion_id) > 0 AND length(criterion_id) <= 600),
  met                                      INTEGER NOT NULL CHECK (met IN (0,1)),
  FOREIGN KEY (watchlist_id, player_id) REFERENCES watchlist_members(watchlist_id, player_id) ON DELETE CASCADE,
  PRIMARY KEY (watchlist_id, player_id, ord)
) STRICT;
CREATE TABLE watchlist_history (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  watchlist_id                             TEXT NOT NULL CHECK (length(watchlist_id) <= 80 AND length(watchlist_id) > 0),
  at                                       INTEGER NOT NULL,
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('org')),
  by_id                                    TEXT NOT NULL CHECK (length(by_id) <= 80 AND length(by_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action                                   TEXT NOT NULL CHECK (action IN ('watchlist_created','watchlist_updated','watchlist_archived')),
  detail_mode                              TEXT CHECK (detail_mode IS NULL OR detail_mode IN ('live_linked','snapshot')),
  detail_source_type                       TEXT CHECK (detail_source_type IS NULL OR detail_source_type IN ('brief','saved_search','criteria')),
  detail_status                            TEXT CHECK (detail_status IS NULL OR detail_status IN ('active','paused','archived')),
  detail_changed_name                      INTEGER CHECK (detail_changed_name IS NULL OR detail_changed_name IN (0,1)),
  detail_changed_mode                      INTEGER CHECK (detail_changed_mode IS NULL OR detail_changed_mode IN (0,1)),
  detail_changed_status                    INTEGER CHECK (detail_changed_status IS NULL OR detail_changed_status IN (0,1)),
  detail_changed_criteria                  INTEGER CHECK (detail_changed_criteria IS NULL OR detail_changed_criteria IN (0,1)),
  FOREIGN KEY (watchlist_id) REFERENCES dynamic_watchlists(id) ON DELETE CASCADE,
  CHECK ((detail_changed_name IS NULL AND detail_changed_mode IS NULL AND detail_changed_status IS NULL AND detail_changed_criteria IS NULL) OR (detail_changed_name IS NOT NULL AND detail_changed_mode IS NOT NULL AND detail_changed_status IS NOT NULL AND detail_changed_criteria IS NOT NULL))
) STRICT;
CREATE TABLE watchlist_membership_events (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  watchlist_id                             TEXT NOT NULL CHECK (length(watchlist_id) <= 80 AND length(watchlist_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  transition                               TEXT NOT NULL CHECK (transition IN ('entered','left')),
  reason                                   TEXT NOT NULL CHECK (reason IN ('criterion_now_met','criteria_changed','brief_changed','newly_visible','first_evaluation','criterion_no_longer_met','unavailable')),
  criterion_id                             TEXT CHECK (criterion_id IS NULL OR length(criterion_id) <= 600 AND length(criterion_id) > 0),
  text                                     TEXT NOT NULL CHECK (length(text) <= 2000 AND length(text) > 0),
  criteria_version                         TEXT NOT NULL CHECK (length(criteria_version) <= 40 AND length(criteria_version) > 0),
  brief_version                            INTEGER,
  policy_version                           INTEGER NOT NULL,
  at                                       INTEGER NOT NULL,
  fingerprint                              TEXT NOT NULL CHECK (length(fingerprint) <= 400 AND length(fingerprint) > 0),
  FOREIGN KEY (watchlist_id) REFERENCES dynamic_watchlists(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  UNIQUE (fingerprint)
) STRICT;
CREATE TABLE exposure_events (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  kind                                     TEXT NOT NULL CHECK (kind IN ('impression','profile_view','evidence_view')),
  day_index                                INTEGER NOT NULL,
  at                                       INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (day_index >= 0),
  UNIQUE (org_id, player_id, kind, day_index)
) STRICT;
CREATE TABLE review_later (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  by_user_id                               TEXT NOT NULL CHECK (length(by_user_id) <= 80 AND length(by_user_id) > 0),
  due_at                                   INTEGER NOT NULL,
  reminded_at                              INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  UNIQUE (org_id, player_id)
) STRICT;
CREATE TABLE evidence_suggestions (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  player_name                              TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  rule_id                                  TEXT NOT NULL CHECK (rule_id IN ('no_recent_footage','single_match_sample','attribute_never_observed','assessment_disagreement','stale_assessment','uncorroborated_claims')),
  rule_version                             INTEGER NOT NULL,
  explanation                              TEXT NOT NULL CHECK (length(explanation) <= 1000 AND length(explanation) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('suggested','requested','supplied','dismissed','reviewed')),
  requested_at                             INTEGER,
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (rule_version >= 1),
  CHECK (status <> 'requested' OR requested_at IS NOT NULL)
) STRICT;
CREATE TABLE evidence_suggestion_records (
  suggestion_id                            TEXT NOT NULL CHECK (length(suggestion_id) > 0 AND length(suggestion_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  record_id                                TEXT NOT NULL CHECK (length(record_id) > 0 AND length(record_id) <= 80),
  FOREIGN KEY (suggestion_id) REFERENCES evidence_suggestions(id) ON DELETE CASCADE,
  PRIMARY KEY (suggestion_id, ord)
) STRICT;
CREATE TABLE calibration_sessions (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  template_id                              TEXT NOT NULL CHECK (length(template_id) <= 80 AND length(template_id) > 0),
  template_version                         INTEGER NOT NULL,
  media_id                                 TEXT CHECK (media_id IS NULL OR length(media_id) <= 80 AND length(media_id) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('open','closed')),
  created_by_user_id                       TEXT NOT NULL CHECK (length(created_by_user_id) <= 80 AND length(created_by_user_id) > 0),
  created_at                               INTEGER NOT NULL,
  closed_at                                INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  FOREIGN KEY (template_id, template_version) REFERENCES assessment_templates(id, version) ON DELETE RESTRICT,
  CHECK ((status = 'closed') = (closed_at IS NOT NULL))
) STRICT;
CREATE TABLE calibration_participants (
  session_id                               TEXT NOT NULL CHECK (length(session_id) > 0 AND length(session_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) > 0 AND length(user_id) <= 80),
  FOREIGN KEY (session_id) REFERENCES calibration_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  PRIMARY KEY (session_id, ord),
  UNIQUE (session_id, user_id)
) STRICT;
CREATE TABLE calibration_submissions (
  session_id                               TEXT NOT NULL CHECK (length(session_id) > 0 AND length(session_id) <= 80),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) > 0 AND length(user_id) <= 80),
  user_name                                TEXT CHECK (user_name IS NULL OR length(user_name) <= 200),
  confidence                               TEXT NOT NULL CHECK (confidence IN ('low','medium','high')),
  submitted_at                             INTEGER NOT NULL,
  FOREIGN KEY (session_id, user_id) REFERENCES calibration_participants(session_id, user_id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, user_id)
) STRICT;
CREATE TABLE calibration_ratings (
  session_id                               TEXT NOT NULL CHECK (length(session_id) > 0 AND length(session_id) <= 80),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) > 0 AND length(user_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  attr_id                                  TEXT NOT NULL CHECK (length(attr_id) > 0 AND length(attr_id) <= 40),
  value                                    INTEGER CHECK (value IS NULL OR (value >= 1 AND value <= 5)),
  not_observed                             INTEGER NOT NULL CHECK (not_observed IN (0,1)),
  FOREIGN KEY (session_id, user_id) REFERENCES calibration_submissions(session_id, user_id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, user_id, ord),
  UNIQUE (session_id, user_id, attr_id),
  CHECK ((not_observed = 1) = (value IS NULL))
) STRICT;
CREATE TABLE calibration_notes (
  session_id                               TEXT NOT NULL CHECK (length(session_id) > 0 AND length(session_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  at                                       INTEGER NOT NULL,
  by_user_id                               TEXT NOT NULL CHECK (length(by_user_id) > 0 AND length(by_user_id) <= 80),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  text                                     TEXT NOT NULL CHECK (length(text) > 0 AND length(text) <= 500),
  FOREIGN KEY (session_id) REFERENCES calibration_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  PRIMARY KEY (session_id, ord)
) STRICT;
CREATE TABLE fixtures (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  competition                              TEXT CHECK (competition IS NULL OR length(competition) <= 80 AND length(competition) > 0),
  home                                     TEXT NOT NULL CHECK (length(home) <= 80 AND length(home) > 0),
  away                                     TEXT NOT NULL CHECK (length(away) <= 80 AND length(away) > 0),
  fixture_date                             TEXT NOT NULL CHECK (length(fixture_date) <= 10),
  lat                                      REAL,
  lng                                      REAL,
  city                                     TEXT CHECK (city IS NULL OR length(city) <= 60),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (fixture_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK ((lat IS NULL) = (lng IS NULL)),
  CHECK ((lat IS NULL) = (city IS NULL)),
  CHECK (lat IS NULL OR (lat >= -90 AND lat <= 90 AND lng >= -180 AND lng <= 180))
) STRICT;
CREATE TABLE coverage_plans (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  label                                    TEXT NOT NULL CHECK (length(label) <= 100 AND length(label) > 0),
  competition                              TEXT CHECK (competition IS NULL OR length(competition) <= 80 AND length(competition) > 0),
  region                                   TEXT CHECK (region IS NULL OR length(region) <= 80 AND length(region) > 0),
  goal_observations                        INTEGER NOT NULL,
  window_days                              INTEGER NOT NULL,
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (goal_observations >= 1 AND goal_observations <= 200),
  CHECK (window_days >= 7 AND window_days <= 365)
) STRICT;
CREATE TABLE coverage_assignments (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  fixture_kind                             TEXT NOT NULL CHECK (fixture_kind IN ('own','friendly_board','open_trial')),
  fixture_id                               TEXT CHECK (fixture_id IS NULL OR length(fixture_id) <= 80 AND length(fixture_id) > 0),
  friendly_id                              TEXT CHECK (friendly_id IS NULL OR length(friendly_id) <= 80 AND length(friendly_id) > 0),
  open_trial_id                            TEXT CHECK (open_trial_id IS NULL OR length(open_trial_id) <= 80 AND length(open_trial_id) > 0),
  fixture_date                             TEXT NOT NULL CHECK (length(fixture_date) <= 10),
  fixture_label                            TEXT NOT NULL CHECK (length(fixture_label) <= 200 AND length(fixture_label) > 0),
  fixture_competition                      TEXT CHECK (fixture_competition IS NULL OR length(fixture_competition) <= 80 AND length(fixture_competition) > 0),
  scout_user_id                            TEXT NOT NULL CHECK (length(scout_user_id) <= 80 AND length(scout_user_id) > 0),
  scout_name                               TEXT CHECK (scout_name IS NULL OR length(scout_name) <= 200),
  travel_budget_minor                      INTEGER,
  travel_currency                          TEXT CHECK (travel_currency IS NULL OR travel_currency IN ('GBP','EUR','USD','CHF','SEK','NOK','DKK','PLN','BRL')),
  travel_entered_by_name                   TEXT CHECK (travel_entered_by_name IS NULL OR length(travel_entered_by_name) <= 200),
  assigned_by_name                         TEXT CHECK (assigned_by_name IS NULL OR length(assigned_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  observed_at                              INTEGER,
  assessment_id                            TEXT CHECK (assessment_id IS NULL OR length(assessment_id) <= 80 AND length(assessment_id) > 0),
  cancelled_at                             INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (fixture_id) REFERENCES fixtures(id) ON DELETE RESTRICT,
  FOREIGN KEY (scout_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (fixture_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  FOREIGN KEY (friendly_id) REFERENCES friendlies(id) ON DELETE RESTRICT,
  FOREIGN KEY (open_trial_id) REFERENCES open_trials(id) ON DELETE RESTRICT,
  CHECK ((fixture_kind = 'own') = (fixture_id IS NOT NULL)),
  CHECK ((fixture_kind = 'friendly_board') = (friendly_id IS NOT NULL)),
  CHECK ((fixture_kind = 'open_trial') = (open_trial_id IS NOT NULL)),
  CHECK ((travel_budget_minor IS NULL) = (travel_currency IS NULL)),
  CHECK (travel_budget_minor IS NULL OR travel_budget_minor >= 0),
  CHECK (travel_budget_minor IS NOT NULL OR travel_entered_by_name IS NULL),
  CHECK (assessment_id IS NULL OR observed_at IS NOT NULL)
) STRICT;
CREATE TABLE coverage_assignment_targets (
  assignment_id                            TEXT NOT NULL CHECK (length(assignment_id) > 0 AND length(assignment_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) > 0 AND length(player_id) <= 80),
  FOREIGN KEY (assignment_id) REFERENCES coverage_assignments(id) ON DELETE CASCADE,
  PRIMARY KEY (assignment_id, ord),
  UNIQUE (assignment_id, player_id)
) STRICT;
CREATE TABLE coverage_assignment_warnings (
  assignment_id                            TEXT NOT NULL CHECK (length(assignment_id) > 0 AND length(assignment_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  code                                     TEXT NOT NULL CHECK (code IN ('duplicate_visit','scout_clash')),
  scout_name                               TEXT CHECK (scout_name IS NULL OR length(scout_name) <= 200),
  FOREIGN KEY (assignment_id) REFERENCES coverage_assignments(id) ON DELETE CASCADE,
  PRIMARY KEY (assignment_id, ord),
  UNIQUE (assignment_id, code)
) STRICT;
CREATE TABLE import_batches (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  kind                                     TEXT NOT NULL CHECK (kind IN ('prospects')),
  created_by_user_id                       TEXT NOT NULL CHECK (length(created_by_user_id) <= 80 AND length(created_by_user_id) > 0),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  mapped                                   INTEGER NOT NULL CHECK (mapped IN (0,1)),
  status                                   TEXT NOT NULL CHECK (status IN ('validated','committed','reversed')),
  summary_total                            INTEGER NOT NULL,
  summary_creatable                        INTEGER NOT NULL,
  summary_errors                           INTEGER NOT NULL,
  summary_duplicates_in_file               INTEGER NOT NULL,
  summary_already_imported                 INTEGER NOT NULL,
  summary_linked_existing                  INTEGER NOT NULL,
  summary_ambiguous                        INTEGER NOT NULL,
  committed_at                             INTEGER,
  reversed_at                              INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (summary_total >= 0 AND summary_total <= 2000),
  CHECK (summary_creatable >= 0 AND summary_errors >= 0 AND summary_duplicates_in_file >= 0 AND summary_already_imported >= 0 AND summary_linked_existing >= 0 AND summary_ambiguous >= 0),
  CHECK (summary_total = summary_creatable + summary_errors + summary_duplicates_in_file + summary_already_imported + summary_linked_existing + summary_ambiguous),
  CHECK ((status = 'validated') = (committed_at IS NULL)),
  CHECK ((status = 'reversed') = (reversed_at IS NOT NULL))
) STRICT;
CREATE TABLE import_batch_columns (
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) > 0 AND length(batch_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  header                                   TEXT NOT NULL CHECK (length(header) <= 200),
  field                                    TEXT CHECK (field IS NULL OR field IN ('name','dob','position','foot','heightCm','provider','externalId','notes')),
  FOREIGN KEY (batch_id) REFERENCES import_batches(id) ON DELETE CASCADE,
  PRIMARY KEY (batch_id, ord)
) STRICT;
CREATE TABLE import_batch_rows (
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) > 0 AND length(batch_id) <= 80),
  row_no                                   INTEGER NOT NULL CHECK (row_no >= 2),
  record_name                              TEXT CHECK (record_name IS NULL OR length(record_name) <= 200),
  record_dob                               TEXT CHECK (record_dob IS NULL OR length(record_dob) <= 40),
  record_position                          TEXT CHECK (record_position IS NULL OR length(record_position) <= 20),
  record_foot                              TEXT CHECK (record_foot IS NULL OR length(record_foot) <= 20),
  record_height_cm                         TEXT CHECK (record_height_cm IS NULL OR length(record_height_cm) <= 20),
  record_provider                          TEXT CHECK (record_provider IS NULL OR length(record_provider) <= 80),
  record_external_id                       TEXT CHECK (record_external_id IS NULL OR length(record_external_id) <= 80),
  record_notes                             TEXT CHECK (record_notes IS NULL OR length(record_notes) <= 2000),
  disposition                              TEXT NOT NULL CHECK (disposition IN ('create','error','duplicate_in_file','already_imported','linked_player_exists','ambiguous_identity')),
  match_player_id                          TEXT CHECK (match_player_id IS NULL OR (length(match_player_id) > 0 AND length(match_player_id) <= 80)),
  FOREIGN KEY (batch_id) REFERENCES import_batches(id) ON DELETE CASCADE,
  PRIMARY KEY (batch_id, row_no),
  CHECK ((match_player_id IS NOT NULL) = (disposition IN ('linked_player_exists','ambiguous_identity')))
) STRICT;
CREATE TABLE import_batch_row_errors (
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) > 0 AND length(batch_id) <= 80),
  row_no                                   INTEGER NOT NULL,
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  message                                  TEXT NOT NULL CHECK (length(message) > 0 AND length(message) <= 300),
  FOREIGN KEY (batch_id, row_no) REFERENCES import_batch_rows(batch_id, row_no) ON DELETE CASCADE,
  PRIMARY KEY (batch_id, row_no, ord)
) STRICT;
CREATE TABLE import_batch_history (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) <= 80 AND length(batch_id) > 0),
  at                                       INTEGER NOT NULL,
  by_kind                                  TEXT NOT NULL CHECK (by_kind IN ('org_user')),
  by_user_id                               TEXT NOT NULL CHECK (length(by_user_id) <= 80 AND length(by_user_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  action                                   TEXT NOT NULL CHECK (action IN ('validated','committed','reversed')),
  created_count                            INTEGER,
  removed_count                            INTEGER,
  kept_count                               INTEGER,
  FOREIGN KEY (batch_id) REFERENCES import_batches(id) ON DELETE CASCADE,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK ((action = 'committed') = (created_count IS NOT NULL)),
  CHECK ((action = 'reversed') = (removed_count IS NOT NULL)),
  CHECK ((action = 'reversed') = (kept_count IS NOT NULL)),
  CHECK (created_count IS NULL OR created_count >= 0),
  CHECK (removed_count IS NULL OR (removed_count >= 0 AND kept_count >= 0))
) STRICT;
CREATE TABLE prospects (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) <= 80 AND length(batch_id) > 0),
  name                                     TEXT NOT NULL CHECK (length(name) <= 200 AND length(name) > 0),
  dob                                      TEXT CHECK (dob IS NULL OR length(dob) <= 10),
  position                                 TEXT CHECK (position IS NULL OR position IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  foot                                     TEXT CHECK (foot IS NULL OR length(foot) <= 20 AND length(foot) > 0),
  height_cm                                INTEGER,
  provider                                 TEXT NOT NULL CHECK (length(provider) <= 80 AND length(provider) > 0),
  external_id                              TEXT NOT NULL CHECK (length(external_id) <= 80 AND length(external_id) > 0),
  notes                                    TEXT CHECK (notes IS NULL OR length(notes) <= 2000 AND length(notes) > 0),
  minor                                    INTEGER CHECK (minor IS NULL OR minor IN (0,1)),
  created_at                               INTEGER NOT NULL,
  reversed_at                              INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (batch_id) REFERENCES import_batches(id) ON DELETE RESTRICT,
  CHECK (dob IS NULL OR dob GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
  CHECK (height_cm IS NULL OR (height_cm >= 100 AND height_cm <= 230))
) STRICT;
CREATE TABLE import_batch_created_prospects (
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) > 0 AND length(batch_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  prospect_id                              TEXT NOT NULL CHECK (length(prospect_id) > 0 AND length(prospect_id) <= 80),
  FOREIGN KEY (batch_id) REFERENCES import_batches(id) ON DELETE CASCADE,
  FOREIGN KEY (prospect_id) REFERENCES prospects(id) ON DELETE RESTRICT,
  PRIMARY KEY (batch_id, ord),
  UNIQUE (prospect_id)
) STRICT;
CREATE TABLE identity_reviews (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  batch_id                                 TEXT NOT NULL CHECK (length(batch_id) <= 80 AND length(batch_id) > 0),
  row_no                                   INTEGER NOT NULL,
  candidate_player_id                      TEXT NOT NULL CHECK (length(candidate_player_id) <= 80 AND length(candidate_player_id) > 0),
  status                                   TEXT NOT NULL CHECK (status IN ('open','resolved')),
  resolved_by_name                         TEXT CHECK (resolved_by_name IS NULL OR length(resolved_by_name) <= 200),
  resolved_at                              INTEGER,
  resolution                               TEXT CHECK (resolution IS NULL OR resolution IN ('linked','kept_separate')),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (batch_id, row_no) REFERENCES import_batch_rows(batch_id, row_no) ON DELETE RESTRICT,
  CHECK ((status = 'resolved') = (resolution IS NOT NULL)),
  CHECK ((status = 'resolved') = (resolved_at IS NOT NULL)),
  UNIQUE (batch_id, row_no)
) STRICT;
CREATE TABLE api_keys (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  key_hash                                 TEXT NOT NULL CHECK (length(key_hash) <= 64),
  label                                    TEXT NOT NULL CHECK (length(label) <= 60),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  revoked_at                               INTEGER,
  last_used_at                             INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (key_hash GLOB '[0-9a-f]*' AND length(key_hash) = 64),
  UNIQUE (key_hash)
) STRICT;
CREATE TABLE api_key_scopes (
  api_key_id                               TEXT NOT NULL CHECK (length(api_key_id) > 0 AND length(api_key_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  scope                                    TEXT NOT NULL CHECK (scope IN ('export:prospects','export:shortlist')),
  FOREIGN KEY (api_key_id) REFERENCES api_keys(id) ON DELETE CASCADE,
  PRIMARY KEY (api_key_id, ord),
  UNIQUE (api_key_id, scope)
) STRICT;
CREATE TABLE webhook_endpoints (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  url                                      TEXT NOT NULL CHECK (length(url) <= 2000 AND length(url) > 0),
  secret                                   TEXT NOT NULL CHECK (length(secret) <= 200 AND length(secret) > 0),
  secret_prev                              TEXT CHECK (secret_prev IS NULL OR length(secret_prev) <= 200 AND length(secret_prev) > 0),
  secret_prev_valid_until                  INTEGER,
  active                                   INTEGER NOT NULL CHECK (active IN (0,1)),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK ((secret_prev IS NULL) = (secret_prev_valid_until IS NULL))
) STRICT;
CREATE TABLE webhook_endpoint_events (
  endpoint_id                              TEXT NOT NULL CHECK (length(endpoint_id) > 0 AND length(endpoint_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  event                                    TEXT NOT NULL CHECK (event IN ('import.committed','identity.resolved','transition.granted','transition.revoked','delivery.failed')),
  FOREIGN KEY (endpoint_id) REFERENCES webhook_endpoints(id) ON DELETE CASCADE,
  PRIMARY KEY (endpoint_id, ord),
  UNIQUE (endpoint_id, event)
) STRICT;
CREATE TABLE webhook_deliveries (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  endpoint_id                              TEXT NOT NULL CHECK (length(endpoint_id) <= 80 AND length(endpoint_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  event_id                                 TEXT NOT NULL CHECK (length(event_id) <= 80 AND length(event_id) > 0),
  type                                     TEXT NOT NULL CHECK (type IN ('import.committed','identity.resolved','transition.granted','transition.revoked','delivery.failed')),
  subject_id                               TEXT NOT NULL CHECK (length(subject_id) <= 80 AND length(subject_id) > 0),
  created_count                            INTEGER,
  resolution                               TEXT CHECK (resolution IS NULL OR resolution IN ('linked','kept_separate')),
  status                                   TEXT NOT NULL CHECK (status IN ('queued','retrying','delivered','failed','abandoned')),
  next_at                                  INTEGER NOT NULL,
  created_at                               INTEGER NOT NULL,
  delivered_at                             INTEGER,
  FOREIGN KEY (endpoint_id) REFERENCES webhook_endpoints(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  UNIQUE (event_id),
  CHECK ((type = 'import.committed') = (created_count IS NOT NULL)),
  CHECK (created_count IS NULL OR created_count >= 0),
  CHECK ((type = 'identity.resolved') = (resolution IS NOT NULL)),
  CHECK ((status = 'delivered') = (delivered_at IS NOT NULL))
) STRICT;
CREATE TABLE webhook_delivery_attempts (
  delivery_id                              TEXT NOT NULL CHECK (length(delivery_id) > 0 AND length(delivery_id) <= 80),
  attempt_no                               INTEGER NOT NULL CHECK (attempt_no >= 1),
  attempted_at                             INTEGER NOT NULL,
  http_status                              INTEGER CHECK (http_status IS NULL OR (http_status >= 100 AND http_status <= 599)),
  error                                    TEXT CHECK (error IS NULL OR length(error) <= 200),
  FOREIGN KEY (delivery_id) REFERENCES webhook_deliveries(id) ON DELETE CASCADE,
  PRIMARY KEY (delivery_id, attempt_no),
  CHECK ((http_status IS NULL) <> (error IS NULL))
) STRICT;
CREATE TABLE org_invites (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  email                                    TEXT NOT NULL CHECK (length(email) <= 254 AND length(email) > 0),
  name                                     TEXT NOT NULL CHECK (length(name) <= 80 AND length(name) > 0),
  role                                     TEXT NOT NULL CHECK (length(role) <= 60 AND length(role) > 0),
  token_hash                               TEXT NOT NULL CHECK (length(token_hash) <= 64),
  status                                   TEXT NOT NULL CHECK (status IN ('pending','accepted','revoked','expired')),
  invited_by_name                          TEXT CHECK (invited_by_name IS NULL OR length(invited_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  accepted_at                              INTEGER,
  revoked_at                               INTEGER,
  user_id                                  TEXT CHECK (user_id IS NULL OR length(user_id) <= 80 AND length(user_id) > 0),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (length(token_hash) = 64 AND token_hash NOT GLOB '*[^0-9a-f]*'),
  CHECK ((status = 'accepted') = (accepted_at IS NOT NULL)),
  CHECK ((status = 'accepted') = (user_id IS NOT NULL)),
  CHECK ((status = 'revoked') = (revoked_at IS NOT NULL))
) STRICT;
CREATE TABLE sso_configs (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  issuer                                   TEXT NOT NULL CHECK (issuer IN ('local-test-idp')),
  client_id                                TEXT NOT NULL CHECK (length(client_id) <= 200 AND length(client_id) > 0),
  created_at                               INTEGER NOT NULL,
  updated_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  UNIQUE (org_id)
) STRICT;
CREATE TABLE sso_states (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  state_hash                               TEXT NOT NULL CHECK (length(state_hash) <= 64),
  nonce_hash                               TEXT NOT NULL CHECK (length(nonce_hash) <= 64),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  created_at                               INTEGER NOT NULL,
  expires_at                               INTEGER NOT NULL,
  used_at                                  INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (length(state_hash) = 64 AND state_hash NOT GLOB '*[^0-9a-f]*'),
  CHECK (length(nonce_hash) = 64 AND nonce_hash NOT GLOB '*[^0-9a-f]*')
) STRICT;
CREATE TABLE support_tickets (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  by_user_id                               TEXT NOT NULL CHECK (length(by_user_id) <= 80 AND length(by_user_id) > 0),
  by_name                                  TEXT CHECK (by_name IS NULL OR length(by_name) <= 200),
  subject                                  TEXT NOT NULL CHECK (length(subject) <= 160 AND length(subject) > 0),
  body                                     TEXT NOT NULL CHECK (length(body) <= 2000),
  status                                   TEXT NOT NULL CHECK (status IN ('open','closed')),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT
) STRICT;
CREATE TABLE support_ticket_refs (
  ticket_id                                TEXT NOT NULL CHECK (length(ticket_id) > 0 AND length(ticket_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  kind                                     TEXT NOT NULL CHECK (kind IN ('case','import')),
  ref_id                                   TEXT NOT NULL CHECK (length(ref_id) > 0 AND length(ref_id) <= 80),
  FOREIGN KEY (ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE,
  PRIMARY KEY (ticket_id, ord)
) STRICT;
CREATE TABLE support_ticket_replies (
  ticket_id                                TEXT NOT NULL CHECK (length(ticket_id) > 0 AND length(ticket_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  at                                       INTEGER NOT NULL,
  by_name                                  TEXT NOT NULL CHECK (length(by_name) > 0 AND length(by_name) <= 200),
  text                                     TEXT NOT NULL CHECK (length(text) > 0 AND length(text) <= 2000),
  FOREIGN KEY (ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE,
  PRIMARY KEY (ticket_id, ord)
) STRICT;
CREATE TABLE support_access_grants (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  ticket_id                                TEXT NOT NULL CHECK (length(ticket_id) <= 80 AND length(ticket_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  hours                                    INTEGER NOT NULL,
  status                                   TEXT NOT NULL CHECK (status IN ('requested','active')),
  requested_at                             INTEGER NOT NULL,
  approved_by_name                         TEXT CHECK (approved_by_name IS NULL OR length(approved_by_name) <= 200),
  approved_at                              INTEGER,
  expires_at                               INTEGER,
  FOREIGN KEY (ticket_id) REFERENCES support_tickets(id) ON DELETE RESTRICT,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (hours >= 1 AND hours <= 72),
  CHECK ((status = 'active') = (approved_at IS NOT NULL)),
  CHECK ((status = 'active') = (expires_at IS NOT NULL)),
  CHECK (status = 'active' OR approved_by_name IS NULL)
) STRICT;
CREATE TABLE support_access_log (
  grant_id                                 TEXT NOT NULL CHECK (length(grant_id) > 0 AND length(grant_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  at                                       INTEGER NOT NULL,
  what                                     TEXT NOT NULL CHECK (what IN ('org-records')),
  FOREIGN KEY (grant_id) REFERENCES support_access_grants(id) ON DELETE RESTRICT,
  PRIMARY KEY (grant_id, ord)
) STRICT;
CREATE TABLE groups (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  name                                     TEXT NOT NULL CHECK (length(name) <= 100 AND length(name) > 0),
  created_at                               INTEGER NOT NULL
) STRICT;
CREATE TABLE group_members (
  group_id                                 TEXT NOT NULL CHECK (length(group_id) > 0 AND length(group_id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) > 0 AND length(org_id) <= 80),
  admin                                    INTEGER NOT NULL CHECK (admin IN (0,1)),
  FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (group_id, org_id)
) STRICT;
CREATE TABLE group_pending_invites (
  group_id                                 TEXT NOT NULL CHECK (length(group_id) > 0 AND length(group_id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) > 0 AND length(org_id) <= 80),
  invited_by_org_id                        TEXT NOT NULL CHECK (length(invited_by_org_id) > 0 AND length(invited_by_org_id) <= 80),
  invited_at                               INTEGER NOT NULL,
  FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (invited_by_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (group_id, org_id)
) STRICT;
CREATE TABLE group_shared_templates (
  group_id                                 TEXT NOT NULL CHECK (length(group_id) > 0 AND length(group_id) <= 80),
  template_id                              TEXT NOT NULL CHECK (length(template_id) > 0 AND length(template_id) <= 80),
  FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE,
  PRIMARY KEY (group_id, template_id)
) STRICT;
CREATE TABLE group_programmes (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  group_id                                 TEXT NOT NULL CHECK (length(group_id) <= 80 AND length(group_id) > 0),
  name                                     TEXT NOT NULL CHECK (length(name) <= 100 AND length(name) > 0),
  region                                   TEXT CHECK (region IS NULL OR length(region) <= 80 AND length(region) > 0),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE
) STRICT;
CREATE TABLE group_grants (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  group_id                                 TEXT NOT NULL CHECK (length(group_id) <= 80 AND length(group_id) > 0),
  from_org_id                              TEXT NOT NULL CHECK (length(from_org_id) <= 80 AND length(from_org_id) > 0),
  from_org_name                            TEXT NOT NULL CHECK (length(from_org_name) <= 200),
  resource_kind                            TEXT NOT NULL CHECK (resource_kind IN ('shortlist','case','assessment')),
  resource_id                              TEXT NOT NULL CHECK (length(resource_id) <= 80 AND length(resource_id) > 0),
  expires_at                               INTEGER NOT NULL,
  revoked_at                               INTEGER,
  revoke_reason                            TEXT CHECK (revoke_reason IS NULL OR revoke_reason IN ('group_departure','revoked_by_owner')),
  created_by_name                          TEXT CHECK (created_by_name IS NULL OR length(created_by_name) <= 200),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE RESTRICT,
  FOREIGN KEY (from_org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  CHECK (resource_kind <> 'shortlist' OR resource_id = '*'),
  CHECK ((revoked_at IS NULL) = (revoke_reason IS NULL))
) STRICT;
CREATE TABLE group_grant_recipients (
  grant_id                                 TEXT NOT NULL CHECK (length(grant_id) > 0 AND length(grant_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) > 0 AND length(org_id) <= 80),
  FOREIGN KEY (grant_id) REFERENCES group_grants(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  PRIMARY KEY (grant_id, ord),
  UNIQUE (grant_id, org_id)
) STRICT;
CREATE TABLE open_trials (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  title                                    TEXT NOT NULL CHECK (length(title) <= 160 AND length(title) > 0),
  trial_date                               TEXT NOT NULL CHECK (length(trial_date) <= 10),
  venue                                    TEXT NOT NULL CHECK (length(venue) <= 160 AND length(venue) > 0),
  age_group                                TEXT NOT NULL CHECK (length(age_group) <= 40 AND length(age_group) > 0),
  notes                                    TEXT NOT NULL CHECK (length(notes) <= 2000),
  created_by_user_id                       TEXT NOT NULL CHECK (length(created_by_user_id) <= 80 AND length(created_by_user_id) > 0),
  created_at                               INTEGER NOT NULL,
  deleted_at                               INTEGER,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (created_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (trial_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')
) STRICT;
CREATE TABLE open_trial_positions (
  open_trial_id                            TEXT NOT NULL CHECK (length(open_trial_id) > 0 AND length(open_trial_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  position                                 TEXT NOT NULL CHECK (length(position) > 0 AND length(position) <= 40),
  FOREIGN KEY (open_trial_id) REFERENCES open_trials(id) ON DELETE CASCADE,
  PRIMARY KEY (open_trial_id, ord),
  UNIQUE (open_trial_id, position)
) STRICT;
CREATE TABLE open_trial_registrations (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  open_trial_id                            TEXT NOT NULL CHECK (length(open_trial_id) <= 80 AND length(open_trial_id) > 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  player_name                              TEXT CHECK (player_name IS NULL OR length(player_name) <= 200),
  by_guardian                              INTEGER NOT NULL CHECK (by_guardian IN (0,1)),
  guardian_id                              TEXT CHECK (guardian_id IS NULL OR length(guardian_id) <= 80 AND length(guardian_id) > 0),
  registered_at                            INTEGER NOT NULL,
  outcome                                  TEXT CHECK (outcome IS NULL OR outcome IN ('invite_trial','declined')),
  outcome_note                             TEXT CHECK (outcome_note IS NULL OR length(outcome_note) <= 200),
  outcome_at                               INTEGER,
  FOREIGN KEY (open_trial_id) REFERENCES open_trials(id) ON DELETE CASCADE,
  UNIQUE (open_trial_id, player_id),
  CHECK ((guardian_id IS NOT NULL) = (by_guardian = 1)),
  CHECK ((outcome IS NULL) = (outcome_at IS NULL)),
  CHECK (outcome IS NOT NULL OR outcome_note IS NULL)
) STRICT;
CREATE TABLE matchdays (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  fixture                                  TEXT NOT NULL CHECK (length(fixture) <= 160 AND length(fixture) > 0),
  venue                                    TEXT NOT NULL CHECK (length(venue) <= 160),
  match_date                               TEXT NOT NULL CHECK (length(match_date) <= 10),
  result                                   TEXT CHECK (result IS NULL OR length(result) <= 20 AND length(result) > 0),
  logged_by_user_id                        TEXT NOT NULL CHECK (length(logged_by_user_id) <= 80 AND length(logged_by_user_id) > 0),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (logged_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (match_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')
) STRICT;
CREATE TABLE matchday_players (
  matchday_id                              TEXT NOT NULL CHECK (length(matchday_id) > 0 AND length(matchday_id) <= 80),
  ord                                      INTEGER NOT NULL CHECK (ord >= 0),
  player_id                                TEXT NOT NULL CHECK (length(player_id) > 0 AND length(player_id) <= 80),
  FOREIGN KEY (matchday_id) REFERENCES matchdays(id) ON DELETE CASCADE,
  PRIMARY KEY (matchday_id, ord),
  UNIQUE (matchday_id, player_id)
) STRICT;
CREATE TABLE friendlies (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  posted_by_user_id                        TEXT NOT NULL CHECK (length(posted_by_user_id) <= 80 AND length(posted_by_user_id) > 0),
  age_group                                TEXT NOT NULL CHECK (length(age_group) <= 40 AND length(age_group) > 0),
  match_date                               TEXT NOT NULL CHECK (length(match_date) <= 10),
  venue                                    TEXT NOT NULL CHECK (length(venue) <= 160),
  notes                                    TEXT NOT NULL CHECK (length(notes) <= 2000),
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (posted_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (match_date GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]')
) STRICT;
CREATE TABLE friendly_responses (
  friendly_id                              TEXT NOT NULL CHECK (length(friendly_id) <= 80 AND length(friendly_id) > 0),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  message                                  TEXT NOT NULL CHECK (length(message) <= 200),
  responded_by_user_id                     TEXT NOT NULL CHECK (length(responded_by_user_id) <= 80 AND length(responded_by_user_id) > 0),
  responded_at                             INTEGER NOT NULL,
  FOREIGN KEY (friendly_id) REFERENCES friendlies(id) ON DELETE CASCADE,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (responded_by_user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  PRIMARY KEY (friendly_id, org_id)
) STRICT;
CREATE TABLE upload_sessions (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  player_id                                TEXT NOT NULL CHECK (length(player_id) <= 80 AND length(player_id) > 0),
  size_bytes                               INTEGER NOT NULL,
  mime                                     TEXT NOT NULL CHECK (mime IN ('video/webm','video/mp4','video/quicktime','image/jpeg','image/png','image/webp')),
  title                                    TEXT NOT NULL CHECK (length(title) <= 120 AND length(title) > 0),
  declared_sha256                          TEXT CHECK (declared_sha256 IS NULL OR length(declared_sha256) <= 64),
  chunk_size                               INTEGER NOT NULL,
  total_chunks                             INTEGER NOT NULL,
  status                                   TEXT NOT NULL CHECK (status IN ('open','finalised','aborted','abandoned')),
  created_at                               INTEGER NOT NULL,
  finalised_media_id                       TEXT CHECK (finalised_media_id IS NULL OR length(finalised_media_id) <= 80 AND length(finalised_media_id) > 0),
  CHECK (size_bytes > 0 AND size_bytes <= 41943040),
  CHECK (chunk_size > 0),
  CHECK (total_chunks >= 1 AND total_chunks <= 1024),
  CHECK (declared_sha256 IS NULL OR length(declared_sha256) = 64),
  CHECK ((status = 'finalised') = (finalised_media_id IS NOT NULL))
) STRICT;
CREATE TABLE upload_session_chunks (
  upload_session_id TEXT NOT NULL CHECK (length(upload_session_id) > 0 AND length(upload_session_id) <= 80),
  chunk_index INTEGER NOT NULL CHECK (chunk_index >= 0),
  FOREIGN KEY (upload_session_id) REFERENCES upload_sessions(id) ON DELETE CASCADE,
  PRIMARY KEY (upload_session_id, chunk_index)
) STRICT;
CREATE TABLE saved_searches (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  user_id                                  TEXT NOT NULL CHECK (length(user_id) <= 80 AND length(user_id) > 0),
  name                                     TEXT NOT NULL CHECK (length(name) <= 120 AND length(name) > 0),
  q                                        TEXT CHECK (q IS NULL OR length(q) <= 120 AND length(q) > 0),
  position                                 TEXT CHECK (position IS NULL OR position IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  foot                                     TEXT CHECK (foot IS NULL OR foot IN ('left','right')),
  availability                             TEXT CHECK (availability IS NULL OR availability IN ('available_now','end_of_season','loan_open','overseas_open','not_seeking')),
  country                                  TEXT CHECK (country IS NULL OR length(country) <= 60 AND length(country) > 0),
  academy_plus                             INTEGER CHECK (academy_plus IS NULL OR academy_plus IN (0,1)),
  age_group                                TEXT CHECK (age_group IS NULL OR age_group IN ('u16','u18','18-21','senior')),
  new_days                                 INTEGER,
  created_at                               INTEGER NOT NULL,
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (user_id) REFERENCES org_users(id) ON DELETE RESTRICT,
  CHECK (new_days IS NULL OR (new_days >= 1 AND new_days <= 3650)),
  CHECK (academy_plus IS NULL OR academy_plus = 1)
) STRICT;
CREATE TABLE invoices (
  id                                       TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  created_at                               INTEGER NOT NULL,
  org_id                                   TEXT NOT NULL CHECK (length(org_id) <= 80 AND length(org_id) > 0),
  org_name                                 TEXT NOT NULL CHECK (length(org_name) <= 200),
  signing_id                               TEXT NOT NULL CHECK (length(signing_id) <= 80 AND length(signing_id) > 0),
  player_name                              TEXT NOT NULL CHECK (length(player_name) <= 200),
  description                              TEXT NOT NULL CHECK (length(description) <= 300),
  amount_minor                             INTEGER NOT NULL,
  currency                                 TEXT NOT NULL CHECK (length(currency) <= 3),
  status                                   TEXT NOT NULL CHECK (status IN ('issued')),
  provider                                 TEXT NOT NULL CHECK (provider IN ('dev-ledger','stripe')),
  FOREIGN KEY (org_id) REFERENCES orgs(id) ON DELETE RESTRICT,
  FOREIGN KEY (signing_id) REFERENCES signings(id) ON DELETE RESTRICT,
  CHECK (amount_minor >= 0),
  CHECK (currency GLOB '[A-Z][A-Z][A-Z]')
) STRICT;
CREATE TABLE reputation_seed (
  scout_name                               TEXT NOT NULL CHECK (length(scout_name) <= 200 AND length(scout_name) > 0),
  org_name                                 TEXT NOT NULL CHECK (length(org_name) <= 200 AND length(org_name) > 0),
  discoveries                              INTEGER NOT NULL,
  success_rate_pct                         INTEGER NOT NULL,
  avg_resale_multiple                      REAL NOT NULL,
  PRIMARY KEY (scout_name, org_name),
  CHECK (discoveries >= 0),
  CHECK (success_rate_pct BETWEEN 0 AND 100),
  CHECK (avg_resale_multiple >= 0)
) STRICT;
CREATE TABLE delivery_callbacks_seen (
  callback_id TEXT PRIMARY KEY CHECK (length(callback_id) > 0 AND length(callback_id) <= 200),
  seen_at INTEGER NOT NULL
) STRICT;
CREATE TABLE delivery_centre (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  since INTEGER NOT NULL
) STRICT;
CREATE TABLE delivery_fail_injections (
  channel TEXT PRIMARY KEY CHECK (channel IN ('email','push','contact','trial','decision')),
  remaining INTEGER NOT NULL CHECK (remaining >= 0)
) STRICT;
CREATE TABLE counters (
  name  TEXT PRIMARY KEY CHECK (length(name) BETWEEN 1 AND 40),
  value INTEGER NOT NULL CHECK (value >= 0)
) STRICT;
CREATE TABLE player_match_facts (
  player_id         TEXT PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE,
  name_key          TEXT NOT NULL CHECK (length(name_key) <= 120),
  position          TEXT CHECK (position IS NULL OR position IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  availability      TEXT CHECK (availability IS NULL OR length(availability) BETWEEN 1 AND 40),
  trust_band        TEXT CHECK (trust_band IS NULL OR trust_band IN ('limited_evidence','developing_evidence','established_evidence','strong_evidence','very_strong_evidence')),
  last_evidence_at  INTEGER CHECK (last_evidence_at IS NULL OR last_evidence_at > 0),
  last_footage_at   INTEGER CHECK (last_footage_at IS NULL OR last_footage_at > 0),
  coach_reference   INTEGER NOT NULL CHECK (coach_reference IN (0, 1)),
  club_confirmed    INTEGER NOT NULL CHECK (club_confirmed IN (0, 1)),
  refresh_due_at    INTEGER,
  refreshed_at      INTEGER NOT NULL
) STRICT;
CREATE TABLE player_match_fact_positions (
  player_id         TEXT NOT NULL REFERENCES player_match_facts(player_id) ON DELETE CASCADE,
  ord               INTEGER NOT NULL CHECK (ord >= 0 AND ord < 3),
  code              TEXT NOT NULL CHECK (code IN ('GK','CB','RB','LB','RWB','LWB','CDM','CM','CAM','RW','LW','ST','CF')),
  PRIMARY KEY (player_id, ord)
) STRICT;
CREATE TABLE player_match_fact_combine (
  player_id         TEXT NOT NULL REFERENCES player_match_facts(player_id) ON DELETE CASCADE,
  protocol_id       TEXT NOT NULL CHECK (length(protocol_id) BETWEEN 1 AND 80),
  best_value        REAL,
  PRIMARY KEY (player_id, protocol_id)
) STRICT;
CREATE TABLE player_match_facts_dirty (
  player_id         TEXT PRIMARY KEY
) STRICT;
CREATE TABLE upload_intents (
  id          TEXT PRIMARY KEY CHECK (length(id) > 0 AND length(id) <= 80),
  purpose     TEXT NOT NULL CHECK (purpose IN ('player_clip','verification_evidence','signing_document')),
  owner_kind  TEXT NOT NULL CHECK (owner_kind IN ('player','org_user','applicant')),
  owner_id    TEXT NOT NULL CHECK (length(owner_id) > 0 AND length(owner_id) <= 80),
  size_bytes  INTEGER NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 41943040),
  mime        TEXT NOT NULL CHECK (length(mime) > 0 AND length(mime) <= 100),
  sha256      TEXT NOT NULL CHECK (length(sha256) = 64),
  status      TEXT NOT NULL CHECK (status IN ('open','used','expired')),
  created_at  INTEGER NOT NULL,
  expires_at  INTEGER NOT NULL,
  record_id   TEXT CHECK (record_id IS NULL OR length(record_id) > 0 AND length(record_id) <= 80),
  used_at     INTEGER, removed_at INTEGER CHECK (removed_at IS NULL OR status = 'expired'),
  CHECK ((status = 'used') = (record_id IS NOT NULL)),
  CHECK ((status = 'used') = (used_at IS NOT NULL))
) STRICT;
