CREATE TRIGGER match_facts_players_insert AFTER INSERT ON players BEGIN
  INSERT INTO player_match_facts_dirty (player_id) SELECT pid FROM (SELECT NEW.id AS pid) WHERE pid IS NOT NULL AND pid NOT IN (SELECT player_id FROM player_match_facts_dirty);
END;
CREATE TRIGGER match_facts_players_update AFTER UPDATE OF name, position, availability, identity_verified, birth_date, country, deleted_at ON players WHEN OLD.name IS NOT NEW.name OR OLD.position IS NOT NEW.position OR OLD.availability IS NOT NEW.availability OR OLD.identity_verified IS NOT NEW.identity_verified OR OLD.birth_date IS NOT NEW.birth_date OR OLD.country IS NOT NEW.country OR OLD.deleted_at IS NOT NEW.deleted_at BEGIN
  INSERT INTO player_match_facts_dirty (player_id) SELECT pid FROM (SELECT OLD.id AS pid UNION SELECT NEW.id AS pid) WHERE pid IS NOT NULL AND pid NOT IN (SELECT player_id FROM player_match_facts_dirty);
END;
