CREATE TRIGGER match_facts_orgs_update AFTER UPDATE OF verified, suspended, verification_revoked_at ON orgs WHEN OLD.verified IS NOT NEW.verified OR OLD.suspended IS NOT NEW.suspended OR OLD.verification_revoked_at IS NOT NEW.verification_revoked_at BEGIN
  INSERT INTO player_match_facts_dirty (player_id) SELECT pid FROM (SELECT player_id AS pid FROM org_squad_members WHERE org_id = OLD.id UNION SELECT player_id AS pid FROM ver_player_invites WHERE org_id = OLD.id UNION SELECT player_id AS pid FROM signings WHERE org_id = OLD.id UNION SELECT player_id AS pid FROM assessments WHERE org_id = OLD.id UNION SELECT subject_id AS pid FROM ver_claims WHERE organisation_id = OLD.id UNION SELECT player_id AS pid FROM org_squad_members WHERE org_id = NEW.id UNION SELECT player_id AS pid FROM ver_player_invites WHERE org_id = NEW.id UNION SELECT player_id AS pid FROM signings WHERE org_id = NEW.id UNION SELECT player_id AS pid FROM assessments WHERE org_id = NEW.id UNION SELECT subject_id AS pid FROM ver_claims WHERE organisation_id = NEW.id) WHERE pid IS NOT NULL AND pid NOT IN (SELECT player_id FROM player_match_facts_dirty);
END;
COMMIT;
